/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150303-3","meetingId":"h27-c-budget","date":"2015年3月3日","dateIso":"2015-03-03","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２７年度品川区一般会計予算","agenda":"平成２７年度品川区一般会計予算","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"始めします。８４ページの国庫支出金、国庫補助金は、マイナンバー制度のところ。そして、１２４ページは地域振興寄附金と伺っていきます。今までこの間、品川区はどのような取組みを行っていて、どのような進捗状況にあって、平成２８年１月のカード交付に向けて、どのように進めていくか、まずご説明ください。","respondent":"秋山情報システム課長","answer":"は通知カードというのを区民の方にお知らせします。そこに向けての改修を、今やっているです。現状としましては、なかなか国の情報が出てこないという中で、細部を詰め切れていない部分はありますけれども、その中で着実に進めているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"今ありました通知カードは、全国民に郵送で送付されるということですから、当然、品川区民全員にも郵送された後に、申請に合わせて個人番号カードをつくるという流れになると思います。ここで運用する仕組みは、各自治体によって違うということはないのでしょうか。その確認をさせてください。","respondent":"秋山情報システム課長","answer":"ただ、それぞれ自治体が持っているシステムというのは違ってありますので、それに合わせての改修の中身については、それぞれの自治体が行っていくということになります。ただ、国が示しているスケジュールにはきちんと合わせていくという考えでやっているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡部委員","kind":"確認","question":"それはわかるのです。そういうものなのかどうなのかという確認をしたかったのです。","respondent":"秋山情報システム課長","answer":"カードについて、例で言うと、図書館のカードですとか、印鑑登録のカードですとか、いろいろ自治体が発行しているものがあります。その辺を載せていくかどうかというのは、独自利用という範疇になりますので、条例で定めた上で、それを使っていくということになると思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡部委員","kind":"確認","question":"その辺の確認も含めてだったのです。少し先の話になりますが、プレス発表で、平成２８年９月から、コンビニエンスストアで電子カードをお持ちの方が住民票の写、そして印鑑登録証明書が取れますと書かれている中で、さまざまなコンビニエンスストア等が日本全国にあります。もしその辺の説明がわかればお願いしたいのです。","respondent":"秋山情報システム課長","answer":"これは、自治体がシステムを整備することによって、住まわれている方の住民票の写等がコンビニエンスストア全体で出せるという仕組みを国がつくっていますので、その仕組みに区として載るかどうかというところで、全国で受けることができるということになっております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"そうしますと、こちらのプレス発表で出ている中で、区来庁者の６５％の方が、この辺の発行で来られるということです。もしくは、同様に地域センター等におきましても、この辺の発行事務はやっているわけですから、そのご利用者の方々が減っていくのかということが予測され、数字で見てとれますけど、その辺を考えますと、例えば、現状の配置が平成２８年９月以降、どのような形になっていくのかということ。","respondent":"秋山情報システム課長","answer":"ただ、どのぐらいが実際に減るのかということは、今の時点では想定の段階です。ただ、そういう方向で行きますので、窓口の配置については考えていかなければならないという認識は持ってあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"この住基カードというのを品川区でずっと発行を続けていまして、本年度も７５ページの発行手数料を見ますと、２,５００件が見込まれている。今発行しても、その後１０年間使えるということは、逆に申しますと、品川区の中で１０年間、住基カードの仕組みと、マイナンバーの仕組みが並行していくのか。この辺の関係、考え方を教えてください。","respondent":"秋山情報システム課長","answer":"住基カードをお持ちの方には、個人番号カードに切替えをというＰＲを、今後していくことになろうかと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後にします。今言いました住基カードをお持ちの方は、１０年間使えるというところもありますけれども、このように変わっていきますという周知、説明等をしっかり丁寧に、平成２７年度が始まりますので、事あるごとに進めていただきたいと思います。次に寄附金です。５０万円を上限に、３分の２まで出ます。この地域振興寄附金の運用性について教えていただければと思います。","respondent":"河内協働・国際担当課長","answer":"専門員が、まずは事業継続性につきまして、さまざまな支援や、八潮に交流スペースがありますが、他の団体の意見などを聞きながら、継続してやっていく方法がないか、資金の調達を行えないかということを検討した上で、さらにその事業の一貫性ではないのですが。","voiceIndex":16,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"意外とこのような仕組みがあることを知らない方も多いかと思います。ぜひ周知していただいて、今ありましたように、４月から事前の打ち合わせ等をして、６月、７月とスケジュールが示されています。できれば年間を通して、いろいろなさっていたほうがいいと思うのですけれども、今の仕組みだとそこまで行かないかと思うのですが、どうでしょうか。","respondent":"河内協働・国際担当課長","answer":"募集期間につきましては、委員がおっしゃられたとおりで、４月から募集を開始いたしまして、審査会を経まして、秋口前ということで、こちらの助成事業につきましては、年内行う事業という制約がありますが、ご案内や説明、相談につきましては。","voiceIndex":18,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"私からは、１２２ページ、財産運用収入、１２４ページ、寄附金、時間があれば、特別区民税をお聞きしたいと思います。財産運用収入について、まずお聞きします。基金の運用の利回りについてでありますが、平成２６年度、マイナス１４７万６,０００円となっております。基金ごとのそれぞれの利回りの現状のあたり、また品川区の運用方針について、改めて教えていただければと思います。","respondent":"久保田会計管理者","answer":"公金の運用方針です。できるだけ安定した基金の運用をするというのが、まず基本原則です。そういう中で、各基金の運用については、企画財政課から一つの考え方が示されまして、その範囲の中で、私ども会計管理室が運用するということになってあります。","voiceIndex":21,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"各基金の利回りをお聞きしたのですが、基金ごとがわからなければ、全体のものを、後でわかれば教えていただきたいと思います。私も研究過程でありますので、ご教示いただきながらという形の質問になると思います。報道によりますと、一昨年になりますか。大分県の国東市の報道がありました。５自治体ぐらいが受賞されたそうです。この辺の考え方として教えてください。","respondent":"久保田会計管理者","answer":"万が一の場合に、取り崩す可能性もあるということで、２年の国債を買うとか、あるいは長くても５年ぐらいという形での短期の購入の考え方を持ってあります。","voiceIndex":23,"id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"私も研究しながらの質問なので、何か提案ができればいいのですが、自治体でさまざまな努力をされながら、先ほど申し上げた収益性という部分についての観点も、今後は必要なのかというところで、また改めて機会を捉えて、このあたりについては質問していきたいと思います。それに該当するような基金が品川区にはないと認識しておりますけれども、その辺の確認をさせてください。","respondent":"本城企画財政課長","answer":"基金につきましては、各基金ありますが、それぞれの基金目的に即した形で有効に活用していくのが現状だと考えております。そういう意味で、不要であるから返すということではなくて、今の段階で確実に、適切に運用できていると考えているものです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"今の質問は確認でしたので、ありがとうございました。次に行かせていただきたいと思います。１２４ページ、寄附金です。時間の関係で、ふるさと納税についてです。これまでの提案も含めて、各委員からありました。現在の品川区のふるさと納税の状況を改めて教えていただきたいと思います。","respondent":"江部総務課長","answer":"昨年１１月の決算特別委員会でもご答弁させていただいた内容ですが、品川区にふるさと納税という形でお預けいただきました人数、金額につきましては、厳密にというわけではありませんが、８名で５３４万８,０００円という数字を押さえております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"こうした現状がある中で、地域でご要望の多いご意見として、お散歩やお買い物の途中などで少し休める場所、腰かける場所を増やしてほしいという声をよく聞きます。協力金が１件当たり５万円となっています。そうすれば、ふるさと納税という視点でも、これについて理解をいただいて、ふるさと納税の額が増えていくということになるのではないかと思いますけれども、この辺についてはいかがでしょうか。","respondent":"黒田税務課長","answer":"いわゆるふるさと納税におけます返礼品の送付への対応についてということですが、先ほど委員からご指摘がありましたように、返礼品合戦になっているという側面がありまして、総務省から「返礼品に関しては。","voiceIndex":31,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"品川区をふるさととしていただける方が全国にたくさんいると、それはそれですばらしいことだという観点で、まさにふるさとで思い起こすと、どうしても高齢者の方々が暮らしよい生活をし続けていただくという観点では、要望として地域の中で少し休める、そして団らんできるという場をつくってもらうということも、非常に大事な観点かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"私からは、８５ページの生活困窮者自立支援事業について、もう一つが、先ほど新規事業であるとおっしゃっていたのですが、１１２ページの歩行者用観光案内標識設置事業補助金について、１１８ページのオリンピック・パラリンピック教育推進校委託金について伺いたいと思います。東京都の補助金でも１５７万１,０００円についてもあわせて伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"２番目の充当事業は、区で実施します任意事業であります就労準備支援事業と、あとは家計管理支援、そして一番下が生活保護でやっておりますけれども、子ども家庭支援事業への充当です。","voiceIndex":38,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"話を変えますけれども、その中で、品川区内にどのくらいの方が対象になられており、生活保護者の中から、もしかしたら生活困窮者になられる方もいらっしゃるかもしれませんけれども、そうしたことについて、人数のある程度の予測はできているのか、伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"実際には、そこまでの人数が積極的に相談に来るということはなかなか考えにくいかと思いますので、そこまで行かないのかと思いますけれども、ある程度の方に対しては支援していかなければいけないということで想定しています。","voiceIndex":40,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"先ほども言われました、約１,１００人ほど対象になるということであります。そうした中で、品川区での職員とか、対応とかは、生活保護のほうでもあると思うのですけれども、これは新たに課をつくるのか、どのような形で対処していくのか。何人ぐらいの職員の方々が対応していくのか。少し伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"体制のご質問ですけれども、自立相談支援員ということで、６名を配置しようかと考えています。就労支援員ということで、１名の配置を現状で考えております。その体制で、一応、先ほどの対象人数ですけれども、それで対応していこうと現状では考えているところです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"今年の４月から始まります事業ですので、しっかりと取り組んでいただければと思います。次に、１１２ページの歩行者用観光案内標識設置事業補助金について伺います。これも同じように、充当事業である観光アクションプラン推進事業のうち、また補助基本額が２つあるのですが、この内容を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"こちらに２基、それから、それ以外の道路等に設置する場合は、半分の補助ということになっておりますので、そちらで２基と予定しています。","voiceIndex":44,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"新規ではなく、復活したということだったので、品川区に多くの観光名所があると思いますけれども、これまで標識の設置数や、今後、観光案内標識を設置していきたい場所などがわかりましたら教えていただけたらと思います。","respondent":"米田商業・観光課長","answer":"今年度につきましては、武蔵小山からスクエア荏原を経て、戸越銀座に向かうルートのところに２カ所、それから、北品川、東品川にかけて、駅から桟橋等に向かうところに２カ所ということで検討を進めております。","voiceIndex":46,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"１１８ページのオリンピック・パラリンピック教育推進校委託についてですが、そうした中で、品川区内にそうした推進校が５校あるとお聞きしております。この事業について、今後、どのような形でオリンピック・パラリンピックへ向けてしっかりと取り組んでいくのか、改めて伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"これにつきましては、この推進校を中心に、また品川区内の各小学校、中学校でも、この活動については、ぜひ報告しながら、より一層充実していきたいと考えております。","voiceIndex":50,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１２２ページの財産収入、旧第一日野小学校跡地の賃料収入について伺いたいと思います。この契約の中身がいつまでなのか、そこを確認したいと思います。平成２８年度をめどに着工という日時に変更はあるのかないのか、伺いたいと思います。いろいろパーテーションとかあるそうなのですけれども、全体で何人規模のイベントホールになるのか、建物をご説明いただきたいと思います。","respondent":"立川経理課長、溝口都市開発課長","answer":"そこでの説明によりますと、工期としましては１月末から９月までで、建物の概要ですけれども、計画施設として、鉄骨造りで約４,０００平米弱の建物を建てるということで、現在建設中です。現在、ＴＯＣとまちづくりに向けて、さまざま協議をしているところであります。そういった中で、今のところ、ＴＯＣから聞いている話では、平成２８年８月から工事に着手するということで変わりはないと聞いております。","voiceIndex":53,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"旧第一日野小学校跡地にできるＴＯＣの建物について、イベントホールが何人規模なのか、そこを伺いたいと思います。再開発の手続を考えますと、平成２８年度をめどに着工という説明であれば、そろそろどんなＴＯＣの自社ビルの建替え再開発になるのか、区に説明があるかと思うのですけれども、スケジュールやオフィスビルなのか、マンションなのか、用途が何なのか、そこを伺いたいと思います。","respondent":"溝口都市開発課長、柏原行財政改革担当課長","answer":"私どもが先ほどお話しした着手の時期、平成２８年度８月というのは、解体に入る期間と認識しているものです。ですから、それから解体、本体工事へ入っていくと聞いているものです。旧第一日野小学校跡地にできる仮設の建物のイベントホールという言い方が正しいかどうかはわからないのですけれども、一応、こちらで聞いていますのは、大きな区画ができるお部屋ということで、３,０００平米ほどのお部屋がある。","voiceIndex":56,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"ＴＯＣの再開発が、今の説明ですと、オフィスビルになるということなのでしょうか。先ほど伺ったのは、この再開発計画が遅れた場合に、このまま区は土地を貸し続けるのか、それとも、やめるのか、この点について、現状のお考えをはっきり伺いたいと思います。何で２カ所目の催事場を区が提供しなければならないのか、そこを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"そういった状況で動いていると私どもは認識しています。","voiceIndex":59,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"つまり、平成２８年度をめどに着工と、先ほどの説明では解体が始まるということです。これが守られなくても、様子を見るということなのでしょうか。それとも、平成２８年度をめどに着工が守られなければ、もう旧第一日野小学校跡地をＴＯＣに貸すのをやめるということなのか、ここの考えをしっかり伺いたいと思います。この計画を中止するということになるのかを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"期間を決めてですので、ＴＯＣからその計画が変わったりというところは聞いてございませんので、その方向で進んでいるという認識です。いずれにいたしましても、ＴＯＣは工事の着工に向けて、今進めていると聞いてありますので、その辺を強く進めてもらうように話をしながらです。","voiceIndex":61,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"この間も、たびたび遅れているだけに、私が伺っているのは、平成２８年度をめどに着工という約束が破られた場合は、貸し付けの計画をやめる考えはあるのかないのか、ここをはっきりとご説明いただきたいと思います。このまちづくり全体の計画そのものが、今、宙に浮いているのではないか、頓挫しているのではないかと思うのですけれども、この点もあわせて伺いたいと思います。","respondent":"柏原行財政改革担当課長、溝口都市開発課長","answer":"前段の部分のご質問です。繰り返しの部分がありますけれども、現段階でＴＯＣから何か変更があったというところではございません。そういったものの更新時期です。そういったものを適正に誘導しながらということで進めてきているビジョンですので、ビジョンについては一定の成果を上げながら、さまざまなまちづくりを今後も進めていきたいと考えているものです。","voiceIndex":63,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"旧第一日野小学校の跡地は、既に小・中一貫校の建設で第一日野小学校が移転してからも、何年もたっております。都市部の貴重な土地を先の見えない計画や具体化が進まない、いわば塩漬け状態にするのではなくて、保育園や特別養護老人ホームなど、今こそ住民要望に充てるべきだと強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"藤原委員","kind":"確認","question":"５点お伺いします。その確認がまず１点。これは変わるのでしょうか。毎回お伺いしているのですけれども、基金を取り崩すのか、一般財源を使うのか、積み増しをするのか、その加減がどうなっているのかが、どうしてもよくわからないもので、ここは、この予算特別委員会でしっかり教えていただいて、４期目の節目にしたいと思いますので、よろしくお願いいたします。この５点をお伺いします。","respondent":"今井制度改革・待機児童対策担当課長、山崎ものづくり・経営支援課長、永尾高齢者福祉課長、本城企画財政課長、鈴木防災課長","answer":"初めに、保育園保育料と幼稚園保育料の関係につきましては、まず、区立幼稚園につきましては、現行のまま新制度に移行してまいりまして。括弧書きになりますけれども、利用料金収入見込額というところで、９,４００万円余の金額を書いております。平成７年入学生から、平成２２年入学生まで、合計いたしまして、２億８,１６８万４,３３０円となっております。ただ、当初はこのような形で計上させていただいているというものです。","voiceIndex":68,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"介護福祉専門学校の件です。私はこの施策を評価しております。課長は、いわゆる貸付金の数字を見て、介護士という意味において、通常、どう思っているか。今後、このことに対しての対策、施策をどう考えているのか、お伺いします。","respondent":"永尾高齢者福祉課長","answer":"これから、高齢者がどんどん増える中で、やはり介護人材は大切にしていかなければいけないので、この学校の運営の支援はこれからも続けていきたいと考えています。","voiceIndex":74,"id":"exchange-028"},{"speaker":"吉田委員","kind":"意見","question":"私からは、１３４ページの競馬組合配分金、１３７ページの各種事業参加費負担金の中の健康塾参加費をお尋ねしてまいりたいと思います。平成２５年は３億４,５００万円、平成２６年度は３億４,０３６万円、そして、平成２７年度は３億３,３４０万円と下がっております配分金というものを、改めてご説明いただき、また年々下がっている数字のご説明を先にお願いいたします。","respondent":"江部総務課長","answer":"減っております理由は、５号交付金が要因でございまして、来場者が減っているということで、要は、そこに行って、買って、その数字が交付金となるということなので、現地での売上を左右いたします来場者数の減少が理由であると認識しております。","voiceIndex":79,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"以前、我が会派の中から、集客についての質問の答弁で、特別区競馬組合からの振興策としまして、「１つに外国人の観光客の誘致に対する東京の夜の楽しみとしてトゥインクルレースの周知。この情報がございましたら、今現在どうなっているかを教えてください。","respondent":"江部総務課長","answer":"既に数年前からホームページ上では３カ国語の広報をしているです。お尋ねのパンフレットにつきましては、現在どこに置いてもらうかや、配布設置場所等の検討をしていて、まだ利用段階ではないと聞いております。掲示板ということについては、私どもでは情報を持っておりません。","voiceIndex":81,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"設置場所というのは、つくってあれば、どこにでも設置していただけるのではないかと思うのですけれども、その辺を、ぜひ品川区でも申し入れていただきたいのです。区長杯。平成２５年ですけれども、「スマイルシティ・品川特別」。先ほどお話しいただきました、外国人向けのいろいろなものを取り扱っているのと、また、今回の区長杯などの効果は何かございましたでしょうか。ぜひその辺を教えてください。","respondent":"江部総務課長","answer":"平成２５年度から始まりまして、今年度で２度開催しております。具体的な数字を持ち合わせておりませんけれども、区長賞レースと銘打ちますと、それなりに来場者が増え、それなりに配当金額が上がっているです。来場者を増やすさまざまな取組みの一つと認識しております。","voiceIndex":83,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"平成２５年の予算特別委員会で、大沢委員から、「今後の若者の世代、どんどんこういうギャンブルから離れていくような文化の気風すらありますので、そこらを何か策を講じていただきたい」という指摘がありました。これは、どういうターゲットなのか。せっかく地元にあるのですから、地域での活用、防災、そして、区全体の利用なども、地域貢献の観点から、その４点なのですが、お考えをお聞かせください。","respondent":"江部総務課長","answer":"来場者を増やすということを課題と競馬組合と認識していることから、数年前からターゲットを若者と女性に絞りまして、先ほどご紹介ありました「夜遊びしようぜ」ということで、イメージキャラクターで若い俳優の三浦春馬さんとか、香里奈さんを使って広報しているということで。","voiceIndex":85,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"ＰＲは、主催が競馬組合の中かもしれないのですけれども、品川区に競馬場はあります。ですから、しっかり組合に意見を言っていただいて、区の利用法、さらに集客率が上がるということは、区内に大勢の方が見えて、また、さまざまな相乗効果もあると思いますので、ぜひご意見を言っていただきたいと思います。その辺、最後に１点お願いします。","respondent":"江部総務課長","answer":"大井競馬場は、まさに品川区のスポットということでは、品川区の魅力の発信地の一つで、大きな部分であると思います。委員がおっしゃる部分につきましては、特別区競馬組合にご相談をしてまいりたいと思います。","voiceIndex":87,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"区長、ぜひよろしくお願いいたします。続きまして、時間がないので、健康塾の参加について、聞きます。本区は、自立した生活を送ることができる元気な高齢者のために、さまざまな事業をなさっていると思います。これは閉じこもりがちな高齢者、コミュニティとのかかわりを持っていくのには、とても大切なものの一環だと思います。この参加状況を少し教えていただきたいと思います。","respondent":"川島健康課長","answer":"今２３会場で実施しているのですが、平成２４年度から順に申しますと、１,８５１人、１,９５５人、２,０３２人。平成２６年度はまだ途中ですが、数が増えている状況です。","voiceIndex":89,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"時間がないので、私の意見を言わせていただきたい。やはり高齢者というのは、自分の足で、自由に気ままに歩ける。元気で明るくて前向きに過ごせるという意味で、このようないろいろな事業にお誘いしていただいて、どんどん取り組んでいただきたいと思います。１人でも多くの方が楽しみながら続けられるように、これからもいろいろな施策をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"提案","question":"私からは４点お伺いします。先ほどほかの委員からもありましたので、１点だけお伺いします。昨年の平成２６年の予算特別委員会の総括質疑でご提案したのですけれども、行政改革の観点から、このような大幅なシステム改修の際には、チームインフォメーションオフィサー、最高情報責任者補佐官、もしくは同等の民間の専門家を採用して、システム構築に当たっては、行政改革の観点から取り組んでいただきたい。","respondent":"永尾高齢者福祉課長、白鳥高齢者いきがい課長、秋山情報システム課長、上垣外生活安全担当課長","answer":"品川区の包括支援センターの考え方になりますけれども、今申し上げましたとおり、品川区が中心となって２０カ所のサブセンターと連携し。今回、北品川シルバーセンターにつきましては、今現在、契約中でございまして、この年度内に取替えを予定しています。平成２７年度につきましても、同様に民間の専門業者の支援を受けてシステム改修を進めていく予定です。私からは、客引き行為の定義について、まずお答えします。","voiceIndex":93,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"特に１点目、地域包括支援センター機能強化推進事業については、こちらの意も酌んでいただいて、ありがとうあります。具体的な状況に対して、第６期、どのように定めていくのか、その辺について教えください。４点目、客引き行為ですけれども、ありがとうあります。これについて、何とかこの条例の適用にならないのかということもありますので、その可能性について伺いたいと思います。","respondent":"永尾高齢者福祉課長、秋山情報システム課長、上垣外生活安全担当課長","answer":"利用者のニーズの把握や、丁寧に相談ができるような体制を第６期に向けてつくっていきたいと考えています。専門の業者ですけれども、品川区内にある日本総研という会社であります。ガールズバーの件についてお答えします。ガールズバーであれば、常にこの規制の対象外になるというわけではございません。","voiceIndex":98,"id":"exchange-037"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、７２ページ、自転車駐車場使用料、１３８ページ、放置自転車等保管料、１４１ページ、処分自転車等売却費、時間があれば、１３４ページ、広告料収入で聞かせていただきたいと思います。すみません。少し細かくなってしまうのですが、まず、１３８ページの放置自転車等保管料です。八潮、不動前とありますが、それぞれ最大どのくらいの自転車が保管できるのか、教えていただければと思います。","respondent":"田口交通安全担当課長","answer":"そのため、保管台数も減少している状況です。２点目の保管台数です。八潮につきましては、おおむね３,０００台、不動前につきましては１,５００台です。","voiceIndex":103,"id":"exchange-038"},{"speaker":"大倉委員","kind":"確認","question":"昨日も駐輪場が増えて、水神口のほうに６００台できると。今後増えていく中で、放置自転車が減っていっているのかと思ったので、伺わせていただきました。その中で、八潮、不動前なのですが、場所自体の所有は品川区でいいのかどうか、確認させてください。１４１ページの処分自転車等売却費は大体年間どれぐらいで、１台幾らで、どこに売れるのかということを確認でお願いします。","respondent":"田口交通安全担当課長","answer":"八潮につきましては東京都となります。不動前につきましては、東急になります。続きまして、売却費です。平成２６年度の実績ですが、自転車１台につきまして、１,７７７円、バイク１台につきまして、８,０１９円となっています。","voiceIndex":105,"id":"exchange-039"},{"speaker":"大倉委員","kind":"質問","question":"売っている場所というのは、どこに売っているのかという質問にも答えていただければと思います。都と東急ということで、借りているということでいいのでしょうか。その費用は、どこに入るのかというのを教えていただければと思います。これは、どういう見込みをされているのか、関連性を持ってお話しいただければと思います。","respondent":"田口交通安全担当課長","answer":"例えば、鉄くず、部品等は、原則は海外へ売却しております。それと、使用料の減額です。これにつきましては、来年度、青物横丁駅で京急の耐震工事を行います。この工事に伴いまして、当日の自転車利用が一部利用できなくなるといった台数を考慮して減額しています。","voiceIndex":107,"id":"exchange-040"},{"speaker":"大倉委員","kind":"確認","question":"これは、やはり台数が減ると、違法駐輪が増えて、保管料が上がっていったりということはしないのですか。保管料が７００万円ぐらい減っているのです。一方では、青物横丁駅の駐輪場がなくなるということは、その分、どこかに違法駐輪が起きるのだろうというところで伺っているので、その辺の整合性はどうなっているのか、確認で聞かせていただいております。","respondent":"田口交通安全担当課長","answer":"全体としましては、増えているという状況です。利用率につきましても、年々上昇傾向にあります。昨年度と比較しましても、現在のところ、利用率は上がっている状況です。","voiceIndex":109,"id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"東急にお支払いしている金額と、どういったところで予算に載ってくるのか教えていただきたいです。もう一回伺いますけれども、保管料が減っている理由は、台数が減るから、でも、一方で駐輪場も減っている。これは、自転車が余る。その余った自転車は、必ず違法駐輪にならないという理屈を教えていただきたい。","respondent":"田口交通安全担当課長","answer":"自転車の収容台数自体は、減ってはございません。ただ、今回、そういった一部工事ということで、使用料は減額になっておりますが、自転車の収容台数自体は、減少ということではございません。東急の不動前の使用料ですが、１３７万円です。","voiceIndex":112,"id":"exchange-042"},{"speaker":"大倉委員","kind":"質問","question":"要は、青物横丁駅で駐輪場を使って利用している人たちは、一体どこに行くのかということなのです。そこは、どこを使っていくのかということで伺えればと思うので、そこをよろしくお願いします。","respondent":"田口交通安全担当課長","answer":"耐震工事に伴いまして、現在、ラックで設置している部分は撤去になりますが、その他の敷地があります。ここに仮設の駐輪場をつくる予定です。それとあわせまして、付近の民間の駐輪場への誘導を行っていく予定です。","voiceIndex":114,"id":"exchange-043"},{"speaker":"大倉委員","kind":"質問","question":"駐輪場の仮設がどこにできるのかと、台数はどのくらいを想定しているのかと、ほかの民間にそれだけキャパがあるのかどうかというのと、周知の方法を教えてください。","respondent":"田口交通安全担当課長","answer":"現在、見込んでいるのが、自転車で８０台です。仮にここに置く場所をつくるです。場所についてですが、具体的な地図がないのですけれども、高架下の部分にそういった仮設で設けられるスペースがあります。そちらを一時的に利用していただくという形をとるです。","voiceIndex":116,"id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、６８ページの３、衛生使用料と、時間があれば１０１ページの２、衛生費負担金、未熟児養育医療費公費負担についてお伺いいたします。６８ページ、３、衛生使用料、１、保健所使用料、試験検査について、昨年に引き続きお尋ねいたします。試験検査６,１１０件の内訳について、ご説明をお願いいたします。","respondent":"高山生活衛生課長","answer":"こちら、６,１１０件の中身としましては、ふん便検査と、微生物学的検査ということで、いわゆる健康検査でありますとか、Ｏ－１５７にかかわる検査といったもののトータルのものでございまして、３センターの収入の合計としまして、６,１１０件を計上しているものです。","voiceIndex":120,"id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問","question":"赤痢と、チフスと、パラチフスと、サルモネラと、腸管出血性の大腸菌は細菌検査です。それと、事務事業概要を拝見しますと、ノロウイルスの検査も入っているのですが、ノロウイルスの検査も、今されているのでしょうか。","respondent":"高山生活衛生課長","answer":"こちらで計上しているような試験検査、いわゆる一般の方の申込みを受けまして検査しているものとして、ノロウイルス検査というものは実施しておりません。","voiceIndex":122,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"赤痢菌と、チフス菌と、パラチフスと、サルモネラと、腸管出血性の大腸菌の細菌検査は、事務事業概要を拝見しますと、大体、年間１,６００件から１,８００件ぐらいで推移しておりまして、かなり多いように思われるのです。これは、何か検査を行うときに決まりとか、検査の目安とか、あるいは持ち込まれた検体が多いとか、何か理由があるのでしょうか。ご説明をお願いします。","respondent":"高山生活衛生課長","answer":"それ以外に、水道事業者の方につきましては、Ｏ－１５７以外の４項目につきまして検査を行うものでございまして、そういったもののトータルが、先ほど委員がご紹介になった数字となっているものです。","voiceIndex":124,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これらの検査の結果で、実際に病原菌が検出される頻度は、どのぐらいなのでしょうか。この数年間で品川区で実際、食中毒の集団発生は見られたのでしょうか。お願いいたします。","respondent":"高山生活衛生課長","answer":"こちらの検査につきましては、生活衛生課の検査室で実施しているものです。委員ご紹介の食中毒の関係につきましては、東京都健康安全研究センターで実施しているものでございまして、こちらの中に含まれるものです。","voiceIndex":126,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ノロウイルスに関してお尋ねいたします。保健所ではどのような場合にノロウイルスの検査を、実際にされないということはわかったのですが、これは外注にかかわらず、オーダーされているのでしょうか。というのは、今現在、ノロウイルスは非常に流行していまして、現在、流行期なので、保健所で実際に検査をしているターゲットがどうなのかということに関して、まずお聞きしたいと思います。","respondent":"佐藤保健予防課長","answer":"保健所の検査室を使いましたノロウイルス検査を行います場合について、ご説明を申し上げます。","voiceIndex":128,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ノロウイルスは、冬場に乳幼児が感染し、激しい水様の下痢と嘔吐を繰り返す、冬季乳児下痢症の原因の１つであります。年長児や大人も感染するために腹痛、嘔吐、下痢の症状を示す感染性胃腸炎の１つです。私のところでも、先週も１人、検査希望でお見えになりました。このような検査希望の事例に関して、医療機関はどのように対応すればいいと保健所はお考えでしょうか。お考えをお願いいたします。","respondent":"佐藤保健予防課長","answer":"症状等々を鑑みまして、主治医の先生が、これは感染性が強くないということがわかった時点で登校できるのではないかというのが、保健所でご説明している考え方です。","voiceIndex":130,"id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"文部科学省の学校において予防すべき感染症の解説の本文では、「診断や診察に当たった医師が身体症状およびその他の検査結果を総合的に判断して、医学的見地に基づいて行われるものであり、学校から特定の検査等の実施、例えば、インフルエンザ迅速診断検査や、ノロウイルス検査を全て一律に求める必要はない」と述べられています。その場合、検査はどこで受けるべきなのか。その費用はどうなるのか。","respondent":"佐藤保健予防課長","answer":"実際に陰性が確認できるかということは、実際の感染性があるかないかという判断とはまた別の基準です。そういったことはなかなか伝わりづらいところではありますが、私どももあらゆる機会を通じて、丁寧に皆様にご説明を申し上げていきたいと考えています。","voiceIndex":132,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"私は、１１３ページの品川産業支援交流施設経費ほか７事業の確認をさせていただきたいと思います。品川産業支援交流施設のＳＨＩＰの概要について、ご説明をお願いいたします。オープンラウンジの会員募集は、４月開始予定かと思いますが、定員は何名でしょうか。お願いいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"品川産業支援交流施設のＳＨＩＰのオフィスの状況です。１２月から募集を開始しまして、一旦、１月中旬で、第１次募集ということで締め切りをさせていただいたところ、オフィス１６室のところ、１５の企業がエントリーということになりました。","voiceIndex":135,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問","question":"１０社が内定されているということだったのですけれども、どのような業種の方が、今、内定されているのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"いわゆる製造業の業種業態の方、それから、情報通信業の方、それから、そうした製造業と情報通信の重なる、製造機器を工作するときに組み込みソフトというものがありまして、そうしたそれぞれの性格を有する企業という状況です。","voiceIndex":137,"id":"exchange-053"},{"speaker":"横山委員","kind":"提案","question":"こちらは２４時間利用可能な全１６室の個室オフィス、コワーキングスペース、工房、貸会議室、多目的ルーム、大崎ブライトコアホールによって、日本、そして世界に向けたデバイスや日々の生活を豊かにするサービスの実現を支援するためのハード面が整理されているということですけれども、新しい事業を創出していくというところが目的かと思いますが。","respondent":"山崎ものづくり・経営支援課長","answer":"産学の連携につきましては、区内に立地しております産業技術院大学、あるいは都立高専と新ビジネス創造の関係で、さまざまなアイデアをいただいて、区内の企業がそのアイデアを具体化するようなやりとりといいますか、そうした形の連携を図っているところです。","voiceIndex":139,"id":"exchange-054"},{"speaker":"横山委員","kind":"質問・要望","question":"最後に簡単に新しいアイデアを生み出すための工夫に関して、会議室の一部の壁に黒板やホワイトボードなどを工夫されるかと思いますけれども、そういった自由で新しいアイデアが生まれやすい環境づくりについてもご配慮いただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"私からは、８９ページの土木費補助金の西品川一丁目地区についてと、１３２ページ、受託事業収入、人孔蓋枠等工事費収入の２点についてお伺いしたいと思います。初めに、西品川一丁目地区です。今工事が始まるというか、更地になって、これから建設が始まってくる段階に入っております。その歩道のところについて、拡幅の計画と、どのようになっているのかをお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"委員ご質問の、今現在狭くなっております鉄道の下の歩道の部分です。これにつきましては、もともと補助１６３号線という都市計画道路の計画がありまして、今回、再開発事業に合わせまして、その整備をする形になっております。","voiceIndex":145,"id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"線路の下に通路、トンネルをつくるという計画だとお伺いしました。住まわれている方にとっては非常に必要な通行帯になると思いますので、ぜひやっていただきたいのです。その点について、きちんと見えるような形で、「歩行者は通行禁止」ということをしていただきたいという要望です。こういう通行についてはどのようにお考えを持っているのかということをお聞きしたいと思います。","respondent":"稲田道路課長","answer":"百反ずい道の歩行者と自転車の通行についてお答えします。歩行者が山手通り側から百反坂下のほうに抜けるということは、通行禁止というところでございまして、看板が見えないですが、既存の看板は現場を点検しまして見えるようにします。","voiceIndex":147,"id":"exchange-057"},{"speaker":"塚本委員","kind":"質問・要望","question":"しかし、せっかく自転車も通れる歩道橋をあそこに整備いたしましたので、やはり事故の危険性等を考えると、あちらの歩道橋をなるべく利用していただけるような形でうまく誘導できるような検討というか、努力をしていただきたいと思います。その点は要望として、よろしくお願いしたいと思います。次に、１３２ページの人孔蓋枠等工事費収入です。事業の内容をお伺いしたいと思います。","respondent":"稲田道路課長","answer":"この人孔蓋枠の受託の事業なのですが、これは区が道路改修工事を毎年実施しているのですけれども、この中で下水道のマンホールがあります。","voiceIndex":149,"id":"exchange-058"},{"speaker":"塚本委員","kind":"質問・要望","question":"マンホールによって滑るということについて、私が小さいときからマンホールの形やデザイン、素材は変わっていないような気がするのですが、マンホールによって滑る危険性をどのようにお考えになっているのかということと、これまで何かしらの改善みたいなことが、実は行われているということがあれば、教えていただきたいのです。よろしくお願いします。","respondent":"稲田道路課長","answer":"そのようなタイプを私どもの工事でも受託して改修しながら、下水道局も年間２００個ほど、品川区内では交換しているという状況です。","voiceIndex":151,"id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。新しくなってくれば、かなり滑らなくなるということで、ご答弁があったと思います。一応、私もこういう声を聞いていたので調べたことがあります。そういったものをどのように認識しているのかというのをお伺いしたいと思います。","respondent":"稲田道路課長","answer":"マンホールの表面にそういう素材を塗って、滑りをなくすという方法につきましては、以前、区でも塗って、そういうものを実施したことがあります。それは、試しにやってみたのですけれども、年月がたつにつれて、どうしてもはがれていくという状況が当時はございました。","voiceIndex":153,"id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"私は、地方消費税交付金について伺います。地方消費税交付金は、昨年度に比べて２５億円も増えている。総額で９２億円です。しかし、具体的にどの事業にどの程度充当したのか。それが昨年度と比べて、どれだけ金額的に増えたのかというのが、なかなか具体的につかめないので、一、二の例でいいですから、どうなっているのかというところを伺いたいと思います。よろしくお願いします。","respondent":"本城企画財政課長","answer":"ただ、今回もさまざまなご説明をさせていただきましたように、社会福祉関係など、さまざまな充実を図っております。今回新たに充実させた項目も含めて、今回、こちらの地方消費税交付金を充当したというものです。","voiceIndex":156,"id":"exchange-061"},{"speaker":"南委員","kind":"質問","question":"国からの指定されている項目ということです。具体的に明らかにしていただければと思っています。例えば、今回、１３項目には、一番上の欄外に書いてあるように、３７億９,０００万円充当しているということなのですけれども、私はもっと９２億円も来ているのでありますから、もっと充当するべきだと思っています。この金額にとどまっているのはどういうことかということも伺いたいと思います。","respondent":"本城企画財政課長","answer":"各分野にわたっているということで、特定のどれということではありませんが、待機児童対策関係でもろもろ充実したり、障害者関係でもろもろ充実したり、高齢者に対する施策も含めてで、今回たくさん一定の財源を拡充する中で、充実させた項目も含めて。","voiceIndex":158,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"今、私が伺いたかった趣旨というのは、１.７％掛ける９２億円で３７.９億円だけではなくて、もっとそのほかに充てるべきではないかということを言いたいのです。そういう視点はお持ちではないのかということを、一つ伺いたいと思います。去年の４月に消費税が８％になりました。ですから、そういう考え方はないのかということを聞いているので、そこについて答弁をお願いしたいと思います。","respondent":"本城企画財政課長","answer":"基金の関係にしましても、一定の財源を確保する中で、現在のサービスを充実させるとともに、これからの社会保障基盤だとか、将来に向けた区民に対しても、きちんとした責任を果たす上で、バランスよく、現在、将来を含めた施策の対応をしていると考えているところです。","voiceIndex":160,"id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"私は、区民の生活の実態を見たときに、やはり施策へ予算をつけて、区民の負担軽減をするべきだと思っているのです。介護保険料も上がります。そういう点で、もっとしっかりと負担軽減をさせるという角度から、国民健康保険料の引き下げ、介護保険料の引き上げではなくて引き下げ、こういうところに潤沢な財政を充てるべきだと思って、ぜひそういう方向で取り組んでいただけるように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-064"},{"speaker":"沢田委員","kind":"質問","question":"庁舎管理費負担金のほうなのですけれども、東京都の品川都税事務所、東京都第二建設事務所、東京法務局品川出張所、それぞれ大幅な負担金が増額ということで、いろいろ調べてお伺いしたところ、以前も別の委員が質問をされていましたけれども、庁舎の擁壁を修理したり、そのたびに負担金が変わるということで、この３つについては、区分所有されているということで、負担が変わるということでありました。","respondent":"立川経理課長","answer":"金額が、今回、約１億円、前年より増額になっております。主な増理由ですけれども、総合庁舎の設備機器の更新の時期を迎えておりまして、その改修工事費につきまして、区と都と国で、庁舎の持ち分比率に従いまして按分した結果、こういった数字になっているところです。","voiceIndex":164,"id":"exchange-065"},{"speaker":"沢田委員","kind":"意見","question":"その持ち分比率によって、区分所有ごとに決まっているということですけれども、それは区と都と国との約束というか、協定みたいなものがあって、そういうことになっているのかお聞かせください。例えば、東京都第二建設事務所と、品川都税事務所よりも東京法務局品川出張所はそんなに２倍以上になっているわけではないので、そのあたりの取り決めがどうなっているのかをお聞かせいただければと思います。","respondent":"立川経理課長","answer":"総合庁舎につきましては、昭和４３年から東京都法務局と、東京都知事と、品川区長の間で協定書を結んでおります。","voiceIndex":166,"id":"exchange-066"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったことで決まっているということです。以前から、法務局が１０年以上前から、品川区から別のところでということで、そういった閣議決定があると思うのです。品川区と法務局との連携というか、品川区に残ってやっていただきたいという連携は、今どのような形でされているのか、改めて確認をさせてください。","respondent":"立川経理課長","answer":"かなり前に法務局の移転ということにつきましては、委員ご指摘のとおり、話があったところです。最近は、その辺の話は一切聞こえてきておりませんので、法務局としましても、移転については、現在のところ検討はされていないという状況だと認識しています。","voiceIndex":168,"id":"exchange-067"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほどの箱根荘はどうなったのかということでお伺いしたいのです。昨年、いろいろと品川区でも努力されて、ヤフーオークションに出されたと思うのですけれども、今現在、どのようになっているのか、お聞かせいただきたいと思います。","respondent":"立川経理課長","answer":"今後なのですけれども、インターネットによる公売は年６回実施しておりますので、引き続き、継続的に粘り強く旧箱根荘の跡地の売却については取り組んでいこうと考えているところです。","voiceIndex":170,"id":"exchange-068"},{"speaker":"沢田委員","kind":"質問","question":"残念ながら応募がなかったということです。できるだけ売却の方針ということで決められて、以前質問したことがあるのですけれども、どうにかして有効活用という話もさせていただきました。今、ヤフーオークションに出されているということでした。現在、区が箱根荘跡を持っていることによって負担している金額は、いろいろなものを含めて、どれだけ年間負担をされているのか、お聞かせください。","respondent":"立川経理課長","answer":"基本的な部分ですけれども、管理料等につきまして、年間約３０万円弱というものがかかっています。維持管理という部分で、剪定費用を若干見込んでいるところです。ですから、現状、維持するのに、総額１００万円程度かかっております。","voiceIndex":172,"id":"exchange-069"},{"speaker":"沢田委員","kind":"質問・要望","question":"何もしなくても年間１００万円出ていくということであります。できるだけ売れる方向で、オークションに出すのもそうですけれども、積極的な広報というか、品川区は、今こういうものを売り出していますということをやったり、もしくは、近所の別荘地に詳しい不動産屋にしっかりとアピールして、売っていただくようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-070"},{"speaker":"井上委員","kind":"質問","question":"今、箱根荘の売却について出たのですけれども、私もそのことについてお伺いしようと考えています。そういった検討が今後あり得るのかどうか。それと、今、年６回、インターネット公売もあるということですけれども、このままずっと待つということは、有効活用には適さないと思うので、どのぐらいか期限を切って考えるとか、多方面での検討が必要と思いますが、いかがでしょうか。","respondent":"立川経理課長","answer":"今後の見通しですけれども、地元の不動産関係の精通者とか、リゾート会社とか、その辺に聞き取り調査を実施したところ、やはりこれぐらいの規模の土地になりますと、取引が極端に少ないという部分があります。","voiceIndex":176,"id":"exchange-071"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど、用途に縛りがあるということでしたけれども、さまざま困難であるということも変えられるということがありますので、その辺は検討いただきたいと思います。２０１４年度の予算書では、充当事業として、「地域生活の支援」と書かれておりましたけれども、２０１５年度の予算では、「心身障害者福祉会館運営費」と表記されております。変更した意図と、事業内容の変更があれば、教えてください。","respondent":"中山障害者福祉課長","answer":"平成２６年度までの３年間につきましては、地域のデイケアをやっているところに対しまして、高次脳障害の医療につなぐまでの支援というところで、この経費を使っていたものです。","voiceIndex":178,"id":"exchange-072"},{"speaker":"井上委員","kind":"質問","question":"そういった居場所、通所デイサービスのようなものも、すごく必要性を感じているのですが、品川区での現状と、今後の方針をお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"こちらをご紹介するのとあわせまして、その方の症状によっては、例えば、就労継続Ｂ型支援であったり、言葉のリハビリであったり、あるいは民間の医療デイケアにつないでいるところです。","voiceIndex":180,"id":"exchange-073"},{"speaker":"井上委員","kind":"質問・要望","question":"なかなか相談に行くということが、まだ周知をされていない現状もあるかと思いますので、そちらのほうに力を入れていただきたいと思います。ですから、周知方法には、普通の人がわかるような丁寧な周知をしていただきたいというのが、一つ要望です。それから、すべての学校を一斉にやるような感じなのですけれども、工事の具体的スケジュールはどのようにお考えでしょうか。","respondent":"品川庶務課長","answer":"スケジュールですけれども、全校にわたりますので、なるべく各学校とも重ならないような形で、各学校、地域、いろいろな部署に連絡調整をとりながら日程を決めてあります。","voiceIndex":182,"id":"exchange-074"},{"speaker":"井上委員","kind":"質問・要望","question":"私が使用料から入ったからそんな感じかもしれないですけれども、基本的には、子どもたちが中心なので、各学校一斉だとしても、その子たちにどういう教育配慮がなされるかということなので、そこはやはり子どもたち中心にスケジュールを立てていくということで、なるべく短期間の工事になるような効率化を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-075"},{"speaker":"向委員","kind":"質問","question":"私からは、７５ページ、犬の登録・鑑札交付、あと７７ページ、食品衛生法関係の関連でお尋ねしたいと思います。犬の登録・鑑札交付のほう、予算ということで、来年度２５２万円ということで計上されています。そもそも犬の登録・鑑札交付をする目的を教えてください。","respondent":"高山生活衛生課長","answer":"したがいまして、世界的に見ますと、狂犬病の清浄地域というのは、日本をはじめとしまして、ごくわずかな地域に限られております。それは、日本の犬の登録制度がもたらした効果だと考えますので、そういった必要性に基づきまして登録を行うものです。","voiceIndex":186,"id":"exchange-076"},{"speaker":"向委員","kind":"質問","question":"狂犬病対策ということで。ぎりぎりのラインを品川区は保っているのかと。もちろん、交付をもらっていない犬もいると思うので、このあたりで、できればもう少し数字としては上がってほしいと思うのですが、この数字がもし間違っていたら、後で教えてください。登録数、実際飼育数との乖離とか、そのあたりを区としてどのようにお考えか、把握していらっしゃるか、教えてほしいと思います。","respondent":"高山生活衛生課長","answer":"委員ご紹介の狂犬病予防の接種率は、大体７割ぐらいです。この数字をできるだけ高い数字に持っていくというのが、区としての責務です。","voiceIndex":188,"id":"exchange-077"},{"speaker":"向委員","kind":"質問","question":"それだけではなくて、本当にたくさんの人がふだん感染していると気付いていないような感染症といったものがあるということで、先日、日本大学の荒島先生に詳しくお話を伺ったりもしました。こういったハンドブックというのは、一応、厚生労働省のホームページからもダウンロードはできるのですけれども、犬の登録に来た際とか、保健所でこういったパンフレットは手に入れることはできるのでしょうか。","respondent":"高山生活衛生課長","answer":"そういった動物由来の感染症につきましては、注意喚起のパンフレット等は厚生労働省でありますとか、環境省等から一部送っていただいている部分もあるのですが、まだ十分に配布する部数については、入手しておりませんので、その他のホームページでありますとか。","voiceIndex":190,"id":"exchange-078"},{"speaker":"向委員","kind":"質問","question":"わかりました。倦怠感、うつのような症状、不登校、子どもが切れやすくなったとか、そういった症状が出る病気。実は推定数約３００万人に上ると全国で言われている感染症であったり、あとはパスツレラ症。抵抗力が低下してくるということも、このあたりの病気、症状が出る引き金となるということでしたので、このあたりについて、今、区としてどういうお考えがあるかというところをお伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"そういった動物由来の感染症、狂犬病をはじめまして、そういったものが、いわゆる日和見といいますか、弱者の方にどのくらい悪い影響があるのかというところまできめ細やかな周知という点に関しては、まだ不十分な部分もあろうかと思いますので、そういった部分につきましては。","voiceIndex":192,"id":"exchange-079"},{"speaker":"向委員","kind":"質問","question":"今、感染症に焦点を当ててお話ししてきたのですけれども、この登録数を把握するということは、例えば、以前我が会派からも、何度かペットの避難所への一緒の避難をどうしたらいいのですかということで質問させていただきました。今は人と飼っている動物とのきずなというのは深いところにありますので、このあたりについて、改めてお願いしておきたいと思うのですけれども、お考えをお願いします。","respondent":"高山生活衛生課長","answer":"もちろん、避難所における受入れの体制の難しさというのもある一方で、この間の東日本大震災の事例などを見ますと、例えばマイクロチップなどが体内に埋め込まれていたことによって、飼い主と会うことができたとか、もちろん鑑札も大事な登録手段ではあるのですが。","voiceIndex":194,"id":"exchange-080"},{"speaker":"向委員","kind":"質問","question":"食品衛生のこともお伺いしたいので、７７ページのところです。来年度、２,４２５万円余ということで計上されています。最近少し気になっているのが、食べ物というと「生肉を食べるのはやめてください」、「牛の生レバーはやめてください」とか、いろいろありました。このあたりはこれでいいのかと思いまして、お尋ねします。","respondent":"高山生活衛生課長","answer":"委員からの食品衛生の関係の情報発信が滞っているのではないかといったご指摘につきましては、この間の食中毒の大規模化でありますとか、ノロウイルス、その他のカンピロバクターをはじめとしたさまざまな食中毒原因菌がありますので、そういった部分の周知については。","voiceIndex":196,"id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、８９ページの土木費補助金の中から、道路バリアフリー事業、２点目が、１３３ページの土木費受託収入の中の大森駅歩道橋、時間があれば、６６ページの民生使用料から、高齢者等住宅使用料をお伺いします。これは、大井町駅周辺とご説明を伺っているのですが、これに関連して、別の場所でのバリアフリーというところを少しお聞きしたいと思います。この構造の考え方。ここをお伺いしたいと思います。","respondent":"稲田道路課長","answer":"大森駅歩道橋です。大森駅歩道橋は、委員ご案内のとおり、大田区と重複認定の協定を結んで管理しています。そこにエスカレーターがついているのですけれども、この稼働時間は、現在朝６時から夜１１時までの稼働時間となっております。","voiceIndex":199,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"地下道のお話です。昭和４２年から開通しているということで、約５０年弱がたっているということです。そういうお声が区に届いているかどうか、そこも含めてお伺いしたいのですが、もし届いていないのであれば、改めてこの場所でお届けしたいのです。ここをどう改善できるかというところが、品川区の手腕が問われるなと、ぜひ頑張っていただきたいという思いで質問しているのですけれども、いかがでしょうか。","respondent":"稲田道路課長","answer":"技術的には非常に難しいということで、両脇区道の高さが決まっております。","voiceIndex":201,"id":"exchange-083"},{"speaker":"こんの委員","kind":"質問","question":"そうなると、一定の構造上、あるいは経年というところで、抜本的に変えるという時期を迎えているのではないかと、そんなタイミングでこういったところも、トンネルの長さが短く、通りやすいようにする構造上ということはお聞きしているのですが、斜めにスロープのようにできるような改善が、今後、そういったタイミングでできるといったことはいがかでしょうか。","respondent":"稲田道路課長","answer":"何とか現場を調査しまして、細かな点になるかもしれませんが、歩きやすいような処置を考えられればということで、調査を進めていきたいと考えております。","voiceIndex":203,"id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ調査から始めていただいて、何とかその可能性を見出していただきたい。このように要望いたします。実は３・１１以降、節電の関係で一旦時間が区切られたのですけれども、どうやらそのままになっているらしいという形なのです。その分、早めに家を出てくださいということもあるでしょうけれども、こうした利便性を区民のために考えていただきたい。このお考えはいかがでしょうか。","respondent":"稲田道路課長","answer":"大森駅エスカレーターです。ここは、声も届いております。今後、検討して、大田区とも協議しながらやっていきたいと考えています。","voiceIndex":205,"id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問・要望","question":"９１ページ、空き家等対策事業の充当補助のところから伺っていきます。そして、区長、所有者、区民の義務や責務が記載されているという中で、特に注目したいところを伺いたいと思います。代執行の規定を盛り込む。その点を一つ伺いたいです。実態調査。平成２６年度、町会等の協力の中で、この調査をしたことで、かなり全区的に関心がぐっと高まったと。この区分をどう考えていらっしゃるのか教えてください。","respondent":"矢木住宅担当課長","answer":"現在のところ、判明いたしました所有者に対しまして、アンケートを実施いたしました。今のところ、１,７００件ほどのアンケート送付をいたしまして、約５４６件の回答を頂戴しております。この中で、貸す意向があるという方は３０件弱といった回答がございました。","voiceIndex":208,"id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問","question":"数字のところで、１,０００という数がある。その中で回答があって、把握ができるもの。これは、追っていく。待っている姿勢ではだめなものだと思われます。その点で、これから条例を根拠に、どう対応していく、運営していくという観点から伺います。というのは、全体の流れで、２０２０年のオリンピック・パラリンピックもある。その点を含めて、今後の運用のところ、考え方を教えてください。","respondent":"矢木住宅担当課長","answer":"こちらは、平成２７年度の予算におきましても、こういった地域の活性化に資する公共的施設ということで、改修費用等を一部助成する空き家活用モデル事業を行います。その中で、体制や有効活用策につきましても検討してまいります。","voiceIndex":210,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"いろいろな事例と応用がきく、幅の広い、そして、次年度すぐではなくて、もともと計画性がある中で、実態調査があり、そして、モデル事業をやり、本格稼働という中で、最後になりますが、本格稼働への中で、特に有効活用のところ。その点、重ねてになりますが、考えを伺って終わりにしたいと思います。","respondent":"矢木住宅担当課長","answer":"こちらは、庁内各組織、ならびにほかの区内団体の皆様とも連携をとりながら、品川区ならではのいい政策を打ってまいりたいと思います。","voiceIndex":212,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"私からは、５５ページ、民生費負担金の区立、私立保育園に関してです。全体的な構成を教えてください。先ほど、いろいろつくるということもありますので、自治体の特徴であったり、観光を含めた形で、マンホールをつくるのであれば、品川区の特徴をそこで訴えることもできるのではないかと思うので、デザインの方向性としていかがでしょうかというご意見をお聞きしたいと思います。","respondent":"竹田保育課長、中村都市計画課長、稲田道路課長","answer":"区立保育園の歳入の状況についてご説明いたします。道路のバリアフリー事業につきましては、今年度、大井町駅周辺地区バリアフリー計画を策定をして、これから公表の予定です。その辺で、費用対効果がなかなか見えないところもあるかとは思いますが、その辺は今後の検討です。","voiceIndex":215,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"区長はおわかりになっているような顔をしていますけれども、本当に地域の活性という意味で言うと、款が違うかもしれませんけれども、観光を視点に入れたマンホールというのは、今非常に注目されておりますので、せっかくつくるのであれば、多少高くなっても、品川区に来ていただく一つのきっかけになろうかと思いますので、ぜひ研究をしていただきたいと思いますので、よろしくお願いします。お願いします。","respondent":"稲田道路課長、中村都市計画課長、今井制度改革・待機児童対策担当課長","answer":"東京都下水道局のほうには、この件を紹介していきたいです。バリアフリーの整備の考え方につきましては、道路、建築物、それぞれ施設管理者、事業主に個別に調整を図りながら、短期的にできるもの、そして。地域型保育事業が新たな区の認可事業になりましたが、これまでよりもさらに国、都の支援が拡充されておりますので。","voiceIndex":219,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"マンホールの件、ぜひとも検討していただきたい。それから、道路のバリアフリーについては、やはり計画的にしていっていただきたいと思います。国は新制度が始まりますし、いろいろな考え方が出てくると思いますので、効果的な方法、民間を活用するなり、いろいろな補助金等も含めて検討しながら、なるべく品川区の負担が少なくなるように、保護者の負担がないような形で工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-091"},{"speaker":"あべ委員","kind":"質問","question":"私からは、１２２ページ、財産貸付収入、地所賃貸料、旧第一日野小学校跡地等、それから、１２４ページ寄附金、先ほどからお話が出ていますふるさと納税に関すること。そして、税外収入に関しても関連で質問をしたいと思います。時間があれば、１３４ページの競馬場についても、少し述べたいと思います。定期借地と賃貸借、どのような基準で使い分けているのかということも、あわせてお伺いしたいと思います。","respondent":"立川経理課長","answer":"地所賃貸料の主なものですけれども、今回、４億９,３００万円ほど歳入計上させていただきました。主なものといたしましては、劇団四季に貸し付けております用地、こちらが金額としましては、６,０００万円弱です。","voiceIndex":225,"id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは、長さで変えているという理解でいいのでしょうか。定期借地と賃貸借では、物権と債権の違いがあって、かなり借り主と貸し主の力関係が変わってくる。定期借地のほうが、借り主にとって、とても有利であるという状態で、長さだけで決めているとは思いにくいのです。戻ってくるための努力をＴＯＣは確実にやってくれるのかということを教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"そういった中で、今ＴＯＣ本社に入っているテナント等です。これは、契約のころは３００店舗ぐらいが入っていたといったところであります。現在、細かい数字はわからないのですが、２５０ぐらいまでになっているという状況にあると聞いてあります。","voiceIndex":229,"id":"exchange-093"},{"speaker":"あべ委員","kind":"意見","question":"これは、テナントが出て行ってしまうのであれば、区が協力する大義名分はないのです。少し残念だと思います。その上で、今回の契約に対しても、また定期借地という形で、あちらの権利を大幅に認めている。これは、区としてどのようにお考えなのか聞かせてください。","respondent":"柏原行財政改革担当課長","answer":"契約書、基本協定を結んでいるのですけれども、その中でも、前提がそれだということで結んでおりますので、基本的に両者はその前提のもとに今動いているという認識です。","voiceIndex":231,"id":"exchange-094"},{"speaker":"あべ委員","kind":"質問・要望","question":"その方向で、ぜひ今後も努力していただきたいと思います。民間が相手だと、どうしても向こうのペースになってしまうということでありましたら、民間とのこのような契約は、できるだけ抑制的に行っていったほうがいいのではないかと、意見として述べします。そうではなくて、適正な料金をとりながら、そういったことをしていくということは可能でしょうか。お考えとしていかがでしょう。","respondent":"多並公園課長","answer":"そういうものをいろいろ研究しながら、今後のよりよい公園の管理のあり方、また進め方については研究してまいりたいと思ってあります。","voiceIndex":233,"id":"exchange-095"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最初に、公園の関係からお聞きしたいと思います。これは、都の補助金の中の都市計画費交付金にも絡んでくると思うのですけれども、これがＪＴ跡地の購入の補助金になっているのですか。そこら辺の確認をさせていただきたいと思います。それが１点。それから、シルバーセンターの件でお聞きしたいと思います。先ほど、目的外使用の件でお話が出ました。この点を教えてください。","respondent":"多並公園課長、白鳥高齢者いきがい課長","answer":"公園整備の歳入の件です。この公園・児童遊園整備の中で、３億円という歳入の中、国庫補助金という形でＪＴ跡地に充てている歳入です。南品川シルバーセンターの浴槽の設置整備です。今現在、計画の中では、４カランということで予定しているものです。","voiceIndex":237,"id":"exchange-096"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ＪＴの購入費用は、都市開発公社が一時買って、立替えているわけですけれども、たしか全体だと５０億円ぐらいでしたよね。多分、１階の部分の和室のところとお聞きしていますので、そこが少し広がると、ふれあいサロンでしたか、食事ができるような施設もついているから、そこら辺の調整をうまく図っていただきたいと思うのですが、その辺のお答えをもう一回お願いしたいと思います。","respondent":"多並公園課長、白鳥高齢者いきがい課長","answer":"こちらの内訳としましては、用地費が３分の１、分割で３カ年に分けている関係で、１７億２,８００万円。残りが工事費とそれにかかる管理委託費です。そのようなことで、現在進めているところです。こちらの施設につきましては、３階建てですので、２階、３階の、現在グループ利用されている方々につきましては、ご負担のないように、その辺のところはしっかりと調整をしながらやっていきたいと考えています。","voiceIndex":240,"id":"exchange-097"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それぞれわかりました。ここだと、ヘリコプター、自衛隊との調整みたいなものはうまくやっていらっしゃるのかどうか。それを確認したいと思います。やはり前からいろいろ言われていました中で、ちょうどあそこの坂を下りる方のご了解が得られておりますので、手すりをつけられるようになると思いますので、この辺もうまく調整していただきたいということをお願いしておきます。","respondent":"多並公園課長、鈴木建築課長","answer":"そういうところもいろいろなところでお話を聞きながら、実態上の件も聞いてあります。現在も、そこを設計の中に含めながら、よりよい災害活動に使えるような整備を進めているところです。したがいまして、基本的には坂道の部分につきましては、もちろん私道ですけれども、区の建築課で所管しております私道整備事業を活用していただきながら、通常ですと、私道の持ち主から申請があっての整備、支援ですけれども。","voiceIndex":243,"id":"exchange-098"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろお聞きして納得しました。万が一の場合には、そういう形でうまく利用していただきたいと思います。これは、総務委員会で既にお話はあったと思うのですが、私は総務委員会に出ていないので確認しておきたかったのです。これは、法人住民税の国税化によって、財調の交付金は全体として減っている中で、当然、品川区の基準財政需要額が多かったということなのですが、その辺の判断を教えてください。","respondent":"本城企画財政課長","answer":"具体的には、都市計画関係の事業で、その分、平成２７年度の見込みが多いということで、その分が約１７億円のプラスになって、若干細かい入り繰りはありますが、大きな要因としては、その分が１７億円プラス、一方で住民税法人分の国税化分がマイナス１１億円の影響で。","voiceIndex":246,"id":"exchange-099"},{"speaker":"鈴木（真）委員","kind":"確認","question":"算定していく中で、新規の項目もいろいろ出てくると思うのです。今回も少し出ているような話だったのですけれども、今回、どのぐらいの新規算定項目になってきて、どんな内容なのか、もう一度確認させてください。","respondent":"本城企画財政課長","answer":"今回、新規算定ということで、最終的に都と区の間の協議が成立しましたのは７件です。そのうち、例えば帰宅困難者対策用の食料費の備蓄ですとか、通学路の防犯カメラの整備費ですとか、そういったものを含めて、７件の新規算定の項目があったところです。","voiceIndex":248,"id":"exchange-100"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然、両方とも品川区がやっている事業だと思いますし、２３区で足並みをそろえている部分の算定ですよね。２３区の中で、品川区はこういう項目を入れてもらいたいという折衝はできるものなのですか。その辺の都との折衝ではなくて、区間の折衝というのは、どんなものなのでしょうか。","respondent":"本城企画財政課長","answer":"ただ、実際は、都との協議に持ち込むに当たっては、２３区で、ある程度かなり標準的な施策になっていないと協議に持ち込むこと自体もなかなか難しいという判断もございましたので、それについては、結局、今回は見送りということで、これからのテーマとして、それも含めて。","voiceIndex":250,"id":"exchange-101"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。区の施策を進めてやっていく中で、これからも新しい事業を進めていくものがいっぱいあると思います。当然、当初は一般財源でやっていくでしょうけれども、その辺、企画サイドとして、新しい施策をぜひ他区にも結びつけて、財源的にも財調を使えるように頑張っていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-102"},{"speaker":"山元委員","kind":"質問・要望","question":"最初に、高齢者クラブ等支援事業についてです。街角にきれいなお花が咲いているのは、実は高齢者クラブの花づくりの方たちが携わっていたということを聞いて、とても心温まるのですが、改めて高齢者クラブというのと、高齢者クラブ連合というものがありますが、この違いがどういうことなのか、教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"高齢者クラブ連合会、そして、高齢者クラブの違いというお尋ねです。現在１１３クラブ、品川区内にクラブ数があります。そちらを束ねて、１つの連合体という組織を組んでいるのが品高連と言われている品川区高齢者クラブ連合会です。","voiceIndex":254,"id":"exchange-103"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、年に１回の菊のお花もそうですが、花づくりなのですけれども、先ほどの課長から１１３グループあるとおっしゃっていました。実際、この中の花づくりに携わっている方たちはどのぐらいのグループが携わっていて、また、品川区内に何カ所ぐらい花づくりに携わっていらっしゃるのか、その辺を教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"各クラブの花づくりを行っているボランティア数につきましては、申し訳ございませんけれども、掌握してございません。","voiceIndex":256,"id":"exchange-104"},{"speaker":"山元委員","kind":"質問・要望","question":"もしわかれば、６０代、７０代、８０代という、１１３クラブのうち、１万２,０１９人いらっしゃるということですが、その割合がわかれば教えていただきたい。高齢者クラブの方たちの、いろいろな活動回数によって助成金が違うのですけれども、実際、１１３グループの方たちの活動回数、またどういうボランティア活動をなさっているのか、わかれば教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"ここが非常に多く活動しているクラブ数。ちなみに、３００回以下のところになりますと、２３クラブ。６００回以下のクラブが３２。もう一つ、８５０回以下が２７クラブということで、大体この辺のところがボランティアの回数です。","voiceIndex":258,"id":"exchange-105"},{"speaker":"山元委員","kind":"質問","question":"先ほど、３００回から６００回が多いということでありますが、現実的にボランティア活動の内容というのは、どういうことをなさっていらっしゃるのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"こういったことを中心とし、また、健康体操ですとか、それぞれのクラブが活性化するような活動が主な活動の内容です。","voiceIndex":260,"id":"exchange-106"},{"speaker":"山元委員","kind":"質問","question":"先ほどの課長のお話ですと、やはりメンバー的に７０代の方が中心というお話でありました。団塊の世代の意識調査によりますと、まずは誘われたら地域活動に参加したいという方が３６％いらっしゃるということであります。そういうことを考えると、これから本当に高齢化が進んでおりますので、継続させるためにも、やはり周知の方法とか、またその方たちに対しての勧誘は、区としてどのようにお考えでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"そのために、区としましては、品高連独自の事業ですけれども、毎年１月から３月、会員増強月間ということで定めておりまして、各クラブがそれぞれの地域の中で会員加入ということで、もちろんこれは行政側といたしましても。","voiceIndex":262,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"区からの情報、８０％以上の方が広報しながわを見ているということですので、ぜひとも、その辺の周知の方法をお願いしたいと思います。現場はかなり高齢化して、次をどうしようかと、皆様、結構悩んでいらっしゃいますので、その辺をよくわかっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":264,"id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは８０ページの国庫支出金、９８ページの都支出金の中の民生費負担金の国民健康保険負担金について伺いたいと思います。保険財政共同安定化事業が、この４月から始められるわけですけれども、拠出金は、都の国保連合会に集められて交付されます。２０１５年度から、１レセプト１円からと、全ての医療費が対象になりますが、これによって、国や都からの支出は変わってくるのかを伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"委員お尋ねの共同事業の交付金の関係です。これは、大きく分けて２つございまして、１つ目が高額医療費の共同事業になってあります。","voiceIndex":267,"id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"提案","question":"今、ご答弁の中にもあったように、この事業は、国民健康保険の改正、改変に関連したものだと思います。平成２７年度、国保条例はまだ提案されていませんけれども、国保運営協議会、私も傍聴しましたけれども、値上げの提案がされていました。値上げに当たっての国や都からの支出はどう変化してくるのか、伺いたいと思います。それと、区への影響はどうなってくるのか、伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"確かに平成２７年度４月１日以降の国民健康保険の改定につきまして、今、条例改正の手続をしているわけです。","voiceIndex":269,"id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問","question":"平成２９年の広域化、また都道府県化に向けた保険財政共同安定化事業なども、序章の一つだと思うのです。現在は、２３区統一保険料ですけれども、広域化、都道府県化になっていくと、これがどうなっていくのかを伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"平成２７年１月１３日、１４日の国の安定化に向けた委員会の中では、都道府県が財政を担当し、それ以外の加入や喪失等の手続、また給付、保険料の徴収等、保健事業につきまして、市町村が共同して負担するという形で推移しています。","voiceIndex":271,"id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問","question":"この広域化、都道府県化ですけれども、私はすべきではないと思うのです。もし広域化になっても、一般財源が投入できるのです。投入して、保険料は引き下げるべきと考えるのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"現在、保険料につきましては、２３区で統一保険料方式を算定しています。その中で、さまざまな財政状況、また地域の事情等を勘案しながら、毎年、前年度の医療費、前々年度の医療費等の増減に基づきまして、保険料につきましては改正しています。ご理解いただきたいと思います。","voiceIndex":273,"id":"exchange-112"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この間、値上げが繰り返されてきているのですけれども、高額療養費への一般財源投入を全てなくしていく。保険料に付加していくというのが、去年から４年間かけて進められていく。１人９,０００円の値上げを強いていくわけです。ですので、値上げではなくて、引き下げこそ行うべきと思うのです。消費税増税分、２５億円が入ってきています。使っていただきたいと思いますけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"今のところ、その予定はございません。","voiceIndex":275,"id":"exchange-113"},{"speaker":"石田（ち）委員","kind":"質問","question":"国保料が高過ぎるという認識を昨年も伺ったのですが、区民にとって、この国保料というのが、住民生活を超えてくるのです。昨日も質問しましたけれども、ここに介護保険料も入ってくるわけです。本当に払いたくても払い切れないというのが、今の区民の実態ですけれども、高過ぎるという認識があるかどうかを伺いたいと思います。","respondent":"本城企画財政課長、高森国保医療年金課長","answer":"地方消費税交付金の使途といたしまして、社会保険関係のものにも充当するということがあります。そういう意味で、今回の地方消費税の交付金分が、国民健康保険事業を支える中にも活用されているものです。そういう方につきましては、ぜひ窓口に相談いただいて、個々の事情に合った形で、さまざまな対応をしています。よろしくお願いします。","voiceIndex":277,"id":"exchange-114"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"高過ぎるという区民の皆様と接する区ですから、こういった区民の思いを、ぜひ受けとめていただきたいと思うのです。ですので、高過ぎるという認識があるかないかを伺いたいと思います。ですので、さらに一般財源投入がしていけるということだと思いますので、そこにさらに保険料軽減、引き下げこそ進めるべきと思いますけれども、いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"今、国保のいろいろ保険料等、ほかの保険料の話もありましたけれども、やはり社会保障費が、全体としてすごく負担が増えている中で、応分な負担をしてもらわないと、これからの制度的なものが持続できないという認識があります。","voiceIndex":280,"id":"exchange-115"},{"speaker":"高橋委員","kind":"質問・要望","question":"よろしくお願いします。４４ページの特別区民税、それと１２６ページの減債基金繰入金と、３７６ページ、公債費との関係についてお伺いします。先に特別区民税のほうなのですが、確認させていただきたいのです。数字的なことで申し訳ありません。２月１日、直近では３７万２,２３４人。どのような見積もりで年金所得者の人数を同人数としたのか、確認なのですが、お伺いします。","respondent":"黒田税務課長","answer":"見込みの中では年金徴収される人数は、今回の高齢者の人口の推移からしても、それほど納税義務者としては増えないのではないかと推計しておりまして、１万５,９００人としているものです。","voiceIndex":283,"id":"exchange-116"},{"speaker":"高橋委員","kind":"質問","question":"ほぼ同じ数字で計算をされて見積もりしていくという形で、今のお話だと、所得の関係とのお話ですけれども、次年度等に関しても、このような形で見積もりの状況は続いていくのでしょうか。","respondent":"黒田税務課長","answer":"年金のみの収入でありますと、老齢基礎年金だけですと、なかなか住民税が出るという額にはならないのですが、年金のほかに給与所得、いわゆるアルバイトをされているということであれば、その分、普通徴収として住民税が発生するということはあろうかと思いますが。","voiceIndex":285,"id":"exchange-117"},{"speaker":"高橋委員","kind":"質問","question":"今の年金のお話はここまでにします。２月に入り、もう新聞報道にもあるように、平成２６年度個人住民税徴収対策会議において、「オール東京特別徴収推進宣言」が採択されました。そこで、平成２９年度の指定に向けて、区ではどのようなスケジュールで臨むのかお伺いします。その際、このような影響を受けるというか、対象になるような方々の割合の数字をもし把握されていたら、あわせてお伺いします。","respondent":"黒田税務課長","answer":"基本的に未納がなければ、特別徴収も普通徴収も徴収率は１００％ですので、そういったところも勘案しながら、対象の事業所について抽出して、切替えを進めてまいりたいと考えています。","voiceIndex":287,"id":"exchange-118"},{"speaker":"高橋委員","kind":"質問","question":"事実上、選択制となっております。ご苦労もあるかと思いますけれども、割合をできるだけ広げ、そして、今お話があったように、影響が及ぶ方々には、早期にお伝えして、準備などの支援、あるいはご相談に乗って、その体制を支える形をお願いしたいと思います。１２６ページの減債基金繰入金についてです。ほかのものは充当が書いてあるのですが、どのような理由なのかお伺いします。","respondent":"本城企画財政課長","answer":"減債基金繰入金につきましては、一般財源の扱いになるということで、このような説明欄の記載がほかの事業と異なっているものです。","voiceIndex":289,"id":"exchange-119"},{"speaker":"高橋委員","kind":"確認","question":"減債基金なのですが、一般財源と同じような形で使われることがあるという確認でよろしいですか。","respondent":"本城企画財政課長","answer":"そうですね。一般財源の扱いになっているので、そのような表記になっているという意味です。","voiceIndex":291,"id":"exchange-120"},{"speaker":"高橋委員","kind":"質問","question":"一般財源としての部分も持ち合わせているということですね。平成２５年度の決算審査の資料によりますと、元利償還金は、平成２７年度から平成３０年度までで１１５億円強となっています。平成２７年度は、４年ぶりに区債の発行が予定されています。これも積み立て不足ということにはならないのでしょうか。今後の繰り入れと積み立ての計画はどのような形になっているのか、お伺いいたします。","respondent":"本城企画財政課長","answer":"その点からして、今後の当面の方針といたしまして、純粋な一般財源の対応ではなくて、起債に当たっても財調制度を有効に活用しながらということで考えておりますので、今までに既に起債して残高となっているものを、償還時に基準財政需要額対応ができるということで。","voiceIndex":293,"id":"exchange-121"},{"speaker":"高橋委員","kind":"質問","question":"財調の手当がある起債をされているということですが、基金として積まれているという言い方がわからなかったです。すみません。時間がないので、この件は、また後日改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-122"},{"speaker":"本多委員","kind":"意見","question":"９４ページ、学校施設整備費、１１６ページ、都補助金、学校施設整備費、それと１００ページ、都負担金の水道管直結化事業、７４ページ、住民基本台帳証明手数料など、何点か端的に聞いていきます。初めに、９４ページの学校施設整備費、１１６ページの都補助金、学校施設整備費の校舎等整備について説明してください。","respondent":"品川庶務課長","answer":"９４ページの学校施設整備金です。主なところとしましては、非構造部材関係です。この歳入の計上となっています。それから、細かいところとしましては、トイレ改修、太陽光発電の設置を含んでいる形です。１１６ページの校舎等整備です。","voiceIndex":297,"id":"exchange-123"},{"speaker":"本多委員","kind":"質問","question":"９４ページの学校施設整備費で、今伺ったものの下の御殿山小学校です。この御殿山小学校を挙げると、教育委員会が出された４つのコンセプトでつくられた。２つ目は、生活しやすい教室配置による、学習意欲を高める空間づくり。いろいろな設備だけではなくて、防災面でも、本当に充実してきていると思うのですけれども、そのあり方と補助金等のかかわりについて教えてください。","respondent":"品川庶務課長","answer":"例えば、補助対象外としましては、実験の机や電話機や消火器、要するに動かせるものに対しては、基本的には補助の対象外となっています。逆に、固定されている衛生機器やエアコン、こういったものに関しては補助の対象という考え方でやってあります。","voiceIndex":299,"id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"今の答弁と重なるかもしれないのですが、エコスクールという点ではいかがですか。","respondent":"品川庶務課長","answer":"例えば、御殿山小学校ですと、風力発電をつけたり、太陽光発電をつけたり、そういうことでエコスクールを進めております。今回、芳水小学校に関しましても、そういう部分でいろいろやっていけるところはないかと検討していく考えです。","voiceIndex":301,"id":"exchange-125"},{"speaker":"本多委員","kind":"質問","question":"取り上げる、取り組むということで、補助金とのかかわりを教えてください。","respondent":"品川庶務課長","answer":"エコスクールをやりますと、基本的には補助金の単価が上がるという効果があります。そういうところでも続けていきたいと考えています。","voiceIndex":303,"id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"空間づくりについて伺うのですけれども、従来、一般論でいくと、校庭やグラウンドは南向きが望ましいと思うのです。教室についても、東向きであったり、南向きであったりという一般論がありがちだと思うのです。そういった空間づくり、教室のあり方とか、光の具合とか、今はどのようになっているのか教えてください。","respondent":"品川庶務課長","answer":"基本的には、一番教室が日当たりがよくなるような形で重視しています。グラウンドにつきましても、当然、日当たりのいい方向に設置するとか、職員室から校庭がよく見える形といったところを考えながら、基本設計へこれから進んでいこうと考えています。","voiceIndex":305,"id":"exchange-127"},{"speaker":"本多委員","kind":"質問","question":"この御殿山小学校は本当に充実されていて、これからも順次、区内の全小学校、中学校を対象に改築が進められていくと思います。そういったところで、今まで何点か聞いたのですけれども、例えば、複合施設になった場合の補助金のあり方について説明いただければと思います。複合施設についても、その使途によっては全然違うと思うのですが、複合施設としての補助金とのかかわりについて教えてください。","respondent":"品川庶務課長","answer":"複合施設といって、一部学校の用途としてやっていけるような部分については、補助の対象にしていくかどうかというところは、要検討という形になるかと思います。","voiceIndex":307,"id":"exchange-128"},{"speaker":"本多委員","kind":"質問・要望","question":"１００ページに行きます。負担金の水道管直結化事業、１０分の８、１,６５６万８,０００円。歳出で見ると、３６５ページで、水飲栓直結化工事ということで、これは都の負担金の区分の名前で、細かいことを言うのですけれども、この名称の違いを説明いただきたい。これは対象外になるのか、算定になるのか、その辺についても教えてください。","respondent":"品川庶務課長","answer":"補助につきましても、東京都で１０分の８の負担が出ております。ただ、方式の違いによって、６割の負担になる場合もありますが、基本的に今年度対象としている学校につきましては、１０分の８の負担という形で進めている状況です。","voiceIndex":309,"id":"exchange-129"},{"speaker":"本多委員","kind":"意見","question":"次に行きます。来庁される方が非常に多くて、事務も本当に多忙を極めていると感じるのですけれども、それまでの平成２８年までの間、現在のとおりで行くのか、人的な措置や、空間的なものとか、番号札が出る電子板ですとか、何か対策というか、工夫をしていくのかお聞かせください。","respondent":"井浦戸籍住民課長","answer":"具体的には、先ほど委員からの紹介もございましたように、平成２８年９月以降はコンビニエンスストア交付ということでシフトしてくるわけですが、その間の具体的な対策としましては、一番大きなメリットとしましては、コールセンターを平成２７年度の途中から導入いたしまして。","voiceIndex":311,"id":"exchange-130"},{"speaker":"本多委員","kind":"質問・要望","question":"過料５万円ということなのですけれども、これは科目存置と同じような考え方で、予算の数字を載っけていると思うのです。当然、過料をとることが目的ではありませんから、区民の人たちが生活しやすい環境づくり、そして、真面目に商売をやる方たちの商売繁盛を願って、悪質で執拗な客引きを排除するということですから、過料が目的ではないけれども、過料をもっと取るような、積極的なところを教えてください。","respondent":"上垣外生活安全担当課長","answer":"今、委員がおっしゃるとおり、条例上は５万円という過料を科しているところであります。他区の例を見ますと、既に過料をつけて施行しているところがありますけれども、まだ、この過料を科しているところはないというところを聞いています。","voiceIndex":313,"id":"exchange-131"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは６３ページのこみゅにてぃぷらざ八潮について、そして、１２４ページ、寄附金について、ふるさと納税についても触れします。初めに、こみゅにてぃぷらざ八潮なのですが、この中にある美術工芸室というのはどのような部屋で、何かほかの施設と違って特色があるのか、教えていただきたいと思います。よろしくお願いします。","respondent":"安藤文化スポーツ振興課長、江部総務課長","answer":"私からは、こみゅにてぃぷらざ八潮の美術工芸室につきまして、ご説明します。やはり美術工芸室ですので、ろくろを回す機械や、お隣には窯も用意しています。そういう部屋です。広報につきましては、税務課でありますが、ふるさと納税は、控除の対象になりますということを伝えながら寄附を募っているという現状です。","voiceIndex":316,"id":"exchange-132"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜここを聞いたかというと、歳入のところにさまざまな使用回数等の記載がされている中で、この部屋がほかの施設とか、こみゅにてぃぷらざ八潮の中でも、非常に使用回数が少ない７０回と記載されていて、なぜここだけこんなに少ないのかと思いました。その点をもう一度お答えください。その辺の取組みも、ぜひ行っていただきたいと思いますが、改めてお考えをお知らせください。よろしくお願いします。","respondent":"安藤文化スポーツ振興課長、江部総務課長","answer":"こみゅにてぃぷらざ八潮の美術工芸室です。平成２３年３月にオープンしまして、これでやっと４年を迎えました。それで、５年目に突入しました。この間、利用率で言いますと、４２.８９％と、非常に高い数字があります。特定の事業に対する寄附をということもあります。品川区に合った寄附の新しい形につきまして、そういったもの全体としてどういう方向に進むかということを、まさにこれから検討を進めてまいりたいと考えております。","voiceIndex":319,"id":"exchange-133"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"こみゅにてぃぷらざ八潮、ものすごく頑張っているのはわかっているので、せっかくいいものがあるので、その活用をぜひともお願いしたいと思います。寄附金なのですが、ぜひ検討を進めていただきたいと思います。そういったさまざまな手法を使って、ぜひ取り組んでいただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"先ほども質問がありました。平成２８年９月でコンビニエンスストアでの交付が始まるということで、いろいろ質問してきた者としては、本当にやっとかというところだと思います。先ほど、人件費の話も出ておりましたけれども、手数料の基本的な考え方についてお伺いしたいと思います。区としての腹づもりというのでしょうか。現行の３００円から安くするかどうかという心づもりがありましたら、教えてください。","respondent":"井浦戸籍住民課長","answer":"手数料そのものの考え方です。明確な積算というものはないのですが、基本的には１件当たりをコスト計算しますと、七、八百円かかるかです。そこを、現在３００円で行っているというところで、充当率ということで、一定の率を考えているところです。","voiceIndex":324,"id":"exchange-135"},{"speaker":"浅野委員","kind":"質問","question":"確かに、実際にはコストもかかっていますし、そのコストには接続するためのコストもかるかと思います。次の質問に移ります。路面維持管理費です。今年度は避難所周辺の道路と、緊急啓開道路、こちらを中心に行ったと伺っておりますけれども、発見された道路下の空洞の状況、数と、実際に修繕したという箇所数についてお伺いします。こういう調査をやっている上で、特徴等があれば教えてください。","respondent":"稲田道路課長","answer":"平成２６年度ですが、調査を実施しましたところ、陥没が起きやすい、浅い部分にある、道路表面近くにある空洞が、全部で１２カ所発見されました。大きさ的には、厚さ１０センチから２０センチ程度、それから、幅が平均で７０センチ、長さが１.１メートルです。","voiceIndex":326,"id":"exchange-136"},{"speaker":"浅野委員","kind":"質問・要望","question":"まだそういう段階には来ていないのかもしれませんが、情報共有というのは、ある程度必要になってくるかと思いますので、今後、努力していただければと思います。これらの事業については、国とか都から補助金が入っておりますけれども、平成２７年度で、これは全部終わるのか、それともまだまだ残って続いていくのか。なるべく早くやっていただきたいと考えていますが、この点はいかがでしょうか。","respondent":"品川庶務課長","answer":"区としましても、今改築している御殿山小学校を除いて、全校が対象になります。非常に多い数ですが、何とか平成２７年度中に工事を完了していくことで進めている状況です。","voiceIndex":330,"id":"exchange-137"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも早期完成を要望したいと思います。そういう意味では、完成した状態を維持していくということが重要だと思います。このような体制を維持する、また確認する、そして、手順といいましょうか、何かをするときには、こういうことをしてはいけないとか、そのようなこともしっかりと周知していく必要もあるかと思います。今後の考え方、また管理方法について教えてください。","respondent":"品川庶務課長","answer":"こういうところを誤りますと、非常に大きな事件につながりますので、この工事が終わった後の点検もしっかりやっていって、学校施設、特に児童・生徒等が使う施設です。非常に重要な施設ですので、その辺については、しっかりとやっていきたいと考えています。","voiceIndex":332,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"歳入の９３ページ、１１３ページ、補助１６３号線整備に関連してお聞きしたいと思います。１６３号線、平成３２年完成目途とも聞いていますけれども、ここの工事と、ＪＲの線路をくぐるところ、先ほど話がありました新幹線の再開発のところ、３つの工事があるのですけれども、これも全て平成３２年に完成するのでしょうか。これらの方たちには、もうお話が行っているのでしょうか。","respondent":"稲田道路課長、溝口都市開発課長、中村都市計画課長","answer":"この区間を完成させていきまして、順次、ＪＲの貨物のところを通って、西品川に向かっていくというのを、高低差や非常に難解な部分がありますので、今後。補助１６３号線の工事で、西品川一丁目地区の再開発事業にあわせての工事の期間です。再開発事業は、平成３０年度の完成を目標に、今現在、動いております。ただ、工期につきましては、短くなるという情報はございませんが、なるべく早く完成していただくように、区からもお願いしてまいりたいと考えております。","voiceIndex":335,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問・要望","question":"交差部は平成３２年目途。わかりました。ほかが順次遅れていくということですけれども、始まってくると、情報というのは欲しいものですから、やはり情報をしっかりと提供していただきたいと思います。二重投資なのかと、それとも、このトンネル部分だけ、すぐ壊せるようにしてあるのかと思いながら見ていたのですけれども、その辺はどうなのでしょうか。確認をしておきたいと思います。","respondent":"溝口都市開発課長","answer":"そういったところで、その先の工事も見据えた形で、ＪＲと協議しながら進めておりますので、多少構造物としては壊さなければいけない部分が出てきますが、歩行者の暫定利用という形で開放しなければいけない関係上、擁壁をつくっているところです。","voiceIndex":339,"id":"exchange-140"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうすると、壊すような感じになっているということでいいですか。あそこを見たときに、青いラインでも、黒いラインでも、赤いラインでも、ここがトンネルということがわかると、「ああ、ここがトンネルになるのだな」と思うのです。その情報を区民に知らせていただきたいと思います。今、補助１６３号線は、随分車が通るのです。あれは、早急にとるべきだと思いますけれども、いかがでしょうか。","respondent":"稲田道路課長","answer":"停止線の位置も何回か書き直して、できるだけ後続車が直進できるような形もとってきておりますが、現在は仮設の状況で、あれを外してしまいますと、真っすぐぶつかるというような、さらに大きな交通事故も考えられるです。","voiceIndex":341,"id":"exchange-141"},{"speaker":"松澤委員","kind":"意見","question":"これは、利用者と全然考えが違う。あれを外したからといって、あそこでぶつかることは考えられない。それに、あそこはもともとコンクリートの擁壁があったのです。あれと同じラインならいいのですけれども、もっと車道側に入っています。これは明らかにバスがとまらないために意地悪をしたとしか考えられない。まちの人はみんなそう言っています。もう一度答弁を聞きます。","respondent":"稲田道路課長","answer":"目的がバスではなくて、先ほど言いました、交通の流れ上の事故を防ぐためのものです。ただ、そうは言いつつも、何か安全に通れる方法があるのかどうか、警察とは協議を常にやっていきたいと考えています。","voiceIndex":343,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"私は、９４ページ、国の教育費補助金、学校施設整備費についてお伺いいたします。先ほどからお話が出ております、学校の防災、避難所機能の強化ということで、大空間の非構造部材の改修という工事を、この補助金をもとにやるわけです。予算の内訳をお聞きしたいのですが、これは国の補助金だけで、区の予算は使わないで済んでいるのでしょうか。","respondent":"品川庶務課長","answer":"こちらの非構造部材を中心とした学校整備費につきましては、国が３分の１の補助となっております。それから、少しページをおめくりいただきまして、１１７ページには、東京都の補助が１,０００分の１６６ついてあります。それ以外につきましては、区費で対応しております。","voiceIndex":346,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"我々は、全ての公立小・中学校の耐震化は既に済んでいるという説明を受けたと思うのです。何かそこがおかしくないのかと思います。これは何かおかしいと思うのですが、どうなのですか。ご見解をお聞かせください。","respondent":"品川庶務課長","answer":"要するに、建物が耐震化されていても、建物に付属しているものが地震によって落ちてしまって、結局避難所としての機能を果たせない場合があります。こういった部分を解消するために、今回の非構造部材の耐震化を進めていくものです。","voiceIndex":348,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"ということは、今まで危険だったという考え方で、ずっとそこに子どもたちは教育現場にいたわけで、一般の町会の近隣の方も、ここは安全ではなくて、いつ落ちてくるかわからないところへ集まって、避難訓練をしているのですけれども、それは変だと思うのです。もう一度教えてください。","respondent":"品川庶務課長","answer":"そもそもは、建築基準法に則って、当然、学校施設もつくっていったという経緯があります。ただ、今回の非構造部材につきましては、この建築基準法の改正によってやっていくという方針が出ました。","voiceIndex":350,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"平成２２年８月に文部科学省から既に提示されて、学校施設における天井等落下防止対策のための手引きが、この時点で出ています。それで全く手をつけられなかったのか、つけなかったのか、品川区としては、経緯を見ていたという考え方なのですか。しかし、実際はそういう指針、ガイドラインがあったにもかかわらず、なぜやらなかったのですか。危険だったわけですよね。","respondent":"品川庶務課長","answer":"基本的に指針にのっとって全てを行っております。今回の非構造部材につきましては、この指針が変わった部分について予算計上しているものです。","voiceIndex":352,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"これははっきり言って、国の責任です。何で区の予算を出さなければいけないのですか。中にいる子どもたちから、これは２カ月、３カ月かかるような話を聞きました。今、どうお答えしてくれるかわかりませんが、教育現場にいる子どもたちというのは、日々成長しているわけです。本当にそういうことを思うと、やはり私は国に物を申すべき。大変大切なことだと思うのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"ただ、安全が第一です。安全をしっかりしてから、学校施設の運営を行っていかなければいけないと思いますので、その間は校長、教員から、全ての皆様にいろいろ工夫をしていただいて、非構造部材の耐震化を進めていただきたいと考えています。","voiceIndex":354,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"私は平成２２年８月に文部科学省のガイドブックが出ていなければ何も言いません。「皆様、こういうふうに直してください」という話は来ているわけでしょう。最後、話を聞いていて、国がこういうことでぼんぼん変えていくのはいいけれども、各自治体は一生懸命やっているのですから、私はそういうことをきちんとやっている自治体は、しっかり国に物を申すべきだと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０２ページから１０７ページにかけての保育園の補助金関係、そして、５４ページの保育園保育料についてお伺いしたいと思います。このことについての区の考え方を聞かせていただきたいのが１点です。もう一つは、区立の認可保育園をつくる場合、先ほどの答弁だと、「国や東京都の補助金はない」という答弁だったと思うのですけれども、そこのところを改めて確認させていただきたいです。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"現在、子ども・子育て計画に載っておりますとおり、私ども、新規開設認可保育園は、本年度４園です。それから、来年度４園。そして、今後、３園ということで、時機を見て開設の整備数を計画のとおり進めていく予定です。考え方をお示しする前に、過去の補助の状況をご説明しますと、平成２４年度ですと、９,１６８人の子どもたちに対して、８億１,７００万円の助成を行っております。平成２５年度が、９,４３４人に対して、８億２,８００万円。","voiceIndex":358,"id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、私立の補助金はわかったのですけれども、区立認可保育園をつくる場合の建設費が幾らかかるのか。国や都の補助金はないのか。その場合、財調などはどうなるのか。１００人規模の区立認可保育園をつくるとしたら、区の負担が幾らかかるのかということでお聞きしましたので、この点についてもお願いします。","respondent":"今井制度改革・待機児童対策担当課長、本城企画財政課長","answer":"１００人規模の定員です。先般来、幼保一体施設で建設してまいりまして、今回も五反田第二保育園が５０人規模なので、想定とは違うものですけれども、一応２億円程度という形で考えているところです。区立保育園整備の財調について、現段階で算定はありません。","voiceIndex":361,"id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"２億円というのは、５０人規模で２億円ということでいいのでしょうか。そのことを確認させてください。区立保育園の運営費というのは、事務事業概要で見ると、大体７６％ぐらいが区の負担ということで書かれているのですけれども、年間２億円くらい運営費がかかるということで、前、どこかの委員会の中で答弁があったと思うのです。このことについてもお聞かせください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"５０人規模ではございませんで、１００人程度と考えております。","voiceIndex":364,"id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区立保育園の運営費なのですけれども、先ほど区の負担というのは、１億５,０００万円くらいでいいのかということで、教えてください。","respondent":"竹田保育課長","answer":"区立保育園の事業経費ですが、平成２６年度で見ますと、総額が８６億円余となっておりますので、それを割りますと、おおむね２億円になります。平成２５年度の決算ベースで、区立保育園ですが、１園当たりの平均が、約１億８,０００万円余となっております。","voiceIndex":366,"id":"exchange-152"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"建設費が約２億円で、運営費が約１億８,０００万円ということで、確認させていただきたいと思います。私は、そういうことで、区立認可保育園を柱に、これからも増設していただきたいと、強く要望しておきます。その点が１点です。そのことはいかがでしょうかということが２点目です。私はここにも保育料の助成をすべきだと思うのですけれども、この保育料助成の３点についてお伺いしたいと思います。","respondent":"金子子ども未来事業部長、竹田保育課長","answer":"申し訳ないのですが、先ほどの答弁について、若干訂正させていただきたいと思います。私が保育課長をしていました平成１５年前後、大体１００人規模ですけれども、概算で建設費２億円、運営費２億円といった数字でありました。保育園につきましては、ゼロ歳児から５歳児、就学前までということで、同じ期間を対象にして、第二子、第三子と考えているものでございまして、こちらは国の制度の横引きといいますか、参考にさせていただいているものです。","voiceIndex":368,"id":"exchange-153"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私から４５ページ、滞納繰越分収入見込額について、それに多少関連して、４６ページの軽自動車税と、５２ページ、交通安全対策特別交付金について、１３４ページの競馬場関係についてお伺いします。ここまでご努力されているわけですので、以前にもお伺いしましたけれども、どういった対応をされているか。多分、その他というか、まだほかにあったと思うので、その確認をお願いしたいと思います。","respondent":"黒田税務課長、江部総務課長","answer":"そういった意味で、現年度分の住民税を取りこぼしなく徴収するということで、翌年度の滞納繰越額を減らすという意味では、今年度は「現年班」という形で、納税相談担当の１つの係で現年催告を強化しまして、昨年度より電話催告を中心に。午前中のご質問で、１号、５号、６号の交付金ということで、当初予算に計上があるとご説明させていただきました。毎年、最終補正で組合利益の最終の利益を分配する分配金が今回の補正予算で３,０００万円。","voiceIndex":372,"id":"exchange-154"},{"speaker":"いながわ委員","kind":"質問・要望","question":"滞納繰越分については、今３０％という話をしたのですが、それは予算であって、結局、決算のところになると、結構徴収率が上がって５０％になっているので、今回、平成２７年度予算ですから、決算が平成２８年、先にあると思うのですが、それが５０％以上になるようにご努力していただく。よろしくお願いします。以前といっても１年前ぐらいだったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":375,"id":"exchange-155"},{"speaker":"いながわ委員","kind":"質問","question":"インターネットは４０％ぐらいまで来ていると思うのですが、それも維持管理があるので、１回の売買でいろいろ手数料も取られると思います。例えば、まず興味を出させるということも必要で、そこで買ってみようかという手法も、何かを考えていかなければいけない中で、品川区というか、競馬組合はどういうお考えでいらっしゃるかというのを教えてください。","respondent":"黒田税務課長、江部総務課長","answer":"今のところ、バイク屋が登録に来るということも多い中では、他区にお聞きしますと、無難なところで普通のナンバーを選ぶというところもあると伺っておりますので、今後検討してまいりたいと考えております。委員ご指摘の来場者を増やすということももちろん、全体の売上を伸ばすということも両方であるということで、２３区共同事業ですので、その辺は組合のほうでしっかり取り組んでいただいていると認識しております。","voiceIndex":376,"id":"exchange-156"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点、５２ページの交通安全対策特別交付金をお伺いするのを忘れていました。これは、実際、多少減額になっているのですが、どういった性質のものなのかを教えていただきたいと思います。特に交通事故がゼロになっているわけでもないのに、何で減額されてしまっているのかというのを教えてください。競馬場に関しては、もう１点だけ。その辺、品川区はどう考えているかお聞かせください。","respondent":"本城企画財政課長","answer":"反則金の納付額を国全体で集めて、都道府県を通じて、各市町村に交付するということになりまして、全体の反則金の総額が減少傾向にあるということで、今、平成２５年と平成２６年を見ても、約２割方減少しているということで、その推移を踏まえて。","voiceIndex":379,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問","question":"私は９３ページの路面維持管理費、それから、１０８ページのシルバー交番設置事業補助金、１２２ページの財産貸付収入で伺いたいと思います。先般、五反田の国道沿いの歩道の陥没があったときに、国から区に、こういう形で、こういう原因で起きて、こういうふうにしっかりやったという報告もないのでしょうか。そこを聞きたいと思います。入っているとすれば、その金額を教えてください。","respondent":"安井土木管理課長、立川経理課長、大串福祉計画課長","answer":"先般、東五反田で発生いたしました国道の陥没事故についてです。ホームページ等では公開されておりますが、直接私どもに報告はございませんでした。旧荏原第四中学校の関係ですけれども、こちらは朋優学院に貸し付けということで、５,２００万円ほど計上させていただいているところです。補助採択の関係で、若干差が出てきているといったところです。少し調べますので、お待ちください。","voiceIndex":385,"id":"exchange-158"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本当は、それが上から来れば一番いいのだろうけれども、来ないのだったら、ぜひそういう体制をつくる努力をしていただきたいと思うのですけれども、そのことについて教えてください。約２年４カ月お貸しになると、行革委員会等、いろいろなところで聞いております。プレス発表のほうで３,３６６万６,０００円となっているのですけれども、ここはどういうことかというのをあわせて教えてください。","respondent":"安井土木管理課長、柏原行財政改革担当課長、大串福祉計画課長","answer":"先ほどの東五反田の事故についてですけれども、私どもとしても、空洞調査等を実施しておりますので、こちらの原因について。こちらにつきましては、今、委員がおっしゃったとおり、２年半ほどということで考えてあります。その後については、今のところ、利用は未定です。プレス発表に出させていただいた３,３００万円余は、いわゆる社会福祉協議会に支払う委託料の金額ということになっております。","voiceIndex":389,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"陥没に限らず、ぜひ品川区内には都道、区道、また国道、橋もありますので、その辺の連携というか、区に聞けば、大体その状況がわかるという体制をつくっていただきたいと要望しておきたいと思います。恐らく、学校等の需要が出てくるのかという気もしないでもないので、この辺も含めて、地元のほうにも、区はどういう考えなのかということは、何かの機会にぜひ教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"そうした中では、スピード感を持ってやっていきたいと考えているところですが、やはりこの事業の主な内容といたしましては、コーディネーターを配置して、地域のさまざまなことに対応していくといったものになっておりますので、その辺の人の採用の問題ですとか。","voiceIndex":393,"id":"exchange-160"},{"speaker":"伊藤委員","kind":"質問・要望","question":"初めに、客引きのところであります。これは、私たち自民党が五反田地域の方々から要望を受けて、大沢委員が質問させていただいて、条例をつくっていただきました。改めて感謝をする次第です。すごく真摯な思いで私たちのところでお話を伺ったのです。要は、この条例を制定されることによって、こういうものがどこまで解決するのでしょうかということをぜひお伺いしたいので、答弁をお願いいたします。","respondent":"上垣外生活安全担当課長","answer":"客引きのみにとどまらず、このあたりに発生するであろう、いわゆる一般的な刑法犯についても、パトロール隊が回ることによって、一定の抑止につながるのではないかと考えております。","voiceIndex":398,"id":"exchange-161"},{"speaker":"伊藤委員","kind":"質問","question":"そのパトロールの話も、今のところ、聞いた話ですけれども、午後１０時ぐらいまでと聞きます。だから、その時間帯に対して、１０時以降、どれだけの効力を発揮していただいて、五反田地域の方々が、わざわざ来ていただいたことに対して条例をつくったわけですから、具体的な展開をどのように、午後１０時以降の対応について、改めてお答えください。お願いいたします。","respondent":"上垣外生活安全担当課長","answer":"それ以降の時間につきましては、区民の方、あるいは警察の力を借りて、こういった抑止に努めていくとともに、区だけではなくて、区民、警察、総合的に取り組むことによって、こういった客引きを許さない雰囲気づくりに努めていきたいと考えております。","voiceIndex":400,"id":"exchange-162"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確かに１０時までで終わりであることは仕方がないのかもしれない。これを東京都はどうしても推し進めていきたいと思っていらっしゃる。同時に、大きな災害に対処していきたいと思うだけならば、やはり評価額について、例えば、引き上げを求めていくとか、新たな視点でこれを展開していかないと、この事業は先に進んでいかないと思うのですが、品川区の見解をお聞かせください。お願いいたします。","respondent":"寺嶋木密整備担当課長","answer":"東京都も、この密集事業、それから１０年プロジェクトを進めるということで、今取り組んでいるところですので、その辺の価格について、どこまで意見が通るかということは別としまして、区としても、もちろん一定程度価格が上がっていただければ、事業が進むという認識があります。","voiceIndex":402,"id":"exchange-163"},{"speaker":"伊藤委員","kind":"質問","question":"この事業の目的とするところは、とても大きな価値あることです。それをつくることによって、多くの方の生命、財産を守るというわけですから、それは長い目で見れば、費用対効果を考えれば、ある程度評価額を上げていくなり、一つの方向性を示していくことは、私は行政の考えとしては間違っていないと思うので、もう一言答弁をお願いいたします。","respondent":"寺嶋木密整備担当課長","answer":"本事業の目的を十分認識した上で、改めて取り組んでまいりたいと思います。","voiceIndex":404,"id":"exchange-164"},{"speaker":"伊藤委員","kind":"質問","question":"確かに、すぐに回答は出ないと思いながら質問しています。でも、地域の方が、せっかくオリンピック・パラリンピックがあるのだからということで勉強会を開いて、ある程度の金額だけれども、無電柱化事業については、補助金も少し出てくる中にあって、やはり品川区の一つの構想としては、検討していくなり、話を聞くなりしていくことは、まず第一歩かと思うのです。改めて答弁をお願いいたします。","respondent":"稲田道路課長","answer":"私どもの道路のところで言いますと、会場周辺から交通の要所のところまでというところで、東京都と協議しながらやってきている。それが条件であるというところでやっておりまして、大井町周辺まで、その構想を延ばせるかというと、なかなか今のところは考えておりません。","voiceIndex":408,"id":"exchange-165"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひ区長にお伺いしたいのが、オリンピック・パラリンピックを迎えるわけでありますから、今まで招致活動もやってこられたし、品川区内でも、これだけの競技が開催されるし、あわせてインフラ整備も行われる中で、改めて区長としての思いと、オリンピック・パラリンピックにかける情熱をお聞かせください。お願いいたします。","respondent":"濱野区長","answer":"これが一番大事なことかもしれませんが、オリンピック・パラリンピックを契機にして、子どもたちの体力向上、あるいは運動能力の向上といったいろいろな面において、品川区としてしっかりと取り組んでいくことが必要だと考えています。","voiceIndex":410,"id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":116328,"voices":412}},{"id":"h27-20150305-3","meetingId":"h27-c-budget","date":"2015年3月5日","dateIso":"2015-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２７年度品川区一般会計予算","agenda":"平成２７年度品川区一般会計予算","exchanges":[{"speaker":"本多委員","kind":"質問","question":"１５１ページの危機管理室経費について伺います。最初に、区施設、事業等運営サポート経費、宿日直経費等と書かれていますけれども、内容についてお知らせください。","respondent":"江部危機管理室長","answer":"危機管理に関するお尋ねです。区施設、事業等運営サポート経費につきましては、区の出先施設、図書館、文化センター等での不審者対策ということで、警備員を配置しているものです。それから、宿日直経費につきましては、管理職が行っております２４時間危機管理宿直経費等です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"本多委員","kind":"意見","question":"これまでも、危機管理については、皆様が必ず２４時間体制で備えをしているということは存じ上げております。サイバーテロも含めて、テロ対策を徹底的に強化する」と語っておりましたけれども、東京都がそういった方針ですが、２３区として、品川区として、これに対して、今後どういうふうに捉えていくのか。品川区の役割等についてお知らせください。","respondent":"江部危機管理室長","answer":"ただ、区だけで守れるわけではございませんので、警察、消防、その他、テロ対策に携わる関係機関との連絡調整ということが重要になってくると考えております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"台風のときですとか、水害のときに災害対策本部を立ち上げられますけれども、それとは別に、警察、消防、自衛隊、電気、ガス、上下水道等、有事に備えて、そういった連絡というのでしょうか。災害対策本部の天災に対する連携も、もちろん重要ですが、それ以外に対しての連絡とか、連携を強化するといった、その辺についてはどのような考え方か、お知らせください。","respondent":"江部危機管理室長","answer":"そういった意味で、情報共有ということでは、官公署連絡会というのを年３回やり、消防、鉄道事業者、警察の皆様方と、課題があればそこで協議をするです。ただ、さらにテロ対策につきましては、もう少し綿密な、協調を深める取組みが必要になってくるというふうに考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"防災協定だと、少し遠距離の自治体と、現実に協定をもう結んでおりますけれども、そういった遠距離の自治体との連携が有効だと思うのですが、近隣区との連絡、連携というのは、特に必要かと思うのです。今言われた鉄道事業者やその他の官公署との連絡という話もありますけれども、近隣の自治体との連絡等、そういうことについてはいかがでしょうか。","respondent":"江部危機管理室長","answer":"これは以前から結んでいるものです。それから日々の業務の中では、やはり事があったときには、危機管理室であったり、防災課であったりが窓口となりまして情報共有するということは行われておりますので、そこを充実させていくという考え方であろうと考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"わかりました。それ以外でいくと、東京都第二建設事務所との連絡といったものが、本当は区長からの指揮系統で指示が出せて動かせられれば有効かと思うのですが、その辺についていかがでしょうか。それから、昨今、自衛隊と防災訓練ですとか、いろいろなところで連絡をされておりますけれども、自衛隊との連絡の強化等、その辺についてはいかがでしょうか。","respondent":"江部危機管理室長","answer":"年１回の全庁の自衛消防訓練を実施いたしまして、避難や消火等の訓練をやっているものです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"本多委員","kind":"意見","question":"突然違うことを聞いて、すみません、しながわ中央公園の、ＪＴの跡の拡張なのですけれども、ヘリポート機能が整備されますけれども、ヘリポートの機能というのは、区内でどのくらいあるのか、お知らせいただければと思います。","respondent":"鈴木防災課長","answer":"区内にありますヘリポートのお尋ねですが、現在、品川区の地域防災計画で指定をしておりますヘリポートは４カ所です。それから、しながわ中央公園は、ヘリポートの整備が終わり次第、計画に追加をするということで考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"わかりました。それから、今、何か有事の際に炊き出しをしなければならないとなったときに、何人分、何日分くらいの備えがあるのか、また、その辺についての今後の考え方について、教えてください。","respondent":"鈴木防災課長","answer":"２日目の分を東京都のほうが備蓄、３日目については外部から都が調達をして、広域の支援を受けるというのが、現在の体制になっております。ただ、ただいま東京都と区で協議をしておりまして、備蓄だけで３日もつように、少し充実させようということで協議しています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"区有施設ですが、小山台二丁目にある国家公務員宿舎跡地、今年の夏頃でしょうか、全ての方が転居されると認識しています。そうした中で、広域避難場所である林試の森公園と一体的な防災に資する整備、また福祉に資する施設が欲しい、こうした地域からのご要望も伺っているところでありますが、区の現在での構想、そしてまた、地域住民の声をどのように反映していくのか、教えてください。","respondent":"柏原行財政改革担当課長","answer":"その地域性のところから考えますと、防災面での活用は、やはり大きな考え方になってこようかと思いますので、土地はかなり広い部分はありますけれども、そういったところを中心に、東京都と連携を図りながらどういった活用ができるのかというのは、引き続き、現在。","voiceIndex":19,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"地域の住民の声ということでもあれだったのですが、しっかりとそうした方々の声を伺いながら、品川区としての構想をつくっていただきたいと思います。そうしたことも含めて、将来的には小山台住宅跡地活用の中で歩道の拡幅をしていくことが求められるところでありますけれども、先ほど申し上げた現状からも早急に何らかの対応が求められるのかと思います。","respondent":"柏原行財政改革担当課長","answer":"先ほどのご質問の中でも、地域のお声ということでございまして、こういった土地の取得を検討する際には、どこの土地でもそうなのですけれども、地域の方のお声を聞きながら検討しているものです。個別に、今、木のお話がございました。","voiceIndex":21,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"本当に、歩行環境については、強くお声をいただいているところであります。次にいきます、１６３ページ、固定資産台帳整備、公共施設等総合管理計画策定委託に関してです。そのうえで、どのように平成２７年度でこの台帳の整備を進めていくのか、また、複式簿記・発生主義の導入についても、どのように進めていくのか、教えてください。","respondent":"立川経理課長、本城企画財政課長","answer":"来年度に向けましては、既存の各種台帳を固定資産台帳のほうに取り込んでいくということで、その辺のシステム的な部分についてやっていくということで、こうした経費を計上しています。基本的なマニュアルも、今度は案ということで、きているところですので、それ以外に独自でやっているものなどの動向も見据えながら。","voiceIndex":23,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"改めて機会を通じて確認していきたいと思います。次にいきます。改めて、平成５年当時の議事録を振り返ってみて、「人権宣言」の制定を求める請願、採択をした自民党、公明党、社会党、民社党の４党の代表が紹介議員となって、議員提出第６号議案、人権尊重都市品川宣言に関する決議が、賛成多数で可決したことを踏まえて制定されたことを見ても、改めてその重要性を認識したところであります。","respondent":"江部総務課長","answer":"シートにつきましては、確かに配布していますが、いつからというのは、確認してみないとわかりません。","voiceIndex":26,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"このシートそのものは、いつつくられたのでしょうか。","respondent":"提坂人権啓発課長","answer":"申し訳ありません、平成５年に人権尊重都市品川宣言を行ったのは間違いないのですが、シートをつくった時期は、不明です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"次にいきたいと思います。１５７ページ、広報経費です。昨年の第２回定例会で提案をさせていただきました、動画によるバリアフリー情報の提供であります。それを含めて、さきの提案も含めて、ＹｏｕＴｕｂｅを採用されたということから、車椅子利用者などに実際に出演をいただいて、動画によるバリアフリー情報の提供を、改めて提案をさせていただきたいと思いますが、その辺の検討状況を教えてください。","respondent":"荒井広報広聴課長","answer":"障害者の方や車椅子を使った方から見た、バリアフリーの視点から見たアクセス、道案内といいますか、地域案内のご提案だったと記憶しております。所管の障害者福祉課とともに検討しながら、どういった形であれば可能であるかというのを進めているところです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"最後に１４７ページ、オープンデータ推進経費について、簡単にお伺いしたいと思います。これも、昨年の第２回定例会で具体的にオープンデータプラットホームの採用などを提案させていただいて、そのものを採用しての活用を、大いに歓迎したいと思います。アプリ開発社との活発な交流も望まれるところだと思いますが、最後に、今後の具体的な推進計画について、教えていただきたいと思います。","respondent":"秋山情報システム課長","answer":"現在、ご指摘のように、避難所、公共施設、自治体情報等を出していますけれども、今後、既に公開している人口統計であるとか、観光情報であるとか、ＡＥＤの位置とか、そういうものについてオープンデータとして公開をしていく予定です。","voiceIndex":32,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"議会各会派からも、それぞれ推進について声が挙がっているところでありますので、さらに区民へのサービスの向上、またビジネスチャンスの拡大、こうしたことも含めて推進していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"私からは、１６５ページの地域振興事業、そして１６９ページの歩行喫煙防止推進経費、１７３ページのオリンピック・パラリンピック開催周知事業、そして時間がありましたら、１８５ページの徒歩帰宅者支援経費について、伺いたいと思います。品高連等については、今後、調査研究課題になるとのことでしたが、その後の検討状況はいかがでしょうか、あわせて伺いたいと思います。","respondent":"久保田地域活動課長","answer":"減もないです。品高連のほうの関係につきましても、高齢者いきがい課のほうと連携しながら、検討を進めているというところでございまして、調査研究を引き続き行っているところです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問・要望","question":"引き続き質問をさせていただきたいのですけれども、今、更新状況というのはどのようになっているのか、伺いたいと思います。","respondent":"久保田地域活動課長","answer":"年に１回以上は更新しているといったところが１４町会・自治会で、残念ながら、この１年間で更新がされていない町会・自治会が１１あるというところでございまして、こうしたところへの働きかけが、今後の課題かと思っているところです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"町会ホームページについての取組みや方針について、また今後も一生懸命取り組んでいただけたらと思います。あわせて、平成２６年度の予算では、町会ホームページ運営支援等に４９９万１,０００円に対して、来年度の予算では２０１万３,０００円となっておりますけれども、半額になっているのは、どういった理由で減らしているのか伺いたいと思います。","respondent":"久保田地域活動課長","answer":"町会ホームページ運営支援等の経費ですけれども、減の主な理由は、１３地区ごとにそれぞれの町会・自治会の活動を紹介するパンフレットの作成を、各地区の連合会に委託をしているのですけれども、その事業が完了したということで、平成２７年度には計上していないです。","voiceIndex":40,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"１６９ページの歩行喫煙防止推進経費について、伺いたいと思います。巡回指導等委託のところでありますが、前年度と比べて５万円増えております。これは、品川区での歩行喫煙者が増えたことを意味するのか等、その増額理由について、ご説明いただきたいと思います。","respondent":"上垣外生活安全担当課長","answer":"増えている理由につきましては、大崎駅周辺におきますたばこの吸殻の量が増えたことに伴いまして、巡回して監視をする時間を増やしております。これに伴う増額であります。","voiceIndex":42,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"この路面表示板設置等工事とありますが、この「等」というのはどういったものなのか、内容を教えていただきたいと思います。","respondent":"上垣外生活安全担当課長","answer":"路面表示のほかは、例えば、ガードパイプにつける横断幕、こういったものが入っております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"歩行喫煙防止の取組みの中には、区民の方々の自主的なものも含まれているとお伺いしております。東京都では、オリンピック・パラリンピックを見据えた方針として、受動喫煙防止対策を掲げており、第１回定例会では、港区の環状２号線に喫煙ボックスを設けるという考えがあるようですが、品川区では、喫煙者やたばこを吸わない人に対して、どのように進めていくのか、対策について伺いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"たばこを吸う方、あるいは吸わない方に配慮した環境の整備につきましては、現在、喫煙所の移転等も含め検討しているところもありますけれども、さらに加えまして、例えばほかの自治体でやっていらっしゃるような。","voiceIndex":46,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"今後とも、よろしくお願いいたします。次に、１７３ページのオリンピック・パラリンピック開催周知事業について伺います。この事業は新事業ということでありますが、事業内容について、改めてご説明いただきたいと思います。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"今回、新しく事業推進検討経費ということでお願いしております、こちらの５００万円の内容ですが、２０２０年東京大会開催にあたりましては、区としても大きな可能性を秘めていると感じているところです。","voiceIndex":48,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"続きまして、ホッケーフェスタについてですが、現時点において、いつごろ執り行われる予定でしょうか。競技観戦ツアー等についてですが、これはどのような競技を観戦するものでしょうか。毎年違うのか、あわせて伺いたいと思います。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"競技観戦ツアーですが、こちらは５種目を考えておりまして、昨年も５種目実施したところありますが、昨年はホッケー、バドミントン、ビーチバレー、サッカー、バレーボールを開催いたしました。","voiceIndex":50,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"この競技観戦ツアーの対象者は、区内の小中学生ということでありますけれども、地域を盛り上げるためにも、今後、対象者を増やしていく方向性はあるのか。そして、参加者からの感想等がありましたら、あわせて伺いたいと思います。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"感想ですが、昨年実施いたしました５種目全てでアンケート調査を実施いたしましたが、ほぼ１００％に近い参加者に、大変よかったというところに丸をしていただいてあります。理由といたしましては、やはり間近で見れたことが大変よかったという内容でございました。","voiceIndex":52,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"今後とも、周知・報告等をよろしくお願いいたします。最後に、１８５ページの徒歩帰宅者支援経費について伺います。ターミナル駅周辺防災エリア計画基礎調査委託についてですが、この調査はどのようにして行ったのか、その調査方法について伺いたいと思います。品川区においては、説明の中で４駅あると伺っておりますが、今後、その４駅以外が対象になるのかどうかということを、あわせて伺います。","respondent":"鈴木防災課長","answer":"徒歩帰宅者支援関係のお尋ねですが、まず１点目の調査方法はどのようなものかですが、これは平成２７年度予算で、今回議決されれば委託をして、これから調査を始めるということで、詳細については、これから受託者と検討する段階です。","voiceIndex":54,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"徒歩帰宅者備蓄物資についてですけれども、この保管場所について、伺います。区のほうからは、既に目黒駅に備蓄されているというお話をお伺いしておりますが、その他のターミナル駅にも置かれていく予定はあるのでしょうか。先ほども質問がありましたが、どのくらいの備蓄量でしょうか、よろしくお願いいたします。","respondent":"鈴木防災課長","answer":"それからあと、近隣の災害時協力協定で備蓄場所を提供いただける事業者の施設にも、区で用意した物資を置かせていただいているというのが現状です。ほかの駅につきましては、今後、順次、同じような協議会を立ち上げてまいりますので、その協議の中で配備をしていく予定です。","voiceIndex":56,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"１６７ページの生活安全推進事業に係わって、客引き行為等の防止条例について伺いたいと思います。この防止条例ですけれども、区民委員会で風俗営業法と迷惑防止条例があることで、区条例が必要な理由を、警察の取締りには一定時間がかかるので、毎日やることは現実的には無理。つまり、従来の警察の対応では徹底できない部分を、区と区民が補うという条例なのか、ここを伺いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"これは他区の例でも同じように、不十分なことが多々ありますので、区が主導的に動きまして、区民の支援、あるいは、警察等の支援もいただきまして、まち全体でこういった迷惑な客引きを防止していこうという趣旨で、条例のご提案をさせていただいたものであります。","voiceIndex":59,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"従来の警察の対応ではなかなか徹底できない部分を、区条例で、区民とともに対応すると。私は、風俗店の客引き行為や客待ち行為、またアダルトビデオの出演依頼など、こうした迷惑な行為は絶対にやめてほしいと強く思います。アダルトビデオへの出演依頼は、どこからが区条例の違反行為なのか、ここを伺いたいと思います。そして、この違反行為に当たる当たらないの基準とは何か、区条例をご説明ください。","respondent":"上垣外生活安全担当課長","answer":"むしろ、こういった取組みにより、客引きがなくなるということに加えまして、その他の刑法犯の減少の効果が見られるので、こういった形で積極的に実施をさせていただきたいと考えております。","voiceIndex":61,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"例えば看板を掲げて静かにピンクチラシを配り、風俗店への客引き、アダルトビデオへのスカウトも、しつこくなければ違反行為にならない、これが区条例の基準なのか伺いたいと思います。私は、しつこくなくても、ピンクチラシの配布や風俗店へのお誘いやアダルトビデオへの出演依頼は迷惑だし、まちの魅力を失う行為はやめてほしいし、全部なくしたいと思いますけれども、いかがでしょうか。","respondent":"上垣外生活安全担当課長","answer":"区として取り組むべき対象として、執拗な客引き行為、スカウト行為を対象にしていこうと。それから漏れる違反行為については、もちろん法律、あるいは都の迷惑防止条例に従いまして、本来的に警察が取り締まっていくべきものと考えております。","voiceIndex":63,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"他の自治体の条例を見ますと、執拗な行為という程度の問題ではなく、業種や業態を指定しています。例えば新宿区では、風適法に規定する営業の客引きは、行為が対象です。墨田区では、ピンクチラシの配布行為が対象です。なぜすき間があるのか、迷惑な業種やその行為をなぜ指定しないのか、ここは改めて伺いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"ただ、罰則がないのです。しかし、品川区におきましては、罰則付きの規定でありますので、規制範囲を絞って、店の許される営業の自由の範囲と、それによって迷惑を受ける区民の方、これのぎりぎりの調整を図って、こういった要件をつけているわけです。","voiceIndex":65,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれの役割があると、私は思うのです。役割分担について、伺いたいと思います。罰則をつけるのであれば、どの行為が違反なのか、明確な、客観的な基準が罰則には必要だと思いますけれども、対象が不明確だったり、規則や運用で決めたり、そういう罰則条例で防ぐことになるのか、ここも伺いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"罰則が不明だということですけれども、この規定の仕方につきましては、現在、東京都の迷惑防止条例が規定しておりますように、執拗な客引き、あるいは執拗なスカウト行為につきましては、都の条例が既に定めている規定でありますので。","voiceIndex":67,"id":"exchange-031"},{"speaker":"中塚委員","kind":"意見","question":"法律や都条例が足りない部分を補うと言いながら、法律や都条例で対応しているというのが、よくわかりません。逆に、健全な経済活動や市民活動もこの条例の対象だという問題です。いわゆる迷惑行為であれば、既に都条例や法律の範囲内で対応可能なもので、区全域に対象を広げ、罰則は特定地域ですけれども、健全な経済活動や市民活動まで対象とする、その理由がわからないので、ご説明ください。","respondent":"上垣外生活安全担当課長","answer":"ただし、この条例で規定しておりますように、執拗な形態については、営業内容を問わず迷惑をかける、あるいは不安、不快感を覚えさせる行為だと考えております。それで、こういった要件を加えた次第であります。","voiceIndex":69,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"条例上は、区内全域で、風俗店も一般の八百屋も同じ対象のテーブルに乗せ、また、勧誘はアダルトビデオへの出演依頼も、バイトや労働組合の勧誘も同じ対象のテーブルに乗せ、違反の基準がしつこいかどうか、罰則は特定地区ですけれども、対象は全分野と、こういう防止すべき問題の深刻な実態が区内にあるのか、健全な経済活動や市民活動まであらかじめ全て対象にする区の条例が、なぜ必要なのか。","respondent":"上垣外生活安全担当課長","answer":"幸い、しつこい形態はないようでありますけれども、仮にこういった方たちがしつこくつきまとって客引きをするということがあれば、それは当然規制の対象にすべきものと考えております。","voiceIndex":71,"id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"サッカークラブや野球チームが子どもたち同士一緒にやろうと勧誘をする、お店が特売で勢いよくアピールする、こうした行為もあらかじめ全て対象とするというのがなぜなのか、よくわかりません。そのうえで、なぜ区が、二重、三重に対象にするのか、この点は正すべきだと思います。民主主義の問題でもありますので、この条例は一度取り下げて、私はしっかりとよく吟味すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問・要望","question":"国際交流推進事業なのですけれども、厳しい財政の中、この事業は、私はだんだん小さくなっていくのかと思いましたら、平成２６年度に比べて増額されているのですけれども、方向転換になってきたのでしょうか。その辺も含めて答弁をお願いします。それから、１７３ページ、オリンピック・パラリンピック開催周知事業で、特にホッケーなのですけれども。","respondent":"江部総務課長、河内協働・国際担当課長、上垣外生活安全担当課長、小川オリンピック・パラリンピック推進担当課長、鈴木防災課長","answer":"今年も、おかげさまで各区、地域団体、外国大使、領事館、それから民間企業の皆様方、大勢ご参加いただきまして。国際関係の基本的な考え方ですが、２０２０年のオリンピック・パラリンピックを間近に控えまして、今まで積み重ねてまいりました友好都市。職場を仮に離れたといたしましても、この条例、あるいは五反田のまちにつきましては、重大な関心を持って。一生に一度あるかないかですので、ホッケーというものを、本番の大会までに認知度を高め、本番のときには。","voiceIndex":75,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"今度、具体的な課題になるのですけれども、きゅりあんという場所を借りまして、受付で注意されるいろいろな項目の中において、外には出ないようにしてほしいと。しかし、あれだけの人数です、区長を先頭にやっていきましょうという新年の初めですから、もう最初から、あそこに飲食物が置いてある、私は、その辺について課題だと考えています。その三つの課題について答弁してください。","respondent":"江部総務課長","answer":"委員からは、昨年１１月の決算特別委員会でもご質問をいただきまして、時期的に、今年度は見直しといいますか、改善には着手できなかったところではありますけれども、廊下にテーブルが出ていたということにつきましては、ちょっと時間をいただきながら、例えば。","voiceIndex":81,"id":"exchange-036"},{"speaker":"横山委員","kind":"確認","question":"私は、１５９ページのシティプロモーション推進経費、１８３ページの災害時応急物資確保費の確認をします。はシティプロモーション推進経費について、お伺いいたします。最初に、品川区シティプロモーション戦略プランの骨子案について、現段階における状況を、四つの点に整理して、お伺いいたします。第１に、シティプロモーションの背景と課題について、品川区の特徴を踏まえて教えてください。","respondent":"荒井広報広聴課長","answer":"手法についてですが、品川区はこれまでもいろいろな形でＰＲ、発信をしてきたところですが、特に区外の方たちに向けてのＰＲ発信をどういうふうにしていくか、媒体について、さらに検討を深めていきたいと考えているところです。","voiceIndex":84,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"まちの魅力は、時代の流れや人々の価値観によって変化していく部分もあります。現在の魅力を発信して磨き続けると同時に、オリンピック・パラリンピックの後の人口減少社会において、品川区が活力あるまちであり続けるために、積極的な仕かけと、その仕組みや体制についても内容を検討していただき、戦略プランを進めていただきたいと強く要望いたしますが、お考えをお聞かせください。","respondent":"荒井広報広聴課長","answer":"世論調査でも、住み続けたいと思われている方が９割以上いる中で、今ある資源と、さらに新しい資源がどんなものであるかということにつきましては、委員ご指摘のあるような関係団体、あるいは新しく入ってくるＮＰＯであるとか、団体の方々、新しい風の声を聞きながら、仕組み。","voiceIndex":86,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"平成２６年度内に特設ホームページを制作予定ということで、概要のほうに書いてあったのですけれども、その内容を詳しく教えてください。イベント等でＰＲ活動を行うとありますが、参加予定のイベントの実施場所、区内なのか、区外なのかというところと、周知パンフレットの内容、またパンフレット配布のほかにどのようなＰＲ活動を、平成２７年度は予定していらっしゃいますでしょうか。","respondent":"荒井広報広聴課長","answer":"２点目はＰＲ活動についてのお尋ねです。イベント、パンフレット等については、まだこれから平成２７年度に具体的にどうやっていくかというのを検討していく予定です。ホームページの内容ですが、平成２６年度末にホームページを作成する予定です。","voiceIndex":88,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"課題として、避難所連絡会議の促進、必要支援物資の情報収集、安全な避難所生活環境の確保、対策の方向性として、避難所運営での意見の取り入れ、備蓄品の確保、物資の調達、更衣室・授乳室・物干し場などの部屋等の確保の記載がありますが、女性の防災リーダー養成や女性の視点での備蓄品の確保、そして物資の調達、トイレ・更衣室・授乳室・物干し場などの部屋等の確保について。","respondent":"鈴木防災課長","answer":"地域の方からいろいろいただく意見、また区議会からいただく意見、そういうものも参考にしながら、具体的には、物品を購入するだけではなくて、その配給に関してもやはり女性に対応できるような女性の配置だとか。","voiceIndex":90,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"被災者は不安を抱えられている中で、例えば生理用品をいただきたいというようなことを、女性のリーダーの方がいらっしゃれば、心細くなくというか、不安なくいただいたりできると思うのですけれども、配給の方法ですとか、リーダーの配置について、もう少しお聞かせください。","respondent":"鈴木防災課長","answer":"具体的なところは、女性のリーダーは実際のアドバイザー研修等の養成でも入ってきていただいておりますし、現実の場所で、皆様でお話し合いをして役割分担をしていただくということで考えております。","voiceIndex":92,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは多分、真空をつくるために必要なことだと思うのですけれども、旧型のタイプだとそういうふうになると伺っていますが、指導をしてくださる消防団の方から、これはちょっと環境に優しくないので、できるだけ早く新しいものに替えたらどうかという、こんなご意見をちょうだいしておりますが、この点、定期的な交換について、どういうふうにお考えなのか。","respondent":"工藤選挙管理委員会事務局長、加藤防災安全担当課長","answer":"私どもといたしましては、事務の手順書の中で、必ず入場整理券を確認すると、そういった中でご案内をするという形になってありますので、そういった部分の事務マニュアルの徹底、また従事者につきましても、私ども。一つのポンプを大体２０年くらいをめどに交換しながら、大体年間１３台くらいを交換していこうと考えています。","voiceIndex":95,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"提案","question":"シティプロモーションにいかせていただきます。その中で、この前、職員報の「ふれあい」のほうに、写真入りで９名の若手職員が政策課題研修を重ねて、インタビュー、ディスカッション、１１団体の他自治体やＮＰＯの視察を行い、１４の事業を提案、発表されたと。その提案事業として、シティプロモーションの認定事業と、交通広告ＰＲ、検索扇動型広告といったものをご提案されたとあります。","respondent":"荒井広報広聴課長","answer":"交通広告ＰＲについてですが、先ほどもありましたが、今後どういった形でＰＲ、周知に努めていくか、新しい媒体の一つとして交通広告ＰＲというものを検討の一つにさせていただいているところです。","voiceIndex":98,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"提案","question":"ここに書いてある２,０１８万円、そのうち１,５００万円は、多分平成２６年度と同じく、広告事業者である電通にお願いする、そして残りの５００万円で、先ほどの二つの事業を取り上げていくということだと思うのですけれども、１４の提案をされていて、そのうちの二つをやると、多分、そういうことだと思います。失敗を恐れれば、やはり総花的な眠たいものになってしまうのです。","respondent":"荒井広報広聴課長","answer":"シティプロモーションに対する再度のお尋ねです。委員おっしゃるように、確かに自治体間競争の中で、それぞれの自治体がどうやって定住人口を獲得していくかというのは、最終的に自治体の目的であると考えているところです。","voiceIndex":100,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"提案","question":"それに関連してですが、第２１回品川区世論調査で、シティプロモーションについてという調査を行われています。そういうことこそ、ぜひ広告代理店から提案をしていただきたいと思います。せっかく委託してやっているわけですから、その点、こういう提案がなかったのか、また今後そういう提案を求めていただけるのか、商業・観光課ではなくて、広報広聴の観点から教えていただきたいと思います。","respondent":"荒井広報広聴課長","answer":"これにつきましては、従来からもお答えしてきたとおり、なかなか人的、経済的に難しいところもあるように考えているところです。ただ、品川区をよりマスコミに乗せていくといいますか、全国ネットに乗せていくという点では、一つの有効な手段であるかと考えているところです。","voiceIndex":102,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一つの案として考えていただければと思います。こんなことを、行政の職員が名刺に書いて大丈夫なのですかと言ったら、その方は不敵に笑っていました。そういうのを見たときに、これはもう本当に、今始められたということは評価しますけれども、真剣にやっているとは思うのですけれども、ぜひ真剣に捉えていただいて、これをどんどん進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"今、どのくらいの掲示板があるのか、わかれば教えていただきたいと思います。それから、１６３ページの区有施設。今後、８月頃にはあそこが閉まって、ベニヤで囲うということは伺ってはいるのですが、その前に、まだまだ夜暗い中、また夕方暗い中、子どもたちが遊んだりする際に心配だというお声をいただいていたので、その辺をどのように考えているのか、まず教えてください。","respondent":"久保田地域活動課長、柏原行財政改革担当課長","answer":"掲示板の一般的な寿命ですけれども、今回、ふれあい掲示板を建て直すにあたりまして、業者のほうに確認しましたところ、耐用年数は２０年程度であると言ってありますので。本日もお話しいただきましたので、改めて国のほうには話していきたいと思ってあります。","voiceIndex":107,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問","question":"掲示板で言えば、２０年ということで、２,３６７基、毎年３６０万円が計上されていくと思うのですが、１町会当たり大体何年で利用しているとか、建替えの計画は持っているのかどうか。そろそろ建替えなので、相談がきているとか、その辺の相談の現状を教えていただければと思います。掲示板のほうだけ、お願いします。","respondent":"久保田地域活動課長","answer":"そういった形で、各町会では、非常に掲示板というものに対して重きを置いて、情報発信の重要性を認識しているものだと、私どもは考えているところです。","voiceIndex":110,"id":"exchange-048"},{"speaker":"大倉委員","kind":"確認","question":"目に見えてきれいなものとか、まさに本当にそのとおりだと思います。次に移ります。防災訓練なのですが、地震体験車に私も去年乗せていただきましたが、地震体験車の稼動率はどうなっているでしょうか。それから、障害者が、例えば車椅子の方がちょっと利用したいといったときに、安全性の観点から体験できませんという声があったということを伺ったので、その辺の確認をさせてください。","respondent":"鈴木防災課長","answer":"１点目の地震体験車の稼動率です。分母を何にするかというところがあるのですが、大体週に３日から４日くらいは出動しております。それから２点目の車椅子の方が地震体験車を体験できないです。","voiceIndex":112,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"週３回とは、かなり稼動しているというところで、ぜひこういう災害を身近に感じられるような地震体験車を活用していただければと思います。そのときには、よく議会でも、中学生、高校生、また地域の企業の方々、そういったところとの連携とかというお話がありますが、平日にそういった訓練が可能なのかどうか、また今後の可能性というか、考え方を教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"１点目の、車椅子の方、障害がある方の地震体験車の利用ですが、委員ご指摘のように、例えば介添えをしたり、専用の要員を増員することで、対応の可能性はあるかと思いますが、安全のことに関しますので、少し検討させていただきたいと思います。","voiceIndex":114,"id":"exchange-050"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に広報経費ですが、今、ツイッターで品川区はいろいろ発信をされている中で、先ほど少し見させていただきましたが、６,０００人を超えるフォロワー数だったのですが、例えば、フェイスブックとかの活用というのは、どのように考えているのでしょうか。ターゲットに合わせたフェイスブックのメニューをつくってやっているのですが、そういったところの考えとか、可能性を教えていただければと思います。","respondent":"荒井広報広聴課長","answer":"フェイスブックについてのお尋ねです。これにつきましては、検討を進めてきたところですが、今後、シティプロモーションの事業を進めていく中で、何らかの形で実現ができないかということで検討を進めているところです。","voiceIndex":116,"id":"exchange-051"},{"speaker":"大倉委員","kind":"質問","question":"安価にできる、コミュニケーションがとれる、拡散性が強い、情報がとれるとか、さまざまあると思うので、ぜひ活用していただければと思って質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"私は、１６３ページ、２款１項６目の企画調整費、町会・自治会のあり方と区との協働に関する調査研究、１５１ページ、２款１項人権啓発費のＤＶ相談について、それからページを示すことはできませんけれども、事業部経営会議の情報公開について、３点お伺いいたします。これは経営会議の会議記録を全て保存しなければならないということだと思いますけれども、区の認識をお伺いいたします。","respondent":"柏原行財政改革担当課長","answer":"基本的には、つくるということで考えてありますが、事案によって、要旨をつくらない場合もあるものです。","voiceIndex":120,"id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"今お答えいただいたように、情報公開請求を３年分しましたけれども、付議議案のうち、指示決定、つまり執行部に対して報告を求める会議の記録しかありませんでした。それとも、区だけで使っていけばいいものと思っているのか。執行部が結果を求めるだけの使い勝手ということであれば、この規則には沿っていないのではないかと考えますが、いかがですか。","respondent":"柏原行財政改革担当課長","answer":"事業経営会議ですが、設置の目的そのものが、区政運営の最高方針および重要施策の基本方針の審議、それから総合調整等々、会議を置くという目的があります。","voiceIndex":122,"id":"exchange-054"},{"speaker":"井上委員","kind":"提案","question":"私は、毎年１１月くらいに行われる予算要求にあたっての事業部の提案説明というところで、予算編成がどのような経過をたどって、こういった委員会の中で審議されているのかという、そこのプロセスは、行政だけがわかっていればいいことではなくて、そのことによって、どういうまちづくりを進められるか、長期基本計画があり、実施計画があるというふうによくおっしゃいますけれども、そこのところは。","respondent":"柏原行財政改革担当課長","answer":"今、予算の１１月の部分の例示をいただきましたけれども、予算を作成するにあたって、各事業部のほうから、こういった形で進めていきたいという提案をいただいて、協議をするといった趣旨で行っているものです。","voiceIndex":124,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問・要望","question":"情報公開については、限りなく進めていただくことを要望して、次の質問にいきます。それから、シェルターについては、すごく運営が非常に困難になっているということが、新聞報道でも、民間のシェルターは大変な思いをされているということだったのですけれども、品川区が確保しているシェルターについては、今後の課題はないのか、お伺いしたいと思います。","respondent":"提坂人権啓発課長","answer":"緊急避難件数ですけれども、平成２６年度につきましては、１月末現在までで１０件。そのうち子どもがいる方が４件となっております。","voiceIndex":126,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問・要望","question":"それからもう一つ、これはあくまでも本当に私見なので、今の人権啓発課長に対してということではないので、誤解のないようにお願いしたいのですが、ＤＶ支援や男女共同参画のリーダー的組織のところでは、私はかねてから女性の管理職のほうが有効であると考えていたのですけれども、やはりほとんどのＤＶ被害者が女性であることとか、男女共同参画の視点においても、そういったことを区はお考えではないのか。","respondent":"提坂人権啓発課長、堀越人事課長","answer":"ＤＶの相談支援については、具体的なスタート時期はまだ決まっておりませんけれども、今後、前向きに研究してまいりたいと考えております。担当課長が男性か女性かというお話ですが、担当課長はしっかりと仕事を進めていくというのが、まず第一でございまして、そのほか、いろいろな関係機関、それから庁内の他課との連携等を図りながら、全体的に進めてあります。","voiceIndex":128,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"時間のない中で申し訳ないのですけれども、町会・自治会のあり方の来年度に向けてのところですが、今、町会の参加のほうに係わっている人たちの委員会ですので、参加しにくい、できないという人たちの声をどのようにここに反映されていくのか、ぜひそこは進めなければいけないと思っているのですが、お伺いしたいと思います。","respondent":"柏原行財政改革担当課長","answer":"次年度もこの会議を進めていきますので、いろいろな方のご意見を伺っていきたいと思ってあります。","voiceIndex":131,"id":"exchange-058"},{"speaker":"沢田委員","kind":"提案","question":"今、私の手元に文部科学省のＱ＆Ａがあるのですが、そこを読ませていただきます。大綱には、首長の権限に関わる事項についてのみ記載されるのですか」というＱ５のところで、回答では、「総合教育会議では、予算や条例提案等に加え、保育や福祉等の首長の権限に関わる事項等について、協議し調整を行うほか、教育委員会のみの権限に属する事項についても協議を行うことが想定されています。","respondent":"江部総務課長","answer":"私どもも、国の考え方に沿いまして、教育委員会が適切と判断した場合、首長が大綱に記載することも考えられるですので、これも含めまして、来年度から始まります総合教育会議の中で協議してまいります。","voiceIndex":134,"id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"私としては、事実誤認があったということでいいのですけれども、区は主体的に教育行政を進めていくということで、大綱に教科書採択の方針を盛り込むべきだと、私は思っておりますけれども、区として今後この総合教育会議の中で大綱に盛り込む盛り込まないを含めて判断されていくということでよろしいのか、改めて教えてください。","respondent":"江部総務課長","answer":"繰り返しになりますけれども、教科書の採択そのものと教科書採択の方針というのは、明らかに違うものでございまして、私どもが先ほどから申し上げておりますのは、教科書採択の方針についてのことですので、これにつきましては、教育委員会の判断を踏まえまして。","voiceIndex":136,"id":"exchange-060"},{"speaker":"沢田委員","kind":"質問・要望","question":"オープンデータのことで聞かせていただきたいのですけれども、オープンデータ推進経費ということで、私は、平成２６年第１回定例会でも質問させていただきました。先ほど、つる委員からも質問がありましたとおり、これからホームページでも、いろいろ順次公開されていくということで書かれておりましたけれども、ぜひとも積極的に今後さらに新しい情報を載せていっていただきたいと思います。","respondent":"秋山情報システム課長","answer":"ただ、民間の方から、オープンデータとして用いたいこういうデータがあるのだけれども、ということに関しましては、こちらのほうとしても柔軟に対応していきたいと考えています。","voiceIndex":138,"id":"exchange-061"},{"speaker":"沢田委員","kind":"提案","question":"広報の仕方という点で、公開しましたということでホームページにも出ていますけれども、例えばそういったことを利用するＩＴ関係の企業などに対して積極的に、どうぞこういうものを使ってみませんかという提案等、その辺のあたりはどのようにお考えなのか、お聞かせください。","respondent":"秋山情報システム課長","answer":"将来的には、地域をあげてオープンデータを使って、何か区民の方の利便性の高いものをつくっていただくというようなことも考えられるとは思っていますけれども、現時点で、すぐにそこまでいくかというのは、なかなかちょっと時間がかかるのかと。","voiceIndex":140,"id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"いろいろと技術的にも大変なこともあるでしょうし、少し時間がかかることかもしれないですけれども、少しずつでもいいので、そういった使える情報を公開していって、官民協働、または民間でも積極的に活用していって、防災とか、子育てとか、さまざまな分野での情報提供を積極的に行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-063"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１４７ページの番号制度対応経費、それから、１５３ページの庁舎等維持管理費について、お伺いしたいと思います。それから、法的にもし可能ということであれば、どのような業務が、業務の簡素化とか、住民票なしで業務が可能となると想定できるのかということも、お伺いしたいと思います。","respondent":"秋山情報システム課長、井浦戸籍住民課長","answer":"ただ、これは平成２９年７月以降、情報連携のネットワークが整備された後にできるということですので、今の現状から申しますと、法的に可能であり、平成２９年７月以降はそういう対応ができるという形になってあります。ただし、平成２９年以降は、各省庁間、行政機関内での情報連携という形で簡略化が推進されてくると考えています。","voiceIndex":144,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"平成２９年７月以降は、そういったことも可能となるとお伺いしましたので、まだ先の話ではありますけれども、区民の業務簡素化か、行政改革といいますか、そういう部分で着実に進めていただければと思いますので、よろしくお願いしたいと思います。品川区として、いわゆる水道料金のコスト削減というような観点で、地下水の活用をどのように評価をするか、お考えをお伺いしたいと思います。","respondent":"立川経理課長","answer":"水道料と地下水ということのご質問です。実は庁舎におきましては、雨水等をトイレ等の排水に利用しています。地下水の利用については、まだ検討している状況ではございませんけれども、今後、利用について検討を図っていく必要があるかという認識でいるところです。","voiceIndex":147,"id":"exchange-065"},{"speaker":"塚本委員","kind":"質問・要望","question":"最初にちょっと聞き忘れたのですけれども、水道料金は年間、ここでは電気とガスと水道料ということで１億３,４７４万円強の金額が出ているのですけれども、これが一体、水道料金としてどのくらいなのかということと、もしわかればですけれども、例えば世田谷区のように１日１０ｔの水が飲料水として活用できるとすれば、水道料金がどの程度賄われるのかというようなことが。","respondent":"立川経理課長","answer":"電気・ガス・水道料のうち、水道料金はどれくらいかですけれども、１億３,４７４万円強のうち、水道料金につきましては、１,９００万円ほど見込んでいるところです。ちなみに、水道の利用の推移につきましては、ここ数年、減少傾向にあるです。","voiceIndex":149,"id":"exchange-066"},{"speaker":"塚本委員","kind":"意見","question":"今、私もすぐに暗算できませんけれども、もちろん地下水を汲み上げてろ過をすると、設備の投資もありますので、それがどの程度ペイするのかというのは、またよく研究しなければいけないのですけれども、もう一つ、地下水を汲み上げて飲料水化することにつきましては、世田谷区では、災害時はある程度規制を取っ払う形で、５万人分になるらしいですけれども、１日１５０ｔの飲料水を確保することができる。","respondent":"鈴木防災課長","answer":"災害時の水につきましては、都の給水所、それからペットボトルによる備蓄等で、必要量については確保できておりますので、その中で、本部のものも賄えると考えております。","voiceIndex":151,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１８１ページの初期消火体制強化費について、お聞かせいただきたいと思います。その対策に責任を持って取り組むということで、その姿勢を求めたいと思います。それが１点です。それからもう一つは、全都の消防署別の延焼危険度ランクというのが、ホームページに公開されていまして、総合評価で、荏原消防署が６ということで、最も全都の中で危険度が高い消防署の一つになっているのです。","respondent":"鈴木防災課長、加藤防災安全担当課長","answer":"２点目の、延焼の危険度ランクで、荏原消防署が高いランクにあるということで、何カ所まで消防が対応できるかですが、申し訳ありません、すぐに手元に各署の台数の情報がございませんので。ただ、今も防災課長から答弁ございましたとおり、この６台で回すというよりも、その災害に応じて東京消防庁管内の部隊を集結して対応するというような状況ですので、その災害に応じて対応していくです。","voiceIndex":154,"id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自分の地元でも、近所で火災があったときに、街頭消火器をみんなが持ち寄って初期消火をして、食い止めたという経験があるのですけれども、そういうところからしても、町会ではぜひこの街頭消火器を増配備してほしいという強い要望があります。しかも、１年間に３００万円から５００万円くらいの予算ですので、さらにこれを拡大していただきたいというのが１点です。","respondent":"鈴木防災課長","answer":"ちなみに、今年度中に危険度ランク５の町会については全て配備が終わりまして、平成２７年度からはランク４の町会の増配備が始まる予定で進めているところです。","voiceIndex":157,"id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は前にも要望したのですけれども、消防水利マップというのが東中延一、二丁目、中延二、三丁目では、とてもいいものをつくっていただいたのですけれども、こういうものを町会ごとにぜひつくっていただいて、町会に配備していただきたいと思うのですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"増設の拡大に関しましては、危険度ランクだけではなくて、不燃領域率や一本当たりの消火器がカバーする範囲を勘案して決めているものですので、計画を変更する予定は、現在はございません。水利については消防のほうで、一定程度充足をしているという認識です。","voiceIndex":159,"id":"exchange-070"},{"speaker":"渡部委員","kind":"質問・要望","question":"１７１ページの地域スポーツ等推進経費と、２００ページ、基幹統計費は国勢調査について伺います。この間２年くらいだったでしょうか、さまざまな話し合いを続けてこられて、いよいよやっと苦難の道を乗り越えられて立ち上がるということで、大変行政の方々にはご苦労があったと思いますが、ここで何点か聞きたいと思います。その２点をお願いします。","respondent":"安藤文化スポーツ振興課長","answer":"これは二つ目ということで、荏原Ｂ地区でただいまやっています。平成２４年１０月から会議を持ち、皆様と始めまして、毎月１回、計２８回行いました。やっとここへきて、地域の皆様のご協力もいただきまして、設立総会を迎えるわけです。","voiceIndex":162,"id":"exchange-071"},{"speaker":"渡部委員","kind":"意見","question":"よろしくお願いします。何かの機会に周知いただければと思います。そして、設立総会において、さまざまな議決がされますけれども、活動拠点が多分スクエア荏原になってくるのかという中で、今回、荏原、荏原西、小山、そして旗の台が一つに、役員が出会って運営母体ができてくると思うのですけれども、そのような方々が活動するための拠点としての部屋も必要かと思うのですが、その辺は何かお考えありますか。","respondent":"安藤文化スポーツ振興課長","answer":"今後も、スクエア荏原のアリーナで、地域の方々にフリー利用をぜひしていただくためにも、スクエア荏原の指導員室と申しましょうか、スタッフルームというものがあります。そこで企画をしていただいて、新たな事業を展開していただきたいと考えています。","voiceIndex":164,"id":"exchange-072"},{"speaker":"渡部委員","kind":"質問・要望","question":"国勢調査のほうは、もう毎回といいましょうか、５年前にも伺ったりしまして、確認したいのは２点です。調査員２,８７０人で対象２０万８,０００世帯という、今回予算書のほうに出されているうち、実際に町会のほうで担当されるのは何名といいますか、ブロックにして幾つ、何世帯くらいで、区が直接どちらかに頼むのがどれくらいあるかという比率を教えていただきたい。","respondent":"久保田地域活動課長","answer":"それで、インターネット回答のなかった世帯に対しては、紙の調査票を配って回答いただくと。ただ、回答にあたりましては、基本は郵送ですので、できるだけ調査員の負担を減らしていきたいと考えています。","voiceIndex":166,"id":"exchange-073"},{"speaker":"向委員","kind":"質問","question":"１８３ページ、災害時応急物資確保費、それから１５１ページ、英語少し通じます商店街に関して、交流事業経費の中に入っていると思うのですが、お尋ねします。少しお尋ねしたいのが、女性が被災のとき避難所などで主に使うであろうと想定して備蓄している品物があると思うのですけれども、具体的に名称とか教えてほしいと思います。英語少し通じますの看板を来年度予算に計上されています。","respondent":"鈴木防災課長、河内協働・国際担当課長","answer":"男性も使う場合もありますが、トイレのときに女性のブースを離れた場所に設置するとか、そういうさまざまな視点で女性に対する対策を折り込んでいるところです。そのような中で、外国人の方がこの店に入ってみたいというようなところで、もしよい案がありましたら、さらに改良を加えながら事業を進めてまいりたいというふうに考えている次第です。","voiceIndex":170,"id":"exchange-074"},{"speaker":"向委員","kind":"提案","question":"こういうきっかけということで、予算計上されて、看板をつくられているのはすごくいいと思うのですけれども、一つ提案なのですが、例えば、段階別に初心者的な色分けをして、グリーンとか、もう少しレベルが上るとかシルバーとか、一番ぺらぺら話せるようになるとゴールドとか、そういった色分けというのも、お互いの競争心をあおるわけではないのですけれども、学ぶ楽しみというか、そういうところも。","respondent":"鈴木防災課長、河内協働・国際担当課長","answer":"これはやはり、保管場所であったり、予算の制約もあるところもありまして、そういうふうにしてありますが、４日目以降、つまりご指摘のあったような避難所生活が始まってからは。そんなところを、限られた英語の中でしっかり伝えるようにということでスタートした事業です。段階的にはなかなか難しいことはあろうかと思いますけれども、アイデアとして研究させていただきたいと思います。","voiceIndex":173,"id":"exchange-075"},{"speaker":"向委員","kind":"意見","question":"備蓄のほうですけれども、予算の制限とかいろいろありますけれども、発災時から３日間とか、そういう考えもあって、やはり女性の視点、リーダーシップとか取れることで、事前準備も必要だと思いますし、震災を考えて、日頃から使い慣れておくとか、そういったところも、女性の視点はどんどん入れてほしいので、今後も引き続きよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-076"},{"speaker":"こんの委員","kind":"質問","question":"私からは、１８３ページの災害時応急物資確保費のしながわ中央公園防災備蓄倉庫整備と分散備蓄計画策定委託、もう一つが１９７ページの投票事務費に関連してお聞きしたいと思います。それから、分散備蓄計画策定ということですが、この計画のいわゆる目的がどのようになっていくのか、というところをお聞きしたい。","respondent":"鈴木防災課長、工藤選挙管理委員会事務局長","answer":"適正・迅速な対応のための計画というふうに考えているものです。新たな取組みというところで、最近ですけれども、小学校と連携して出前選挙ということで、今年の１月に延山小学校とタイアップして、そのような取組みもさせていただいているところです。","voiceIndex":178,"id":"exchange-077"},{"speaker":"こんの委員","kind":"質問・要望","question":"防災備蓄倉庫のほうですけれども、わかりました。そうすると、より一層バランスよく配置をして、いざとなったときには、そこから救援物資をということですか。それを災害時に持ち出そうと思ったときに、実は重たくて全部持てないという声を伺います。それから、投票のことなのですけれども、投票率アップは、いわゆる啓発活動だけなのでしょうか。こうした動きを、品川区はどのように見ているのでしょうか。","respondent":"鈴木防災課長、工藤選挙管理委員会事務局長","answer":"１点目の在宅避難、もしくは避難する場合の備蓄の持ち出しや用意する品目ですが、まず、基本的に全体的な考え方としましては、もちろん区のほうでは最低限必要な食料や水、毛布等は３日分備蓄をしております。ご提案の趣旨を見て研究という形にしておりますが、投票所を増やすには、突然の選挙のときに対応できるのかどうかという部分、それから専用回線を通した名簿対照等で個人情報が使われるという部分、そのようなところもありますし。","voiceIndex":181,"id":"exchange-078"},{"speaker":"こんの委員","kind":"提案","question":"備蓄品のほうは、基本的な確認をさせていただきました。投票所には行けなくても、バスで来られるデイサービス、いわゆる誰が来るというのは明確にわかるので、デイサービスの先で投票ができるようになると、高齢者で行きたくても行かれない方のための投票率の向上、これはいかがでしょうかという声がありますので、お届けをいたしますので、今後こういったところも考えていただければと、要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":184,"id":"exchange-079"},{"speaker":"渡辺委員","kind":"確認","question":"私は、１５５ページ、水と緑の市町村との交流事業を伺います。事務事業概要等を見ていまして、確認を含めて伺います。平成２５年度を基準に聞きます。もう一つ言うと、ふれあい協働農園の参加者も全１０回で参加者数が１１２人と、そういう意味では、重複がない人数はどの程度なのかということを、まず伺いたいと思います。では、まず山北町のところで伺います。","respondent":"久保田地域活動課長","answer":"実数というのでしょうか、同じ方が何回も行っているということは当然ありまして、例えば貸し農園につきましては、平成２５年度で１８１区画あるうち、１５０区画を品川区のほうで使っていまして、一人で４区画まで使えますので、大体。","voiceIndex":186,"id":"exchange-080"},{"speaker":"渡辺委員","kind":"質問","question":"おそらくそういうことだろうという中で、今、山北町のことを伺いました。早川町に関しても、マウントしながわ活用事業は全４回行って、参加者が８３人と、単純に４回ですから、１回当たりの数字が出てくるかと思います。この交流事業や貸し農園にしても、根強くファンがいらっしゃる。そういう意味で、この二つの町との交流事業の課題をどう捉えられているのか、主な課題と思われるものを教えてください。","respondent":"久保田地域活動課長","answer":"区民ニーズ等も変化してきている中でありますので、今後も引き続き、そういった利用負担の軽減だけではなく、ひだまりの里について、多くの方にご利用いただけるようなあり方検討を進めていこうということで、山北町と確認をしています。","voiceIndex":188,"id":"exchange-081"},{"speaker":"渡辺委員","kind":"確認","question":"いろいろな区主催事業のメニュー、田植えと稲刈りですかと、虫捕りと川遊び体験、ますます今、ファミリー層には、この都会で２０年前、自分たちが子どもだった頃、親となった今は、自分の子どもに体験させてあげられないということがメニューにされていて、需要はあると思うのです。この区長会のマッチングの仕組みの動向とか、方向性の確認をお願いできればと思います。","respondent":"柏原行財政改革担当課長","answer":"それぞれを運営しながら、各区がマッチングできるものを、ホームページを通じながら情報共有していくというようなところで、今、動いているのが第一弾です。そのほかにもいろいろ、プラットホームをつくっていこうとか、検討している状況です。","voiceIndex":190,"id":"exchange-082"},{"speaker":"渡辺委員","kind":"提案","question":"いち早く区長会のほうでそういう動きがあり、そして今、各市町村に要望も、アンケートだとか用紙を見せていただきました。そしてまた、昨年来の地方創生の中で、地方都市で、市町村が都内とマッチングをしたいというのは、すごく要望もあるでしょうし、品川区だったらものすごくリクエストが見込めるような気がします。否定はしません。拡大拡充の必要性が十分にあると思われますが、いかがでしょうか。","respondent":"久保田地域活動課長","answer":"私どものほうでは、水と緑の協定ということで早川町と山北町と、水と緑の交流をしていますけれども、実際には、例えば防災協定、また経済的な交流、またいろいろな形での民民同士の交流というものも多く、品川区の中で行われているということは認識しています。","voiceIndex":192,"id":"exchange-083"},{"speaker":"渡辺委員","kind":"提案","question":"議会としても、いろいろ提案できるようにやっていきたいと思います。時間がありますので、もう１点。１６３ページの国家戦略特区事業推進委託、１,０００万円の予算が計上されています。主な点をお知らせください。","respondent":"柏原行財政改革担当課長","answer":"こちらにご提案申し上げている国家戦略特区事業推進委託の予算ですけれども、区域指定を受けた中で、具体的な区としての事業であるとか、区全体としての考え方、そういったところをまとめて、具体的な事業提案を国のほうにしていけるように、それの検討経費。","voiceIndex":194,"id":"exchange-084"},{"speaker":"渡辺委員","kind":"質問","question":"経費はわかるのですが、委託となっていますが、どんな当てがあって委託をされるのか教えてください。","respondent":"柏原行財政改革担当課長","answer":"そういったところに、例えば情報の収集であるとか、実際にプランの考え方を出していただいたり、そういったところをコンサル系の業者に委託という形で進めていくことを考えてあります。","voiceIndex":196,"id":"exchange-085"},{"speaker":"渡辺委員","kind":"提案","question":"委託する中で、どんなオーダーをしていくか、品川区のこういう特徴をこう把握していて、こう活かしたい、そこにまた第三者の発想だと思うので、その辺どんなところか、要はリクエストですか、品川区を十分に把握して、地元の方との接点を多く持てる、あるいは地元でそういうところがあるのかどうかも含めて検討いただければと思いますが、お考えを聞いて終わります。","respondent":"柏原行財政改革担当課長","answer":"今、委員おっしゃっていただいたとおりでございまして、品川区としての考え方を出していくですので、これから委託に向けての準備に入るのですけれども、品川区の現在の考え方とか、品川区の地域の持っている特性であるとか、そういったところをお伝えしながら。","voiceIndex":198,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"１５１ページの男女共同参画センター運営費の中にあります、女性の活躍支援講座、これは内容は何でしょうか。今後の取組みで特徴があるものはどういうものでしょうか、という点について。次に、１５９ページのシティプロモーション推進経費、これは何人かの委員から質問がありましたが、品川区の特徴を一言で言うと何でしょうか、劣っている点は何でしょうか、お答えいただきたいと思います。","respondent":"提坂人権啓発課長、荒井広報広聴課長、柏原行財政改革担当課長","answer":"平成２４年度に設置しました虐待防止ネットワーク推進協議会との連携強化を図ってまいりたいと考えております。品川区の魅力について、一言で申し上げれば、非常にバランスのとれたまちであること、逆にプロモーションを進めていくうえでは、突出したもの。今月中に４回目を開く予定ですが、平成２６年度のまとめに今入っているところです。","voiceIndex":201,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"子育てと両立しなさいといっても、保育園がないとできませんので、保育課との連携とか、そういう話は出ていますでしょうか。区長が、どういう品川区にしていきたいか、これがやはりこのシティプロモーションの中では要になるのではないかと思うのですが、区長の想いが聞けたらいいと思うのですが、いかがでしょうか。どういう品川区を目指されているのかを、お聞きできたらと思います。","respondent":"提坂人権啓発課長、荒井広報広聴課長、柏原行財政改革担当課長","answer":"ＤＶの加害者更正プログラムについては、東京都などでやっているものもありますので、その辺の情報収集をしていきたいと考えております。さらに住んでよし、働いてよし、学んでよし、訪れてよし、といった品川区を目指していきたいと考えているところです。今、学校というご意見もございましたけれども、そういった若い世代の方々に入ってもらうのがキーであろうというような意見もありますので。","voiceIndex":205,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"一つだけ、女性が活躍するには、やはり保育園が必要です。オアシスルームではなくて、しっかりと保育対策を取りながらということを考えて、対策をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-089"},{"speaker":"あべ委員","kind":"質問","question":"私からは、１４９ページの成人式経費に関連して、人権啓発ですとか、少し飛びますけれども、住民票等の事務に関しても関連で伺います。その後、１５１ページの地域住民と外国人との交流促進、それから、１７９ページ、区民保養所経費、１９６ページ、区議会議員選挙についても、簡単にお伺いしたいと思います。品川区としては、これについて、どのようなお考えをお持ちでしょうか、教えてください。","respondent":"江部総務課長、提坂人権啓発課長","answer":"成人式についてのお尋ねですが、今年２０歳の方、約２,５５２名のうち参加された方が１,３２０名ということで、５２％でございました。きゅりあん７階、８階を使っての実施でございました。今回の渋谷区のパートナーシップ証明書については、そもそも婚姻制度というのは両性の合意に基づいて成立するものであって、少なくとも法的な婚姻としては証明できませんけれども、同性のカップルについて。","voiceIndex":211,"id":"exchange-090"},{"speaker":"あべ委員","kind":"質問・要望","question":"出席された方の中には、品川区の方ももちろんいらっしゃいましたし、毎回少しずつ会場を変えながら開いているのですけれども、ぜひ品川区で開いてもらって、そのときには、区長、あるいは教育長にぜひそこにご出席いただき、祝辞もいただけたらいいという思いを持っていらっしゃる方もおられるのですが、その辺はどのように今後対応されるでしょうか、お伺いしたいと思います。よろしくお願いします。","respondent":"江部総務課長","answer":"新たなやり方ですので、まさにこれから調査研究します。","voiceIndex":214,"id":"exchange-091"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうすると、やはりこういう事業は、最初の予算の段階から固有名詞一つだけを出して、ここのお客さまというよりも、まずはこういう事業をしたいから、区内にあるそういった宿泊施設幾つかに声をかけて、やりたいと言ったところと事業をしていくというほうが筋ではないかと思うのですけれども、いかがでしょうか。区議会議員選挙、先ほども、投票所を大学に設置してはどうかという話がありました。","respondent":"河内協働・国際担当課長、立川経理課長、工藤選挙管理委員会事務局長","answer":"理由ですが、まず１点目が、こちらにつきまして、現状で連携が取れているというところでございまして、利用者の中で主にバックパッカーと言われる。いわゆる売れる売れないというのは需給の状況ですので、そうしたことを見極めるためにも、地元の精通業者、またはリゾート関連の開発業者から情報を得て。大学構内での設置です。こちらのほうも、まず研究してまいりたいと考えております。","voiceIndex":216,"id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"提案","question":"私は、１５３ページの総務管理費、職員研修費、それから１６１ページの財政管理費の中で財務書類作成等委託と、それから契約と別々に確認したいと思います。もう１点、１６８ページの文化スポーツ振興費。これは、自民党として提案して、議員提出の条例ということで、文化芸術・スポーツのまちづくり条例、この趣旨に合って、今回新しい部ができたということは非常に期待しているところであります。","respondent":"堀越人事課長、河内協働・国際担当課長","answer":"具体的な派遣先の企業につきましては、現在、東京商工会議所品川支部と調整をさせていただいておりまして、具体的な派遣先の選定に入っているです。平成２７年度の実施に向けて、今準備に入っている状況です。先ほど答弁させていただきました、外国人の地域住民との交流促進の事業ですが、こちらは、国際友好協会が考えておりますオリンピックに向けて準備を進めていく事業として該当しております。","voiceIndex":221,"id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"研修のほうは、内容はわかりました。ただ、経営状況まで本当に入っていくのかと、少し気になったところがあります。企業側としても、その辺はある程度隠さなければいけないのではないか。いい部分はどんどん出せばいいのでしょうけれども、本当に内容まで取り組んでいけるのでしょうかと、今聞きながら、思いました。その辺で、もう１回お答えいただければと思います。","respondent":"河内協働・国際担当課長","answer":"地域の国際化に向けまして、国際友好協会といたしましても、英語少し通じます商店街などをはじめといたしまして、大使館との連携など、さまざま複合的な取組みをあわせまして、オリンピックに向けてしっかり取り組んでまいりたいと考えている次第です。","voiceIndex":224,"id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問","question":"まちの人との接触を、国際友好協会はもっと持っていいのではないかと思います。逆に言うと、先ほど派遣と言った中で、職員を国際友好協会に派遣してもいいのではないかというような感じを、今、両方の質問をしながらちょっと思ったくらいなので、その辺何かもう少し出ればと思います。","respondent":"中川原地域振興事業部長","answer":"国際友好協会ですが、協働・国際担当課長も申しましたとおり、大井どんたくでの大使館との関係、それから、今区が進めています、地域の方たちを巻き込んだオリンピック・パラリンピックに向けての英語力の向上等は、全て国際友好協会と品川区が連携して。","voiceIndex":226,"id":"exchange-095"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。実際に、当然、品川区の財政は日本で一番という状況もあるから、私どもはわかっていますけれども、これを見る人もなかなかいないかもしれないですけれども、見るときに、例えば平均的な基準はこうで、品川区の数字は高いですとか、いいですということをもっと表現してほしいというところがあるのですが、その辺をまず教えてください。","respondent":"本城企画財政課長","answer":"ただ、先ほど別の委員への答弁の中でもさせていただきましたが、ちょうど今年の１月に、総務大臣のほうから改めて全国的な共通基準に基づいて、きちんと平成２９年度の決算までに整理するということで、そのあたりが整理できると、現在やっています品川区の経営状況についても。","voiceIndex":228,"id":"exchange-096"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、確かにいい数字なのでしょうかけれども、そこら辺は何かもう少し、繰り返しになってしまって申し訳ないのですけれども、標準がないだけに難しいかもしれないけれども、そこら辺も気になっています。それからもう１点、建物などの老朽化の状況ということで、約４割が老朽化しているという部分があるのです。一緒に老朽化もあったので、老朽化の点、もしあればお答えいただきたいと思います。","respondent":"本城企画財政課長","answer":"ただ、建物の老朽化の状況などは、必ずしも相対的な評価でないと意味づけを与えられないわけではありませんので、このあたりは、今、パーセントでとどまっているものを、どういうふうに政策として課題があるのかとか、少なくともそういうようなことも含めて。","voiceIndex":230,"id":"exchange-097"},{"speaker":"鈴木（真）委員","kind":"確認","question":"時間が１分くらいなのですけれども、１点、ちょっと確認だけ。改正公共工事品質確保促進法、これが昨年６月に改正して、契約関係に関しても、いろいろなパターンができてくるというお話が出ていました。設計段階から施工業者が入ってくるような形もあるということも聞いているのですが、これからの契約に対して、何か考え方を検討中かどうか、そこだけ教えてください。","respondent":"立川経理課長","answer":"改正公共工事品質確保促進法では、新たな契約方式ということで、いろいろな実例が示されているところですので、区としましても、その辺については、今後、研究していきたいと考えているところです。","voiceIndex":232,"id":"exchange-098"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、１８３ページの防災センター運営費、それから時間があれば、１７５ページのこみゅにてぃぷらざ八潮の運営費について、お伺いします。一つは、多目的空間・シアターということで、今までも防災センターで行われていた３Ｄといいますか、映画をやっていましたが、イメージだと全面改修とおっしゃっていますが、あそこの画面はそのまま使うのかと思いまして、その辺を教えていただきたい。","respondent":"鈴木防災課長","answer":"ただし、今まで事務室等バックヤードで使っていた部分も含めて、全体的にレイアウトを変更することで、新たなスペースを少し捻出しまして、さまざまな体験コーナーを設置する予定で計画をしているものです。","voiceIndex":236,"id":"exchange-099"},{"speaker":"山元委員","kind":"質問","question":"約３億円ちょっと使うということで、かなりすごいものができるのだろうと楽しみにしております。平日はここを使わせていただいていて、今まで、お仕事をしている人は行きたくても来れなかった方が大勢いたのですが、今回新しく平成２８年からスタートするにあたって、土日についてはどのようにお考えになっているのでしょうか。","respondent":"鈴木防災課長","answer":"リニューアル後の開館についてですが、とりあえず現時点では、今までどおり平日を予定しております。と申しますのも、今度は体験型コーナーを複数設けますので、そのための安全管理の要員が必要になります。","voiceIndex":238,"id":"exchange-100"},{"speaker":"山元委員","kind":"質問・要望","question":"ある程度様子を見て、土日も可能なのかと期待しておりますので、よろしくお願いしたいと思います。特に今、町会とかもすごく皆様、防災グッズに対して興味がおありで、特に区で買うと少しお安くなるということもありまして、できれば、自分たちで触ってみて、こんな感じだとかという意味でも、触れるようなところに防災グッズを展示しているのかどうか、教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"防災グッズの展示についてのご質問ですが、まさに今ご質問いただいたように、現在も防災グッズの展示はしておりますが、実際に区民の方が触ったり、もしくは袋に詰めてみたり、体験できるという形の展示を考えておりまして、そのためのコーナーが、現在。","voiceIndex":240,"id":"exchange-101"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひ展示していただきたいと思います。この六つのブースですが、オープンすれば、多分小学生、中学生が来ると思いますけれども、実際に全部を体験した場合、どのくらいの所要時間がかかるのか、その辺も教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"個人でいらっしゃった場合には、その場で見学できる時間をお聞きして、適宜ご案内するようになりますが、団体に関しては、人数や希望するプログラムをお聞きしまして、その時間と内容等を合わせたものを組み立てて、体験や見学をしていただくというふうに。","voiceIndex":242,"id":"exchange-102"},{"speaker":"山元委員","kind":"意見","question":"もしくは、今言ったこのシアターを使って、画面を通してのそういう訴えというか、小さい子どもたちも大変な思いをして生き延びた、同世代の子どもたちもこんな思いをしたというような、何かそういうことを画面から訴えられるような、そういうお考えはありますか。","respondent":"鈴木防災課長","answer":"ご質問いただきました、体験を語っていただいたり、もしくは映像で伝えたりする内容に関してですが、建物や展示に関しての設計はもう今年度でほぼ終わっておりますが、具体的な展示の内容、それから映像等に関しては、４月以降に検討する予定でおりますので、その中で。","voiceIndex":244,"id":"exchange-103"},{"speaker":"山元委員","kind":"質問・要望","question":"時間がありますので、１７５ページのこみゅにてぃぷらざ八潮運営費のところでお伺いしたいと思います。今回、グラウンド人工芝生化工事費ということで、今度、あそこのグラウンドが芝生になるのかと思いますが、そこを教えていただきたい。それから、その下の非構造部材耐震化等工事費は、どこを工事するのか、教えていただきたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、新たに多目的に利用していただこうと思いまして、人工芝として計上させていただきました。そしてもう一つ、非構造部材の耐震化につきましては、八潮は避難所になってありますので、体育館の非構造部材の耐震化、または便所排水管の耐震工事等です。","voiceIndex":246,"id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問","question":"私からは、１４９ページ、総合教育会議費の問題と、１８５ページ、駅周辺帰宅困難者対策経費、固定電話の設置についてやりたいと思います。昨年６月に教育委員会制度を定める、地方教育行政の組織と運営に関する法律が改悪されました。２点目は、区長に教育大綱制定権を義務づけたこと。総合教育会議が設置されますけれども、この会議で区長と教育委員会はどのような関係になるのか、教えてください。","respondent":"江部総務課長","answer":"新しく始まります総合教育会議において、区長と教育委員会は対等の関係で、その中で協議を行うという立場にあります。","voiceIndex":249,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問","question":"対等の関係で協議をするということです。この場は公開の場であるというので、しっかりと見ていきたいと思っていますけれども、総合教育会議で取り扱う事項について、どのようなルールで決定をされていくのか、この点も教えてください。","respondent":"江部総務課長","answer":"協議題についてのお尋ねですが、基本的には、国のほうで想定しております３点、教育行政の大綱の策定、教育の条件整備など重点的に講ずべき施策、それから児童・生徒等の生命・身体の保護等緊急の場合に講ずべき措置について、協議題になっていくものです。","voiceIndex":251,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"大綱とは、自治体の教育の目標や施策の根本方針です。こうした大綱は、本来ならば、教育委員会と首長とが対等、平等の関係で協働し、また広範な住民の皆様、区民の方々の参加のもとで、民主的な策定をするべきところであると思っています。だからこそ、区長の権限が教育委員会の権限を侵さない、このためのルールが必要であると思いますが、この辺の歯どめというものはあるのでしょうか、教えてください。","respondent":"江部総務課長","answer":"大綱につきましては、教育委員会と首長との連携を強化し、地方における総合的な教育のあり方を定めていくものです。もちろん、総合教育会議の中で決定するということではなくて、協議する場です。","voiceIndex":253,"id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このことは、申し上げておきたいと思います。そして、「（中略）そのほかに考えられるものといたしましては、例えば、首長が自ら属する党派の主義主張に偏った教材を学校で使用する、あるいは、首長が自ら属する党派の主義主張に偏った教育の実施を求めようというようなことにつきましては、総合教育会議において協議をすべき事項ではないと考えております」と、６月１２日の前川局長の発言です。","respondent":"江部総務課長","answer":"午前中に、ほかの委員からのご質問にも答弁を申し上げましたけれども、ある程度統一的な見解では、少しぶれた経緯は確かにございましたが、その後、文部科学省のほうでもＱ＆Ａで項目を分けまして、方針と教科書採択そのものは違うという認識ですので、繰り返しですが。","voiceIndex":255,"id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問","question":"教科書採択と方針は違うという言い方をされましたけれども、採択に当たっての方針を出すということですよね。教育行政の法律上の権限といって、区長がやることは予算絡み、私学とか、教育財政の取得処分とか、契約予算の執行、子どもたちが学ぶよりよい環境をつくっていくのが区長の仕事であって、あとは教育委員会にしっかりと任せていく、このことが大事であると思いますが、いかがでしょうか。","respondent":"江部総務課長","answer":"なぜ首長が、ですけれども、それは教育委員会だけではなく、子育てとか、文化スポーツも含めた区全般における教育施策を有効に連携しようというのが今回の目的ですので、そこで話し合われるということは望ましいことであると理解しております。","voiceIndex":257,"id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問","question":"教科書の問題はとても大きな問題であると思うのです。私の母は、若い方々に接していて、お作法などを教えていたのですが、やはり軍国少女を育ててしまったということに対して、ずっと後でも後悔をしていましたけれども、それはこういう仕組みの中でつくられていったのだと思います。そのために、今回の制度は少しも役立たないと思いますが、いかがでしょうか。","respondent":"江部総務課長","answer":"教科書採択の方針につきましては、繰り返しですけれども、これは協議題とすることは、教育委員会との協議調整の中で可能であると考えております。","voiceIndex":259,"id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問","question":"方針を協議題にするということは、どういう意味なのですか。方針って何ですか。","respondent":"江部総務課長","answer":"方針は方針です。","voiceIndex":261,"id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"２点、お伺いしたいと思います。１点目が１７７ページの歴史館経費に関連して、２点目が１８１ページの防災対策において何点かお聞きしたいと思います。１７７ページの歴史館経費に関連してですけれども、実は先日、歴史館に行ってきました。歴史館の予算の中で、この３０周年における経費、特に何を見込んでいるのか、その辺についてお聞きしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"ご案内のとおり、歴史館は今年３０周年を迎えます。そんな中で、１７９ページの特別展示等経費、これが特別展ということで、東海道品川宿の特別展を行うのですけれども、ここに冠をつけて、ここでオープニングとか、そんなことを考えているところです。","voiceIndex":264,"id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"催し物はわかりましたけれども、学校でも周年行事だと、何とか記念ということで、いろいろパーティなどやりますけれども、この品川歴史館は、費用を取れるようなところではないですよね、７０歳以上無料だとか、障害者無料、小中学生は無料、あるいは取っても１００円、団体だと２割引きで、本当にお金を稼ぐ施設ではないですけれども、やはり３０周年を迎えた節目ですから。","respondent":"安藤文化スポーツ振興課長","answer":"少し答弁が漏れました。東海道品川宿の特別展のオープン記念ですけれども、その前の日に前夜祭と申しましょうか、関係各位を呼んで内覧会をやりまして、それも３０周年にふさわしいような内容を、これから考えていくところです。","voiceIndex":266,"id":"exchange-113"},{"speaker":"松澤委員","kind":"質問","question":"預かってもらった、そのついでにこの竹内重雄展を見させていただいたのですけれども、やはりすばらしいものです。収蔵庫というものを大事につくらなくてはいけないと思うのですが、これはほかの方も何回も質問しているのですけれども、この３０周年を機会に収蔵庫をしっかりとつくるべきではないかと思うのですが、この点のお考えをお聞きしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"その数は２万９,０００点以上にのぼってあります。そんな中で、歴史館の地下１階には民具とか生活用品等を保存しています。そして、２階のもう一つの収蔵庫には古文書だとか、浮世絵だとか、紙ベースのものを収蔵しています。","voiceIndex":268,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"おそらくそうだと思いますけれども、３０周年なのだから、この節目にしっかりとひとつ湿度、温度を調整したものを、そんな立派なものではなくても、いろいろいただいた収蔵品、絵画などですと、湿度も温度もいろいろ加味しなければいけないと思うのですけれども、それは今現在、一つくらいあるのですか、そのほかの収蔵品を保管するところ。今、再開発か何かで結構お部屋をいただいたりするではないですか。","respondent":"安藤文化スポーツ振興課長","answer":"３０周年を迎える期に、もう一度歴史館の運営等を我々区で考えます。そしてまた貴重な資料につきましては、専門委員もいますので、ご相談をしながらうまく保存していくように考えていきたいと思っています。","voiceIndex":270,"id":"exchange-115"},{"speaker":"松澤委員","kind":"意見","question":"防災対策のほうにいきます。大変に頼もしいと思うと同時に、やはりこういうようなもの、あるいはもっと小さな、大工さんとか、建設組合みたいな方とも防災協定を結ぶべきではないかということで、我々も常々そういう話をしています。今度、何かそういうことが進んでいるという話を聞いたのです。今どのような形で進んでいるのか、その辺を聞きたいと思います。","respondent":"鈴木防災課長","answer":"水防等のときにご協力をいただく機関や団体との協定ですが、ご指摘がありましたように、建設防災協議会には、日常の業務と、それから水防時の対応ということで、日々協力をいただいているところです。","voiceIndex":272,"id":"exchange-116"},{"speaker":"松澤委員","kind":"確認","question":"そうすると、今、小さな組合とも結びつつあるということでよろしいですか、確認しておきます。","respondent":"鈴木防災課長","answer":"現在、まだ組合単位ではないのですが、工務店単体でとか、そういう関係事業者との協定は幾つか結んでいるところです。","voiceIndex":274,"id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"時間がなくなってきたのですが、もう１点いいですか。１８３ページ、貯水槽等維持管理費、１１０万円ちょっと。これが、たくさんある貯水槽の維持管理の費用ということで、よろしいのでしょうか。","respondent":"鈴木防災課長","answer":"通常の貯水槽の維持管理、また修繕の部分も含んだ経費です。","voiceIndex":276,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がないので、要望だけ言っておきます。貯水槽は幾らつくっても、水というのは必要なものですから、今後とも貯水槽だけはどんどんつくっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-119"},{"speaker":"高橋委員","kind":"質問・要望","question":"先に、１４７ページの財政調整基金積立金について、お伺いします。少し疑問があるので、教えていただきたいと思います。平成２４年度という決算ベースで、ちょっと前なのですが、２３区平均の１４.５％、それくらいの積立てが、財政調整基金では必要ではないかと考えるのですが、本区の財政規模から見て、この財政調整基金の適正額、どのようにお考えでしょうか、お尋ねします。","respondent":"本城企画財政課長","answer":"そのくらいの規模を持つことで、仮に、先ほど申し上げました１００億円規模の減収のような事態に備え、２年分の予算を組み替えたりして状況対応ができると、考えているところです。","voiceIndex":280,"id":"exchange-120"},{"speaker":"高橋委員","kind":"質問","question":"標準財政規模の２０％を目途にということで、１００億円以上の減収の可能性が今までにあり、それに対応するためには、そこを崩すことよって、２年くらいもっていくというようなご説明が今ありました。そこからすると、もし仮にそういった大きなマイナスの経済変動があったときには、現在では厳しい状況なので、今後もそのような対応ができるような形で積み上げていくという認識でよろしいですか。","respondent":"本城企画財政課長","answer":"そういう意味で、財政調整基金については、現在の見通しとしては、そのようなものを持っておりまして、いろいろなタイプの基金がありますが、それぞれ目的別にいろいろな目途がありますので、基金間のバランスも考えながら、財政調整基金については。","voiceIndex":282,"id":"exchange-121"},{"speaker":"高橋委員","kind":"質問・要望","question":"数年前の調査では８割だったのですが、まだ１割しか浸透していない。地域の方にお尋ねしても、それは何ですかという声が多いです。そこで、来年の１月の交付開始までに、具体的にどのようなスケジュールで準備に入るのでしょうか。そして、その周知について、具体的にどのようにＰＲ活動を行っていくのでしょうか、お願いします。","respondent":"井浦戸籍住民課長","answer":"全体的な進め方のスケジュールとしましては、まず、平成２７年４月以降になりますと、住民基本台帳システムの改修を行いまして、平成２７年１０月に個人番号を付番いたしますので、それまでの間に、戸籍住民課としては、テスト、あるいは研修等々を行ってまいります。","voiceIndex":284,"id":"exchange-122"},{"speaker":"高橋委員","kind":"質問・要望","question":"より身近な形で区民の皆様に、ということであれば、地域センターでの交付とかは可能ではないでしょうか。その辺がいろいろな面で難しいとすると、そのあたりも検討していただきたいのですが、それについてはいかがでしょうか。それから、予算書では、工事請負費が１,２３８万円ですが、交付場所設置の工事が９５０万円余で、二百数十万円差があるのですが、その点。","respondent":"井浦戸籍住民課長","answer":"３番目の区民目線の周知という部分につきましては、やはり何といっても利便性、簡便性が向上するということで周知してまいりたいと考えています。","voiceIndex":286,"id":"exchange-123"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、１５１ページ、交流事業経費、１５９ページ、シティプロモーション推進経費、１７１ページ、品川区民芸術祭経費、時間があれば、１８３ページの小中学校消火ポンプ配備、また、１８５ページの防災区民組織育成費について、伺います。その中で、今年度内のスケジュール状況、もう今は３月ですけれども、どのようにされているのか、教えてください。１７１ページの品川区民芸術祭です。","respondent":"河内協働・国際担当課長、荒井広報広聴課長、安藤文化スポーツ振興課長","answer":"今、ご提示いたしております看板の文面ですが、まだ案文ということで、ただ具体的なイメージがありませんとなかなか進んでいかないということで、今後。総務委員会での議論を受けて変えてきたものといいますか、さらに内部的に検討いたしまして、一つ進めさせていただいたかと思っているところですが、一つは。そしてもう一つは、２年前になりますが、東海道四百年祭を記念して行いましたしながわ物語、実行委員長でもあります小川先生がつくったものを。","voiceIndex":289,"id":"exchange-124"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは中学校から今度は小学校まで配備していただいて、本当に心強いと思うのですが、せっかく配備をしていただいている中で、もう一歩踏み込んでいただきたいのは、せっかく学校にありますので、今、教師の皆様はさまざまなことをやられていて、非常に負担も多い中だとは思うのですが、できる限り負担をなくしながらも、例えば研修という形でもいいのかと思いますので、ぜひ学校の先生たちも。","respondent":"鈴木防災課長","answer":"万が一のときには、その操作方法を知っている方が高齢の方であっても、近くにいる若い方に指示をして、活用していただくというような方法もありますので、いろいろな形で効果的に使っていただけるようにしていきたいと考えております。","voiceIndex":293,"id":"exchange-125"},{"speaker":"石田（し）委員","kind":"意見","question":"消火ポンプの件は、今、生徒たちが組んで一緒に防災訓練のときにお披露目をしていますが、例えば、それの教師版みたいなものがあったら、また地域の方とも盛り上がるのではないかと思いますので、ぜひご検討をよろしくお願いします。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":295,"id":"exchange-126"},{"speaker":"浅野委員","kind":"質問","question":"１４７ページ、番号制度対応経費、１９５ページ、個人番号カード経費、それから１８３ページ、災害時要援護者支援経費と、１６３ページの公有財産管理費について、質問します。そのうちの６９％、約７割が既に対応していると回答したそうですが、品川区はどのような回答をされたのか、品川区の現状について教えてください。","respondent":"井浦戸籍住民課長","answer":"実施率としては１００％です。","voiceIndex":297,"id":"exchange-127"},{"speaker":"浅野委員","kind":"質問","question":"実施率が１００％ということは、この７割の中に入っているということかと思います。この件に関しましては、総務省は４年前に、もう既に部屋番号の記載の徹底を自治体に要請をしていたということですので、適切に進めてこられたということかと思います。少しお伺いしたいのは、正確な住所という言葉がよく使われているのですけれども、この定義はどのようになるのか、教えてください。","respondent":"井浦戸籍住民課長","answer":"住所の法律的な定義につきましては、住居表示法に定めがございまして、まず都道府県から始まり、町丁名、それから街区符号というのが真ん中の番号です。そして最後の番号が住居番号で、さらに部屋番号というもので完全な住所となるものです。","voiceIndex":299,"id":"exchange-128"},{"speaker":"浅野委員","kind":"質問・要望","question":"個人を特定できるカードですので、間違ったところに行ってしまったとか、そういうことがないように、これからも転入や転出とかさまざまあるかと思いますけれども、その都度、確認をしつつ、正確な住所を管理していただくようにお願いします。昨年度の数字で結構ですので、調査対象者の件数、返送された件数、返送率を教えていただきたい。","respondent":"鈴木防災課長","answer":"実績についてですが、最近５年間の状況で見ますと、大体毎年１,８００から２,０００件程度通知をお送りしまして、大体４０％くらいの方からお返事をいただいております。そのうち、さらに６５％くらいの方からは登録の意思表示をいただきまして、登録をしています。","voiceIndex":301,"id":"exchange-129"},{"speaker":"浅野委員","kind":"質問","question":"返送されなかった方について、さらなる対応というのはされているのか、また再度送付したりとか、または直接訪問するとか、そのようなことはされているのか、教えてください。","respondent":"鈴木防災課長","answer":"お返事をいただけなかった対象の方につきましては、対象の要件から外れない限りは、毎年１年に１回一斉にお送りするお知らせで、引き続き、繰り返し呼びかけをしております。防災訓練やいろいろな場面で、登録のお願いのお話もさせていただいているところです。","voiceIndex":303,"id":"exchange-130"},{"speaker":"浅野委員","kind":"質問","question":"引き続き、この名簿の精度をアップしますよう、お願いしたいと思います。避難誘導ワークショップについて、これは議会でも質問させていただいたのですけれども、１回も実施していない町会・自治会が５６あると答弁いただいたと思います。今後、どのような形で動機づけをしていくのか、実施に向けた取組みについて教えてください。","respondent":"鈴木防災課長","answer":"その促進のためには、防災アドバイザー研修、それからその研修を終えられた方のステップアップ研修、この中でも、避難誘導のワークショップを中心に実技をやっていただいたり、いろいろな情報提供もしておりまして、その方たちが地域に戻られて。","voiceIndex":305,"id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"一人でも多くの方を、というか全員を助けなければならないのですけれども、訓練というのは非常に重要だと思いますので、引き続き要援護者の支援をよろしくお願いしたいと思います。続きまして、１６３ページの普通財産非構造部材等耐震化工事費について、質問します。耐震化を全て完了する予定はいつになっているのかについても、教えてください。","respondent":"立川経理課長","answer":"こちらは、旧八潮北小学校と旧荏原第四中学校でございまして、旧八潮北小学校につきましては、トイレと排水管部分の耐震化です。旧八潮北小学校、旧荏原第四中学校は、天井部分の耐震化です。","voiceIndex":307,"id":"exchange-132"},{"speaker":"浅野委員","kind":"質問","question":"これらの工事は、今年度中に全て終わるのかどうかということと、あとは全体的に見て、まだまだ非構造部材の耐震化が終わっていないという施設はあるのかどうか、今後の計画があれば教えてください。","respondent":"小林施設整備課長","answer":"平成２６年度は、主に避難所であります小学校、中学校並びにその小学校、中学校から外れました避難所の、今申し上げましたマイスクール八潮とか、旧荏原第四中学校、そちらのほうの体育館並びに校舎の非構造部材の点検を行いました。","voiceIndex":309,"id":"exchange-133"},{"speaker":"須藤委員","kind":"質問・要望","question":"１４９ページの総合教育会議費に関連して、お尋ねします。そのことで、より発展するということが、どういうことなのだろうかと。今までの教育委員との懇談会を通じてどういう形で前に進んでいくのか、今度の会議ができてどういう形になるのか、それぞれ区長、教育長のお考えがあればお聞かせいただきたいと思います。","respondent":"江部総務課長","answer":"先ほどの繰り返しですけれども、それによって、教育委員会の教育に加え、子育て、文化・スポーツを含めた区政全体における教育に係わる施策の連携がとれて、総合的な施策展開につながっていくというふうに考えています。","voiceIndex":312,"id":"exchange-134"},{"speaker":"須藤委員","kind":"質問","question":"もともとこういった形は、教育委員会ができていて、いろいろな話がありました。そうでなければ、国に先んじてというような表現で、施政方針で述べてはこないと思うのです。そういったよさをお互いに持って、そしてなおかつ責任はきちんと私のほうが取りますというものができてきて、教育行政というものが前へしっかり進んでいくのだろうというふうに思っているのですけれども、この意見でいかがでしょうか。","respondent":"濱野区長","answer":"国語、算数、理科、社会の教科内容について、あるいは事細かな教科内容について、口を差し挟む考えはありませんけれども、学校というものの存在がどういうものなのかということについては、常に発言をしてまいりましたし、今後も発言をしてまいりたいと考えています。","voiceIndex":314,"id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"続きまして、１５７ページの広報広聴費でお聞きしたいのですが、今、企業とか町場では、クレーマーという、いわゆるいろいろクレームをつけてくるというので、その対応が非常に大変だと聞いているのですけれども、広報広聴という、まさに聴くところで、いろいろな話が来るのだろうと思うのですけれども、そのあたりで、クレーマー的な問題というか、そういうひどい例があるのか、どうでしょうか、ありますか。","respondent":"荒井広報広聴課長","answer":"ただ、それぞれ個別の事例につきましては、個別の所管で対応していただくようにお願いしていますが、やはりそれぞれのところでかなり苦労しているという話は伺いますし、またそれに対して広報広聴の窓口としても相談に乗って、一緒に対応している状況があります。","voiceIndex":316,"id":"exchange-136"},{"speaker":"須藤委員","kind":"質問","question":"そういう対応を、区民サービスという形になるのでしょうけれども、きちんと説明できる状況の部署の人と、そうではない担当というのが出てきてしまうと思うので、そのあたりも配慮をしていただければと思うのですが、いかがでしょうか。それから、今みたいにクレーマーがきて、担当の方が非常に心身を壊したというような状況には、こういう自賠責みたいなものが使えるのかどうか、教えてください。","respondent":"荒井広報広聴課長、江部総務課長","answer":"そういったものに対して、一定程度毅然とした態度といいますか、きちんとした説明を尽くすように努めているところです。特別区自賠責の考え方ですけれども、発生いたしました損害に対して、２３区で共同で保険をかけているものです。","voiceIndex":318,"id":"exchange-137"},{"speaker":"須藤委員","kind":"質問","question":"自賠責の中で、今言ったクレーマーみたいなもので、職員が体調を壊してしまった、どうにかなってしまったというときの補償、保険みたいなものが出るのかという質問をしたのですけれども。それはまた全然別で考えていくのか。","respondent":"江部総務課長","answer":"公務員が損害を被った場合は、公務災害という考え方ですので、自賠責とは違うと思います。","voiceIndex":321,"id":"exchange-138"},{"speaker":"須藤委員","kind":"質問","question":"全庁共通プロジェクトというのが、これだけなのか。それとも、これは総務費のところだからこの四つだけなのか、全庁共通でやるといえば、教育しかり、健康問題にしても、少子高齢化云々といろいろあるだろうと思うのですけれども、全庁共通プロジェクト推進経費に載っているのは総務費のところだけだろうと思うのですけれども、全庁共通のプロジェクトはほかにもあるのかどうか、教えてください。","respondent":"柏原行財政改革担当課長","answer":"全庁共通プロジェクトの予算の考え方ということであろうかと思います。","voiceIndex":323,"id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"公共施設等総合管理計画策定委託というのがあるのだけれども、その上に、区有施設改修工事設計等委託というのがありますけど、公共施設と区有施設で、片方は改修の委託を計画しています、こちらは管理しますと、そのあたりを総合的に見ていかないと、これは改修した後の管理という話になってくるのだろうと思うのですけれども、そのあたりを含めて、前段に載っているものを含めて。","respondent":"柏原行財政改革担当課長","answer":"ただ、基本的には区の考え方をお伝えしながら事業を進めていくというもので、国家戦略特区を考えてあります。それから、区有施設、公共施設の部分です。公共施設、これは全体の総合管理ということで、改修も含めた形で、今後の先を見た中での考えでやっていこうと思っています。","voiceIndex":325,"id":"exchange-140"},{"speaker":"須藤委員","kind":"質問","question":"それはどうでしょうかということが一つ。それから、これを続けてやっても、オリンピック・パラリンピックが終わってがくんときてしまうという空虚なものが、前回のオリンピックのときにあったと思うので、そのあたりの点について、お考えをお聞かせください。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"それが終わってから、皆様ががくんと落ちてしまうのではないかですが、今回のオリンピックにつきましては、その後のレガシーということを大変重要視しているものですので、そういったことを踏まえて、区といたしましても、オリンピックはオリンピックで最大の目標ではありますが。","voiceIndex":327,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"私は、１４６ページ、総務費全般の中で、契約スライド条項制度についてお聞きしたいと思います。この制度が、単品スライド条項、インフレスライド条項と言われていると思いますが、民間企業と民間建設業者との間には、このようなスライド条項の適用はないと思いますが、自治体と民間業者とのこういう入札制度においてはあるのですが、これは特別なものなのでしょうか、教えてください。","respondent":"立川経理課長","answer":"スライド条項ですが、こちらは、いわゆる工事契約を結ぶ場合に、契約約款に決められた内容です。民間の状況ですけれども、民間は民間なりに民民での話し合い等とか、そういったことで、いわゆる物価上昇等に対して対処していると聞いているところです。","voiceIndex":330,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"民間では、こういうスライド条項が基本的にありませんので、契約時点で、資材が値上る前に資材の発注をしたり、急騰する可能性がある場合は、その値上がり分をあらかじめ見積りに載せたりして対応しています。区と契約する、入札に参加する業者は、経済状況の変化に対応する術を知らないのでしょうか。なぜこの業界だけが対応できないのか、教えてください。民間ではきちんとやっていると、私は聞いています。","respondent":"立川経理課長","answer":"スライド条項の適用ですけれども、いわゆる残工事期間が２カ月以上あり、急激な価格変動等に対処するというのがインフレスライド条項です。こうした状況がある場合については、民間もそれなりの対応をしていると認識しています。","voiceIndex":332,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"かみ合わなくて恐縮ですが、民間では、ほとんどやっていません。あらかじめ見積りに上乗せしたり、契約と同時に資材を発注すれば、その分に対しての資材の高騰に関して、値上がりしたから上げてくださいという、資材メーカーからの要請はないようにできております。民間は民間できちんとやっているのに、何で行政はできないのでしょうか。もう一度、お聞かせください。","respondent":"立川経理課長","answer":"委員ご指摘のありました、民間では、あらかじめいわゆる物価の上昇等について見込んで契約しているですけれども、行政の公共工事におきましては、最新のいわゆる積算単価等を用いて、それを根拠に予定価格を定めておりますので。","voiceIndex":334,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"今、民間の話も出ましたが、区でもそうだと思うのです。例えば、今、区と業者が入札して、契約しましたと。民間はみんな苦労しているわけだから、では、その人たちにも補てんすべきではないですか、同じ区内産業だから。それを、自分たちは、そうやって上がってしまったから、上げますというのだったら、ちょっと筋が通らないと思うのですが、いかがですか。","respondent":"立川経理課長","answer":"インフレスライド条項の適用に関してですけれども、こちらにつきまして、具体的にどういった事例について適用しているかですが、ここ２年くらい、いわゆる設計労務単価の上昇が大幅であったということで、主に労務費に関してスライド条項が適用されたと、区では認識しています。","voiceIndex":336,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"今、労務単価ときましたが、資材は、実際確かに値上がりしています。もう１点、お聞きます。今、単品スライドがありました、スライド条項もありました、では今度値下がりしたらどうするのですか。下げてくれているのですか。総務委員会でもあまり聞かないのですけれども、こうやって契約金額が下がったのですか、これはどうなのですか、もしこっちはやってなかったら、おかしくありませんか、教えてください。","respondent":"立川経理課長","answer":"資材価格についてですけれども、資材価格につきましては、おおむね１年ほど前から、全体としましては、価格変動については、急激なものはございません。ある意味、高どまりというような状況ですので、落ち着いた状況になっているところです。","voiceIndex":338,"id":"exchange-146"},{"speaker":"須貝委員","kind":"提案","question":"あまりやるつもりはなかったのですけれども、でも実際に契約が下がった案件について、総務委員会のほうで、区議会で認めてくださいという事例は、私は聞いてないのですけれども、実際に下がっているのですか。区議会に、そういうふうに議案として提案しているのですか。","respondent":"立川経理課長","answer":"下げたことがないですが、急激な物価変動という意味で、急激に物価が下がったといったことが、実際になかったです。","voiceIndex":340,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり同じ区内の業種、業界、いろいろな産業ですから、平等にやっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":342,"id":"exchange-148"},{"speaker":"南委員","kind":"質問","question":"はじめに、先ほど、区長が首長として意見を言うべきだと思っているというふうに発言されました。私は、これは本当に残念な発言だと受けとめました。それから、１４７ページの番号制度対応経費について、マイナンバーのことについて、伺いたいと思います。それから、この制度が導入されることによって、どんな効果があるのか、導入の目的は何なのか、まずそれを伺いたいと思います。","respondent":"秋山情報システム課長","answer":"そういうことが、番号によって効率的に個人が特定できるようになるということで、行政の効率化が進んでくるです。それから、国民の利便性の向上ですが、先ほどもご説明させていただきました、番号によって情報の連携をすることにより、添付書類の省略ができるということ。","voiceIndex":344,"id":"exchange-149"},{"speaker":"南委員","kind":"確認","question":"費用については、平成２６年度、平成２７年度の２年間で２億４,６００万円ということでいいのかどうかを確認したいと思います。この調査について、このような結果になっていること、これだけの数字が紹介されたことについて、区はどのように認識をしておられるのか、それについて伺いたいと思います。","respondent":"秋山情報システム課長","answer":"これは国全体で法案として成立したものですので、品川区としては粛々と進めていくという考えです。","voiceIndex":346,"id":"exchange-150"},{"speaker":"南委員","kind":"質問","question":"多額な税金が使われているということ、国民の中で、多くの人たちが、プライバシーを危険にさらす仕組み、こういうことを実感して不安を感じているという、こういう状況。こういう中で、私は進めていくべきではないと思っているのです。日本で起きない保証はないと思うのです。ここについて、どのような見解を持つのか伺いたいと思います。この点についての見解を伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"内閣府が今年の１月に実施しました世論調査について、補足させていただきたいと思います。","voiceIndex":348,"id":"exchange-151"},{"speaker":"南委員","kind":"意見","question":"でも、私は芋づる式に情報が全部さらけ出されてしまう危険のあるものはやめるべきだと、こういうふうに思います。ぜひそういう立場でいてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":350,"id":"exchange-152"},{"speaker":"いながわ委員","kind":"質問","question":"その辺がどうしてなのかということ。そこの中延特別養護老人ホームでは、担当の人に聞いたら、年に２回くらいはこうしたことをやっていますということなのですが、おそらく行政がかかわっている社会福祉法人とかいろいろあると思うのですが、そういった障害者施設とか高齢者施設の防災訓練というのを、防災課として把握されているのか、今後どういう状況であるべきかということを、教えてください。","respondent":"小林施設整備課長、鈴木防災課長","answer":"荏原文化センターの非構造部材の物件が入っていないということにつきましては、１７７ページの大ホール天井改修等工事の「等」の中に非構造部材が入っておりますので、平成２７年度に最終の段階で発注をかけまして。福祉施設と高齢者福祉課や障害者福祉課、主管課との連携ということで、通信訓練を行ったりということで、関連する施設と連携をしながら、主体として各施設で訓練を行っていただいているというのが現状です。","voiceIndex":352,"id":"exchange-153"},{"speaker":"いながわ委員","kind":"質問・要望","question":"荏原文化センターに関して、平成２５年度に耐震改修の実施設計の委託が始まって、平成２６年度にいろいろやりながら、実際にこの吊り天井とか、特定天井というのですか、それが始まったのが平成２６年４月施行予定と書いてあるのですが、ここは確認が取れていないのですが、その流れの中で、少し心配していたのが、「等」の中に入っているからそれはいいのですけれども、それがなくて。","respondent":"鈴木防災課長、加藤防災安全担当課長、稲田道路課長","answer":"ただ、もう一つ福祉施設につきましては、区の福祉避難所の位置づけを協定でお願いしておりますので、そちらの面でのマニュアル作成だとか、訓練についても。消防の設備、それから訓練についてですけれども、先ほどお話のあった２回の訓練、あるいは消防の自衛消防訓練を兼ねた防災訓練かということも考えられます。ご指摘のガードパイプですが、これはもうご存じのように、交通安全、歩行者の安全を守るということで、飛び出しや横断抑止というところで設置しております。","voiceIndex":355,"id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問・要望","question":"はじめの西大井駅周辺サイン設置等工事ですが、これの具体的な内容を教えてください。それから、２点目の分散備蓄計画策定委託については、区の備蓄倉庫が西大井のＪタワーの中に、実はあるのですけれども、そこには備蓄品が入っていないというお声があるのですが、それの事実確認と、もし入っていないとすれば、なぜなのか教えていただきたいと思います。","respondent":"荒井広報広聴課長、鈴木防災課長、工藤選挙管理委員会事務局長","answer":"こちらにつきましては、西大井駅から大井第三地域センター、あるいはウェルカムセンター原への道順を示すためにサインを設置するものです。各スタンドの責任者にも集まっていただきまして、説明会を開催して、実際の備蓄例の報告もいただいておりますので、今回の報道にあった都のように。いずれにしまして、増える若年層に対しての主権者意識の向上という部分に努めてまいりたいと考えています。","voiceIndex":361,"id":"exchange-155"},{"speaker":"たけうち委員","kind":"質問・要望","question":"Ｊタワーについては、今、防災課長は幾つか入っているとおっしゃったけれども、その住民の方は、区の防災倉庫なのに全くないというような言い方をしているので、私は確認していないのですけれども、そういう中で、実際に４年前の東日本大震災のときにも、帰宅困難者があそこに来たという中で、やはり一定程度受け入れざるを得ない中で、せっかく区の備蓄倉庫があるのに。","respondent":"荒井広報広聴課長、鈴木防災課長","answer":"門の前に案内をつけたらどうかというご意見ですが、これにつきましては、文化財として一般公開を年に何回かさせていただいているところもありますので、文化財担当。Ｊタワーの倉庫についてですが、ご指摘がありましたように、住民の方もいろいろ心配をしたり、また受入れについて考えていただいているですので、しっかりとした情報提供と、またご協力いただける内容について。","voiceIndex":365,"id":"exchange-156"},{"speaker":"伊藤委員","kind":"質問","question":"私は、１６７ページ、客引き防止パトロール隊活動費に関して、それから、１８１ページ、防災体制整備費に関連して、それから１７７ページ、五反田宇宙ミュージアムに関連して質問します。非常に迷惑なのだけれども、こういう方々に対して、この条例で何か対応できないかという相談を受けたのですが、改めて答弁をお願いいたします。","respondent":"上垣外生活安全担当課長","answer":"さらに加えまして、この営業の内容にかかわらず、執拗な客引き、スカウト行為についても、あわせて規制の対象にしておるところです。","voiceIndex":369,"id":"exchange-157"},{"speaker":"伊藤委員","kind":"質問","question":"要はこういう行為について迷惑だということなのです。そういう行為があったということだけ指摘をしておきます。プラネタリウムの事業をずっと展開していくのであれば、継続した事業をやっていくべきだと思うのです。例えば一つの記念イベントなのかもしれないけれども、どうもこれだけが突出しているイメージがあるのですが、いかがでしょうか、あわせて答弁をお願いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、品川区の子どもたちにも宇宙の夢をということで、五反田文化センターを宇宙の基地に発信をしていきたいと考えています。","voiceIndex":371,"id":"exchange-158"},{"speaker":"伊藤委員","kind":"質問","question":"その方向性は間違いなく正しいのだけれども、これがすごく突出しているイメージがあるのです。だから、これはやっていただいていいのですが、だけれども、それをどうやって継続していくのですかということだと思うのですが、もう１回答弁をお願いします。","respondent":"安藤文化スポーツ振興課長","answer":"これは初めての試みです。今回、これをぜひ成功させまして、継続性を持たせていきたいと考えています。","voiceIndex":373,"id":"exchange-159"},{"speaker":"伊藤委員","kind":"確認","question":"そこなのですが、宇宙に関心を持っていただくことは大切なことであるし、プラネタリウムを使うことは、当然必要である。３.１１の震災のことを改めて勉強する中で、あの被害の恐ろしさを改めて痛感したわけであります。となれば、では果たして品川区としてはどういう体制で自衛隊の協力を得ていくのでしょうか、という確認をお願いいたします。","respondent":"堀越人事課長","answer":"現在、さらに対策を強化していくという観点から、人事の部分ですが、自衛隊幹部職員ＯＢを部長級職員としての採用を予定しておりまして、豊富な経験、危機対応能力の活用ということで、現在、具体的に自衛隊と調整をしています。","voiceIndex":375,"id":"exchange-160"},{"speaker":"伊藤委員","kind":"質問","question":"昨日の勉強会の中で出た話が、品川区を担当する部隊の人数が全部で１５０名だそうです。５区ですから、１区当たり３０名。","respondent":"鈴木防災課長","answer":"実際に、東京都のほうも、現在、東京都の災害対策本部で、自衛隊をキーに連携をうまくするために、市町村との連絡調整窓口を新たに設置しているという状況もございまして、今後も、自衛隊と東京都と区と連携しまして、しっかりした体制強化に取り組んでいきたいと考えております。","voiceIndex":377,"id":"exchange-161"},{"speaker":"伊藤委員","kind":"意見","question":"人事課長の答弁の中では、部長級で来ていただくと聞きましたけれども、その方が品川区としっかりと連携を取っていただいて、そういう大きな組織の協力を得ていくということは、災害時には非常に頼りになると思うので、部長級で来ていただく方との連携をどのように取っていくのかということについてだけ、答弁をお願いいたします。","respondent":"堀越人事課長","answer":"災害時においては、区の中では区長、防災まちづくり事業部長と連携して、自衛隊との連携、災害派遣の具体的な構造、派遣の受入れをしたときにより機動的に迅速に災害対策に対応できるような、そういう技術的な面、経験、知識を具体的に活用していただくと。","voiceIndex":379,"id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1022#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":117427,"voices":381}}]);
